local config = {
  ui_story_5043_50430101_1_dialog_content = "<color=#e8d9bb>El Salón de la Justicia, Jardines de Lumopolis</color>",
  ui_story_5043_50430101_2_dialog_content = "¡Su Señoría, ese no es el caso!",
  ui_story_5043_50430101_3_dialog_content = "Lo juro por el Dios de la Luz, no le he mentido en asuntos del corazón.",
  ui_story_5043_50430101_4_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5043_50430101_5_dialog_content = "Orden en la corte! El demandado se abstendrá de interrumpir al demandante.",
  ui_story_5043_50430101_6_dialog_content = "Continúe, juez Leyn.",
  ui_story_5043_50430101_7_dialog_content = "Señorita, acaba de decir que el demandante no cumplió con sus deberes como su prometido durante el período de su compromiso. ¿Es eso correcto?",
  ui_story_5043_50430101_8_dialog_content = "¡Es!",
  ui_story_5043_50430101_9_dialog_content = "Puede hacer una declaración final antes de que el tribunal comience sus deliberaciones.",
  ui_story_5043_50430101_10_dialog_content = "El Día de la Corona de Luna del mes pasado fue el aniversario de siete meses de nuestro compromiso.",
  ui_story_5043_50430101_11_dialog_content = "¡Pero a ese bueno para nada ni siquiera le importaba!",
  ui_story_5043_50430101_12_dialog_content = "Oh por favor. ¡No puedes esperar que celebre nuestro compromiso todos los meses!",
  ui_story_5043_50430101_13_dialog_content = "Yo podría no haber objetado. ¡Pero te las arreglaste para comprar regalos diferentes para otras personas!",
  ui_story_5043_50430101_14_dialog_content = "Espera un minuto. Ya expliqué, esos eran para conexiones de negocios de mi familia—",
  ui_story_5043_50430101_15_dialog_content = "H-Espera! No empieces a discutir, ahora...",
  ui_story_5043_50430101_16_dialog_content = "<size=30>Tina, usted es un juez ahora. ¡Actúa como uno!</size>",
  ui_story_5043_50430101_17_dialog_content = "<size=30>¡Oh, sí, es cierto! Soy. Está bien, mira esto. Ejem...</size>",
  ui_story_5043_50430101_18_dialog_content = "<size=45>¡Orden orden!</size>",
  ui_story_5043_50430101_19_dialog_content = "<color=#e8d9bb>*multitud murmurando*</color>",
  ui_story_5043_50430101_20_dialog_content = "(Lo que quiero saber es por qué estoy sentado aquí escuchando una riña de amantes...)",
  ui_story_5043_50430101_21_dialog_content = "poniéndome impaciente, PlayerName? Estás empezando a parecer aburrido.",
  ui_story_5043_50430101_22_dialog_content = "¿Por qué a mi? Para nada... Oh, está bien, tienes razón como siempre, Carleen.",
  ui_story_5043_50430101_23_dialog_content = "Para ser honesto, siento exactamente lo mismo.",
  ui_story_5043_50430101_24_dialog_content = "Pero a diferencia de ti, no puedo dejar que se note. Después de todo-",
  ui_story_5043_50430101_25_dialog_content = "Lo sé. Hasta cierto punto, se reflejaría mal en el Señor de la Ciudad allí.",
  ui_story_5043_50430101_26_dialog_content = "...",
  ui_story_5043_50430101_27_dialog_content = "Hasta el momento no ha dicho nada.",
  ui_story_5043_50430101_28_dialog_content = "Lo siento. Inicialmente quería que vinieras a Lumopolis Gardens para dar un informe sobre tus aventuras en Longzhou.",
  ui_story_5043_50430101_29_dialog_content = "Pero parece que el Señor de la Ciudad no podrá perder el tiempo.",
  ui_story_5043_50430101_30_dialog_content = "No es problema. No es como si tuviera algo urgente que hacer.",
  ui_story_5043_50430101_31_dialog_content = "<size=30>Y para ser honesto, realmente no quiero volver a entrar en una de esas solemnes salas de conferencias...</size>",
  ui_story_5043_50430101_32_dialog_content = "Lo siento, ¿qué?",
  ui_story_5043_50430101_33_dialog_content = "¡Nada!",
  ui_story_5043_50430101_34_dialog_content = "(Ahora que lo pienso, no he estado aquí desde que <color=#FFB400>incidente</color>...)",
  ui_story_5043_50430101_35_dialog_content = "(Irridon estaba sentada donde está ahora, leyendo el veredicto del Salón de Justicia sobre Carleen.)",
  ui_story_5043_50430101_36_dialog_content = "(Y Carleen... bueno, ella ha cambiado mucho desde entonces.)",
  ui_story_5043_50430101_37_dialog_content = "PlayerName, ¿estás soñando despierto?",
  ui_story_5043_50430101_38_dialog_content = "Uhm, bueno... Estaba pensando...",
  ui_story_5043_50430101_39_dialog_content = "¡Estaba pensando en el efecto que tiene el Día de la Corona Lunar en Lumopolis!",
  ui_story_5043_50430101_40_dialog_content = "Sí, este tipo de cosas son comunes en esta época del año.",
  ui_story_5043_50430101_41_dialog_content = "A medida que los hombres y mujeres jóvenes disfrutan de la atmósfera de Mooncrown, algunos comienzan nuevos romances y, a veces, se forman grietas en las relaciones existentes.",
  ui_story_5043_50430101_42_dialog_content = "Luego, están los nobles decadentes que tienden a intentar pensar en formas de hacer que el entretenimiento dure el mayor tiempo posible.",
  ui_story_5043_50430101_43_dialog_content = "Como resultado, el Salón de la Justicia termina con un montón de disputas de relaciones que manejar.",
  ui_story_5043_50430101_44_dialog_content = "El Señor de la Ciudad se sienta a escuchar con más frecuencia de lo habitual, para evitar que ocurran posibles situaciones sin precedentes o que se salgan de control.",
  ui_story_5043_50430101_45_dialog_content = "De todos modos, disfruto más sentarme aquí en la audiencia que sentarme en la silla del acusado.",
  ui_story_5043_50430101_46_dialog_content = "Carleen...",
  ui_story_5043_50430101_47_dialog_content = "<color=#e8d9bb>¡Tom, tom, tom!</color>",
  ui_story_5043_50430101_48_dialog_content = "<size=45>¡Orden!</size>",
  ui_story_5043_50430101_49_dialog_content = "¡Con todo, fue malo e imperdonable!",
  ui_story_5043_50430101_50_dialog_content = "¡Por lo tanto, solicito a la corte que termine nuestro compromiso!",
  ui_story_5043_50430101_51_dialog_content = "Jejeje Estimado demandante, ciertamente entiendo de dónde viene.",
  ui_story_5043_50430101_52_dialog_content = "Según tengo entendido, este fue un arreglo de larga data entre sus familias. Y tú y el acusado eran novios desde la infancia.",
  ui_story_5043_50430101_53_dialog_content = "Lo cual tiene sentido. Es difícil imaginar a un hombre como el acusado ganándose el corazón de una bella dama como usted sin tales ventajas.",
  ui_story_5043_50430101_54_dialog_content = "Tienes razón. Crecimos juntos, por eso lo conozco mejor que nadie.",
  ui_story_5043_50430101_55_dialog_content = "Que envidiable. Vaya, estoy casi celoso del acusado.",
  ui_story_5043_50430101_56_dialog_content = "(¡¿Qué?! ¡Este juez es un poco espeluznante!)",
  ui_story_5043_50430101_57_dialog_content = "J-Juez Schwab...",
  ui_story_5043_50430101_58_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5043_50430101_59_dialog_content = "Juez Schwab, por favor mantenga su profesionalismo.",
  ui_story_5043_50430101_60_dialog_content = "Después de todo, ni yo ni el juez principal tenemos conocimiento del carácter del acusado.",
  ui_story_5043_50430101_61_dialog_content = "Todo lo que podemos determinar es que debe haber llegado a su decisión después de una gran consideración basada en la cantidad de años que lo conoce.",
  ui_story_5043_50430101_62_dialog_content = "Eh...?",
  ui_story_5043_50430101_63_dialog_content = "(Heh. Ella se enamoró de eso.)",
  ui_story_5043_50430101_64_dialog_content = "eh, yo...",
  ui_story_5043_50430101_65_dialog_content = "Acusado, ¿tiene algo que decir ante el juez presidente? Irridon da el veredicto?",
  ui_story_5043_50430101_66_dialog_content = "<size=45>¡Mi amor! ¡Siempre has sido el único para mí!</size>",
  ui_story_5043_50430101_67_dialog_content = "C-Cómo puedes decir esas cosas aquí...",
  ui_story_5043_50430101_68_dialog_content = "Muy bien. Y después-",
  ui_story_5043_50430101_69_dialog_content = "<size=45>¡Espera!</size>",
  ui_story_5043_50430101_70_dialog_content = "Lo lamento. Pero lo he reconsiderado.",
  ui_story_5043_50430101_71_dialog_content = "Yo deseo <color=#FFB400>retirar</color> mi caso.",
  ui_story_5043_50430101_72_dialog_content = "(¿Qué, solo así?)",
  ui_story_5043_50430101_73_dialog_content = "Lo siento de verdad. No pude considerar mis acciones completamente. Deberíamos haber resuelto nuestros malentendidos nosotros mismos.",
  ui_story_5043_50430101_74_dialog_content = "No. Es mi culpa por no ser más amoroso. Soy yo quien te ha hecho mal.",
  ui_story_5043_50430101_75_dialog_content = "Solicitud rechazada. Los procesos judiciales deben ser respetados. Hay formalidades que deben seguirse tanto al presentar un caso como al retirarlo.",
  ui_story_5043_50430101_76_dialog_content = "Pero hay una manera más fácil de manejar esto.",
  ui_story_5043_50430101_77_dialog_content = "Encuentro al acusado—",
  ui_story_5043_50430101_78_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5043_50430101_79_dialog_content = "-¡no culpable!",
  ui_story_5043_50430101_80_dialog_content = "¡Querido!",
  ui_story_5043_50430101_81_dialog_content = "¡Dulzura! Ven, vamos a tomar el té de la tarde...",
  ui_story_5043_50430101_82_dialog_content = "Caso cerrado. Se suspende el juicio.",
  ui_story_5043_50430101_83_dialog_content = "¡Señor Schwab, por favor espere!",
  ui_story_5043_50430101_84_dialog_content = "¡Felicitaciones por una audiencia exitosa, Lord Schwab! ¡Por favor, toma estas flores!",
  ui_story_5043_50430101_85_dialog_content = "A-Y también tengo un poco de chocolate blanco para ti. Aquí...",
  ui_story_5043_50430101_86_dialog_content = "(Puaj...)",
  ui_story_5043_50430101_87_dialog_content = "Uno a la vez, mis lindos. Formar una cola ordenada...",
  ui_story_5043_50430101_88_dialog_content = "<color=#e8d9bb>Jardines de Lumopolis, Oficina del Juez Principal</color>",
  ui_story_5043_50430101_89_dialog_content = "El objetivo de tener reglas es permitirnos ver rápidamente dónde aún reina el caos.",
  ui_story_5043_50430101_90_dialog_content = "¿Por cuánto tiempo han estado apareciendo en los tribunales estos ridículos casos de relaciones?",
  ui_story_5043_50430101_91_dialog_content = "Señor de la ciudad, señor, solo en el último mes.",
  ui_story_5043_50430101_92_dialog_content = "Veo. Ah, volver a ser joven...",
  ui_story_5043_50430101_93_dialog_content = "Pero el Salón de la Justicia es un lugar sagrado y serio.",
  ui_story_5043_50430101_94_dialog_content = "¿Desea que dejemos de escuchar estos casos, mi señor?",
  ui_story_5043_50430101_95_dialog_content = "No, todavía no es el momento para eso.",
  ui_story_5043_50430101_96_dialog_content = "Eso solo daría como resultado que los ciudadanos dirigieran su ira hacia el Salón de Justicia.",
  ui_story_5043_50430101_97_dialog_content = "¿Qué quieres que hagamos, entonces?",
  ui_story_5043_50430101_98_dialog_content = "Establezca un tribunal subordinado temporal para manejar estas disputas románticas.",
  ui_story_5043_50430101_99_dialog_content = "Seguirá siendo parte de Lumopolis Gardens, pero separado del Salón de la Justicia.",
  ui_story_5043_50430101_100_dialog_content = "En cuanto a la dotación de personal... envía a algunos de los más jóvenes. Será una buena experiencia para ellos.",
  ui_story_5043_50430101_101_dialog_content = "Un tribunal temporal requerirá un juez principal temporal.",
  ui_story_5043_50430101_102_dialog_content = "May Te pregunto si tienes a alguien en mente.",
  ui_story_5043_50430101_103_dialog_content = "Me di cuenta de un joven candidato en particular antes...",
  ui_story_5043_50430101_104_dialog_content = "<color=#e8d9bb>El Salón de la Justicia, Jardines de Lumopolis</color>",
  ui_story_5043_50430101_105_dialog_content = "Parece que Irridon y el Señor de la Ciudad están discutiendo asuntos importantes.",
  ui_story_5043_50430101_106_dialog_content = "Supongo que la reunión de hoy no está sucediendo. Si no recuerdo mal, el próximo espacio libre en su agenda es...",
  ui_story_5043_50430101_107_dialog_content = "Oh, lo siento, PlayerName. Vas a estar esperando durante días.",
  ui_story_5043_50430101_108_dialog_content = "Te acostumbrarás. Siempre rompe sus citas e ignora las opiniones de los demás.",
  ui_story_5043_50430101_109_dialog_content = "N-No hables así. Y tenemos algo de tiempo libre ahora, ¿verdad?",
  ui_story_5043_50430101_110_dialog_content = "Incluso el simple hecho de ver a estos jueces ordenar sus papeles es una excelente manera de pasar el tiempo.",
  ui_story_5043_50430101_111_dialog_content = "Acusación. Evidencia. Argumentos... Bien, eso es todo.",
  ui_story_5043_50430101_112_dialog_content = "Casi termino aquí. Tina, ¿Cómo estás?",
  ui_story_5043_50430101_113_dialog_content = "¿eh? ¿Qué?",
  ui_story_5043_50430101_114_dialog_content = "Oh, lo siento, Leyn. Esa audiencia se prolongó durante tres horas. Estoy todo... bostezo...",
  ui_story_5043_50430101_115_dialog_content = "Oh, es así, ¿eh?",
  ui_story_5043_50430101_116_dialog_content = "Qué día tan ajetreado has tenido. Aquí, querida Tina, toma una taza de bebida reconfortante para que te sientas mejor...",
  ui_story_5043_50430101_117_dialog_content = "Mhm, gracias Leyn. *Trago*",
  ui_story_5043_50430101_118_dialog_content = "¿¡Eh!?",
  ui_story_5043_50430101_119_dialog_content = "¡¿Chocolate caliente?! Odio las bebidas dulces!!!",
  ui_story_5043_50430101_120_dialog_content = "Jejeje, despierto ahora, ¿verdad? No me importa si tienes narcolepsia. Trabajar primero, dormir después.",
  ui_story_5043_50430101_121_dialog_content = "Y ahora que lo pienso... Siento que has estado más dormido que de costumbre los últimos días.",
  ui_story_5043_50430101_122_dialog_content = "No me parece. Hago un punto de estar despierto durante cuatro horas todos los días.",
  ui_story_5043_50430101_123_dialog_content = "¿Incluso hoy? Y empezaste a bostezar antes de que termináramos de trabajar ayer.",
  ui_story_5043_50430101_124_dialog_content = "¿No dormiste bien? No puedo imaginarte sufriendo de insomnio.",
  ui_story_5043_50430101_125_dialog_content = "¿Qué? Eso es ridículo. Como si...",
  ui_story_5043_50430101_126_dialog_content = "Bien, eso es todo ordenado. Me voy a casa.",
  ui_story_5043_50430101_127_dialog_content = "Nos vemos mañana, todos.",
  ui_story_5043_50430101_128_dialog_content = "Sí, me iré pronto.",
  ui_story_5043_50430101_129_dialog_content = "Adiós, señora Carleen y compañero masculino.",
  ui_story_5043_50430101_130_dialog_content = "¡Nos vemos!",
  ui_story_5043_50430101_131_dialog_content = "(¿Es eso a lo que me han reducido? ¿\"Compañero masculino\"?)",
  ui_story_5043_50430101_132_dialog_content = "¡Guau! ¡Cuánto tiempo sin verte, compañero masculino de Lady Carleen!",
  ui_story_5043_50430101_133_dialog_content = "Conozco esa voz...",
  ui_story_5043_50430101_134_dialog_content = "Matthieu! y Loewe. No esperaba verlos a ustedes dos.",
  ui_story_5043_50430101_135_dialog_content = "Matthieu, Veo que estás tan ocioso y descarado como siempre.",
  ui_story_5043_50430101_136_dialog_content = "No te enojes, princesa. No estoy aquí para holgazanear.",
  ui_story_5043_50430101_137_dialog_content = "Algo interesante está en marcha. ¿quieres entrar?",
  ui_story_5043_50430101_138_dialog_content = "Algo interesante\"?",
  ui_story_5043_50430101_139_dialog_content = "Sí. Me acabo de enterar. Los plebeyos no se enterarán hasta mañana.",
  ui_story_5043_50430101_140_dialog_content = "Seguir.",
  ui_story_5043_50430101_141_dialog_content = "Es como esto. La corte tiene un caso muy inusual para escuchar. Ahora, aún no ha sido asignado, pero...",
  ui_story_5043_50430101_142_dialog_content = "Es tan bueno como el mío.",
  ui_story_5043_50430101_143_dialog_content = "Lo que quiere decir es que rogó y rogó al juez presidente desesperadamente hasta que lo consiguió.",
  ui_story_5043_50430101_144_dialog_content = "¡Ey! Deja de interrumpir.",
  ui_story_5043_50430101_145_dialog_content = "De todos modos, está conectado con el Día de la Corona de Luna...",
  ui_story_5043_50430101_146_dialog_content = "<color=#e8d9bb>Jardines de Lumopolis, Barrio Residencial</color>",
  ui_story_5043_50430101_147_dialog_content = "La la... lalala... la la ♪...",
  ui_story_5043_50430101_148_dialog_content = "(Lo primero que debe hacer al llegar a casa: comprobar si hay cartas o paquetes...)",
  ui_story_5043_50430101_149_dialog_content = "Oh...",
  ui_story_5043_50430101_150_dialog_content = "Aún nada.",
  ui_story_5043_50430101_151_dialog_content = "(Todavía tengo las hojas y las nueces <color=#FFB400>él</color> me envió el mes pasado.)",
  ui_story_5043_50430101_152_dialog_content = "(Es hora de que envíe algo a cambio, pero <color=#FFB400>él</color> todavía no me ha dado su nueva dirección.)",
  ui_story_5043_50430101_153_dialog_content = "(Y ahora que lo pienso, ha pasado casi un mes desde que escuché de <color=#FFB400>a él</color>.)",
  ui_story_5043_50430101_154_dialog_content = "(Es bastante preocupante... ¿Cuándo podré enviar las cookies que hice para <color=#FFB400>a él</color>?)",
  ui_story_5043_50430101_155_dialog_content = "(¿Tal vez debería... ser un poco más proactivo?)",
  ui_story_5043_50430201_1_dialog_content = "<color=#e8d9bb>El día siguiente</color>",
  ui_story_5043_50430201_2_dialog_content = "Así son las cosas.",
  ui_story_5043_50430201_3_dialog_content = "El Señor de la Ciudad ha decidido establecer una corte temporal dentro de Lumopolis Gardens.",
  ui_story_5043_50430201_4_dialog_content = "He decidido llamarlo el <color=#FFB400>División de romance</color>.",
  ui_story_5043_50430201_5_dialog_content = "Entiendo. Y seguiré dando lo mejor de mí allí.",
  ui_story_5043_50430201_6_dialog_content = "Pero si puedo preguntar, ¿quién servirá como juez principal? ¿Asumirás tú también esa carga?",
  ui_story_5043_50430201_7_dialog_content = "No, hemos recibido orientación del Señor de la Ciudad sobre ese asunto. Ha sugerido al juez <color=#FFB400>Schwab</color>.",
  ui_story_5043_50430201_8_dialog_content = "Una decisión que no entiendo del todo, aunque ayer pareció impresionar al Señor de la Ciudad...",
  ui_story_5043_50430201_9_dialog_content = "Y quizás su estilo sea particularmente adecuado para tratar asuntos amorosos.",
  ui_story_5043_50430201_10_dialog_content = "Muy bien. Schwab tenía su propia forma única de resolver ese lío ayer. Estaba impresionado.",
  ui_story_5043_50430201_11_dialog_content = "Ciertamente sabe cómo usar sus... encantos.",
  ui_story_5043_50430201_12_dialog_content = "No debes estar decepcionado, Leyn.",
  ui_story_5043_50430201_13_dialog_content = "Todos ustedes acaban de convertirse en jueces oficiales, pero el Señor de la Ciudad aprecia sus habilidades.",
  ui_story_5043_50430201_14_dialog_content = "Y cuando regrese de la División Romance, estará bien posicionado para la promoción.",
  ui_story_5043_50430201_15_dialog_content = "Sí. Gracias, juez principal.",
  ui_story_5043_50430201_16_dialog_content = "Además, tengo otra tarea para ti.",
  ui_story_5043_50430201_17_dialog_content = "De hecho, podría ser el caso más complicado que la División de Romance tiene que manejar en este momento.",
  ui_story_5043_50430201_18_dialog_content = "¿Puede que hayas oído hablar de ello? <color=#FFB400>El caso de la estatua sin cabeza</color>?",
  ui_story_5043_50430201_19_dialog_content = "¿Tengo mi primer caso tan pronto?",
  ui_story_5043_50430201_20_dialog_content = "Ah, es un alivio escuchar que estás tan interesado. Ya he tenido cinco o seis personas que han rechazado el caso.",
  ui_story_5043_50430201_21_dialog_content = "¿Y por qué lo hicieron?",
  ui_story_5043_50430201_22_dialog_content = "Aparte del hecho de que es un caso extraño... la mayoría de ellos dijeron que estaban ocupados teniendo citas con sus amantes.",
  ui_story_5043_50430201_23_dialog_content = "Ah, ya veo...",
  ui_story_5043_50430201_24_dialog_content = "(Esos nobles nunca cambian...)",
  ui_story_5043_50430201_25_dialog_content = "El demandante en el caso es un noble de Lumopolis Courtyard, el Sr. <color=#FFB400>Byron</color>.",
  ui_story_5043_50430201_26_dialog_content = "<color=#e8d9bb>Hace cuatro días</color>",
  ui_story_5043_50430201_27_dialog_content = "<color=#e8d9bb>Ding, ding—ding—</color>",
  ui_story_5043_50430201_28_dialog_content = "ya vengo, ya vengo. ¡Deja de sonar!",
  ui_story_5043_50430201_29_dialog_content = "¿Ha llamado, señor? ¿Tocaste la Campana de la Justicia?",
  ui_story_5043_50430201_30_dialog_content = "Hice. ¡Quiero demandar a alguien! es mi vecino",
  ui_story_5043_50430201_31_dialog_content = "él dañó <color=#FFB400>galatea</color>, la estatua que se encuentra fuera del Salón de la Justicia. ¡Lo vi con mis propios ojos!",
  ui_story_5043_50430201_32_dialog_content = "Aférrate. Sé que la estatua de ahí simboliza la justicia. Pero, ¿desde cuándo se llama Galatea?",
  ui_story_5043_50430201_33_dialog_content = "Y sí, se rompió hace unos días, pero para ser honesto, pensamos que era viejo...",
  ui_story_5043_50430201_34_dialog_content = "Señorita, tenga cuidado con su idioma. Galatea es un <color=#FFB400>\"ella\"</color>!!! Fui yo quien la nombró.",
  ui_story_5043_50430201_35_dialog_content = "Está bien. Entonces, ¿podría pasarme su queja?",
  ui_story_5043_50430201_36_dialog_content = "Déjame ver...",
  ui_story_5043_50430201_37_dialog_content = "¿Hmm? Sr. Byron, el crimen del que acusa a su vecino, ¿es correcto?",
  ui_story_5043_50430201_38_dialog_content = "Acabas de decir que dañó la estatua, pero aquí has escrito <color=#FFB400>\"obstrucción del amor</color>.\"",
  ui_story_5043_50430201_39_dialog_content = "Eso es correcto. Porque...",
  ui_story_5043_50430201_40_dialog_content = "Galatea es mi <color=#FFB400>amante</color>!",
  ui_story_5043_50430201_41_dialog_content = "¿Así que se enamoró de una estatua... y ahora quiere demandar a la persona que la destrozó?",
  ui_story_5043_50430201_42_dialog_content = "Sí. Debido a que la estatua está clasificada como instalación pública, no podemos evitar que alguien se enamore de ella.",
  ui_story_5043_50430201_42X1_dialog_content = "Y así, estrictamente hablando, este es un caso para la División Romance.",
  ui_story_5043_50430201_43_dialog_content = "También he enviado gente para hablar con el acusado.",
  ui_story_5043_50430201_44_dialog_content = "Hay lagunas en la historia del Sr. Byron. El acusado en el caso podría no ser el sospechoso.",
  ui_story_5043_50430201_45_dialog_content = "Como saben, aquí en la Sala de Justicia investigamos tanto como juzgamos. Leyn, debemos averiguar qué está pasando antes de que se escuche el caso.",
  ui_story_5043_50430201_46_dialog_content = "De lo contrario, terminaremos aplazando el caso hasta una futura audiencia. Y la División de Romance ni siquiera es un arreglo permanente, así que esa no es una opción.",
  ui_story_5043_50430201_47_dialog_content = "Si entiendo. Resolveré el caso antes de que cierre la División de Romance, te lo aseguro.",
  ui_story_5043_50430201_48_dialog_content = "Me alegra escucharlo. Y dos de tus colegas te estarán ayudando.",
  ui_story_5043_50430201_49_dialog_content = "Uno es tu viejo amigo, Tina. Ella accedió a ayudar esta mañana.",
  ui_story_5043_50430201_50_dialog_content = "Le he pedido que revise el papeleo, aunque sospecho que ahora se está recuperando del sueño.",
  ui_story_5043_50430201_51_dialog_content = "El otro... bueno, es un dolor de cabeza, pero técnicamente es <color=#FFB400>más experimentado</color> que tú. Estoy seguro de que te dará algunos consejos útiles.",
  ui_story_5043_50430201_52_dialog_content = "Puedes reunirte con él ahora, frente a esa estatua.",
  ui_story_5043_50430201_53_dialog_content = "Compara notas con Tina cuando termines tus investigaciones.",
  ui_story_5043_50430201_54_dialog_content = "Iré enseguida.",
  ui_story_5043_50430201_55_dialog_content = "<color=#e8d9bb>Jardines de Lumopolis, junto a la estatua</color>",
  ui_story_5043_50430201_56_dialog_content = "(Me pregunto quién es esta persona \"más experimentada\" sobre la que el Juez Jefe estaba siendo tan vago...)",
  ui_story_5043_50430201_57_dialog_content = "Oh, ¿el Salón de Justicia está dejando entrar a cualquier plebeyo ahora?",
  ui_story_5043_50430201_58_dialog_content = "(Debí haberlo adivinado...)",
  ui_story_5043_50430201_59_dialog_content = "Creo Leyn parece más un buen juez que tú, Matthieu.",
  ui_story_5043_50430201_60_dialog_content = "Buenos dias capitan Carleen, y mis mejores deseos.",
  ui_story_5043_50430201_61_dialog_content = "Por favor, no te pares en la ceremonia. Esto es PlayerName. Matthieu aquí nos ha pedido a ambos que echemos una mano en la investigación.",
  ui_story_5043_50430201_62_dialog_content = "¡Eres el Caelestite legendario! ¡Eres mucho más accesible en persona!",
  ui_story_5043_50430201_63_dialog_content = "E-Eres muy amable. Espero poder ser de alguna ayuda.",
  ui_story_5043_50430201_64_dialog_content = "<size=32>¿Qué diablos dicen los rumores sobre mí...</size>",
  ui_story_5043_50430201_65_dialog_content = "Deberías dar gracias al Dios de la Luz, plebeyo. Con nuestra ayuda, su trabajo se desarrollará con rapidez.",
  ui_story_5043_50430201_66_dialog_content = "Me sorprendería si no sale mal.",
  ui_story_5043_50430201_67_dialog_content = "¿Qué pasa, novato? No pareces emocionado.",
  ui_story_5043_50430201_68_dialog_content = "Este es uno de los casos más extraños en la historia de la Sala de Justicia. ¡Muestra un poco de entusiasmo!",
  ui_story_5043_50430201_69_dialog_content = "Sí. Una estatua extraña, un crimen extraño, un demandante extraño. Y un mentor extraño.",
  ui_story_5043_50430201_70_dialog_content = "¡Cuidado, niño! Muestra un poco más de respeto.",
  ui_story_5043_50430201_71_dialog_content = "Muy bien. No vine aquí para discutir contigo. ¿Supongo que has examinado la estatua?",
  ui_story_5043_50430201_72_dialog_content = "¿Eh? Oh, ¿te refieres a la caja de dinero?",
  ui_story_5043_50430201_73_dialog_content = "Lo siento, es solo que no tiene la cabeza, me recuerda a algo en lo que podrías ahorrar monedas. Me dan ganas de tirar un Nightium.",
  ui_story_5043_50430201_74_dialog_content = "Oh por favor. Intenta tomarte esto en serio...",
  ui_story_5043_50430201_75_dialog_content = "<color=#e8d9bb>Quebrar-</color>",
  ui_story_5043_50430201_76_dialog_content = "¿Qué fue eso?",
  ui_story_5043_50430201_77_dialog_content = "Graaaaaah! ¡Rugido!",
  ui_story_5043_50430201_78_dialog_content = "¡¿Qué demonios?! ¿Cómo llegaron los eclipses a Lumopolis Gardens?",
  ui_story_5043_50430201_79_dialog_content = "¡Es imposible! Lumopolis está vigilada día y noche. No hay forma de que un Eclipsite pueda entrar...",
  ui_story_5043_50430201_80_dialog_content = "¡Guardias!",
  ui_story_5043_50430201_81_dialog_content = "¡Señora!",
  ui_story_5043_50430201_82_dialog_content = "Voy a revisar todos los registros de entrada y salida. ¡Y dile a la Guardia Nocturna que quiero un informe de toda la actividad reciente!",
  ui_story_5043_50430201_83_dialog_content = "En cuanto a los eclipses... PlayerName, ¿Supongo que ustedes cuatro pueden lidiar con ellos?",
  ui_story_5043_50430201_84_dialog_content = "Por supuesto. Ir, Carleen.",
  ui_story_5043_50430201_85_dialog_content = "Bien entonces. Es hora de que los Eclipsites reciban su veredicto final.",
  ui_story_5043_50430202_1_dialog_content = "¡Se acabó! Nadie resultó herido, ¿verdad?",
  ui_story_5043_50430202_2_dialog_content = "Estoy bien. Sólo un poco disgustado.",
  ui_story_5043_50430202_3_dialog_content = "Acabo de empezar a trabajar. Ahora necesito un baño de nuevo.",
  ui_story_5043_50430202_4_dialog_content = "Oye, plebeyo, ¿estás bien?",
  ui_story_5043_50430202_5_dialog_content = "Gracias por preguntar. Da la casualidad de que no estoy bendecido con la misma necesidad de bañarme constantemente que disfrutan los aristócratas.",
  ui_story_5043_50430202_6_dialog_content = "Lo siento mucho por ti. Aunque supongo que eso significa que Loewe es el germaphobe más grande aquí.",
  ui_story_5043_50430202_7_dialog_content = "Siempre te cubres con tanta fuerza, Loewe. Sospecho que incluso encuentras el aire sucio.",
  ui_story_5043_50430202_8_dialog_content = "Probablemente puedan renunciar si la estatua se rompe.",
  ui_story_5043_50430202_9_dialog_content = "¡No me ignores!",
  ui_story_5043_50430202_10_dialog_content = "Está bien, ya has visto suficiente. El Salón de la Justicia puede ocuparse de ello ahora.",
  ui_story_5043_50430202_11_dialog_content = "Crucial <color=#FFB400>evidencia</color> no debe dejarse sentado al aire libre de esta manera.",
  ui_story_5043_50430202_12_dialog_content = "Según el demandante, este es el <color=#FFB400>víctima</color>.",
  ui_story_5043_50430202_13_dialog_content = "Espera, déjame echar un vistazo más de cerca...",
  ui_story_5043_50430202_14_dialog_content = "Mmm. La sección de fractura es más limpia. No parece una vieja grieta que finalmente se abrió.",
  ui_story_5043_50430202_15_dialog_content = "Es más como si alguien le rompiera la cabeza deliberadamente.",
  ui_story_5043_50430202_16_dialog_content = "PlayerName, ¿Tienes algún consejo?",
  ui_story_5043_50430202_17_dialog_content = "Hay una cosa rara.",
  ui_story_5043_50430202_18_option_content = "la cabeza que falta",
  ui_story_5043_50430202_19_dialog_content = "No parece vandalismo espontáneo. El descanso es demasiado limpio.",
  ui_story_5043_50430202_20_dialog_content = "Además, no hay ningún otro daño. Solo la cabeza perdida.",
  ui_story_5043_50430202_21_option_content = "Fragmentos de estatua",
  ui_story_5043_50430202_22_dialog_content = "Los alrededores están demasiado limpios. ¿No debería haber pedazos extra de la estatua por ahí?",
  ui_story_5043_50430202_23_dialog_content = "Las personas enviadas a recoger las pruebas probablemente las barrieron.",
  ui_story_5043_50430202_24_dialog_content = "¡E-Eso tiene sentido! En ese caso, supongo que lo extraño es la cabeza que falta.",
  ui_story_5043_50430202_25_dialog_content = "Creo que tienes razón. Parece que alguien rompió la cabeza de la estatua para poder <color=#FFB400>robarlo</color>...",
  ui_story_5043_50430202_26_dialog_content = "Oye, espera. ¿Alguno de ustedes ve <color=#FFB400>eso</color>? Aparecí de la nada.",
  ui_story_5043_50430202_27_dialog_content = "Mira, al lado de esa ventana, en el cielo sobre Lumopolis...",
  ui_story_5043_50430202_28_dialog_content = "Es un <color=#FFB400>luna</color>.",
  ui_story_5043_50430202_29_dialog_content = "¡Yo lo veo!",
  ui_story_5043_50430202_30_dialog_content = "Las cosas raras siguen sucediendo. ¿Qué sucede?",
  ui_story_5043_50430202_31_dialog_content = "Qué intrigante. ¿Deberíamos echar un vistazo?",
  ui_story_5043_50430202_32_dialog_content = "Espera... ¡Aún tenemos trabajo por hacer!",
  ui_story_5043_50430202_33_dialog_content = "¿Están todos aquí?",
  ui_story_5043_50430202_34_dialog_content = "Ey, Tina. Esto es PlayerName. La Caelestita.",
  ui_story_5043_50430202_35_dialog_content = "Jejeje. De hecho, nos conocimos el mes pasado, el Día de la Corona de Luna.",
  ui_story_5043_50430202_36_dialog_content = "Buen día, PlayerName. Es encantador verte de nuevo.",
  ui_story_5043_50430202_37_dialog_content = "Hola, Tina. Aunque ya no es de mañana...",
  ui_story_5043_50430202_38_dialog_content = "Tina siempre piensa que es de mañana cuando se despierta.",
  ui_story_5043_50430202_39_dialog_content = "Tienes el tiempo perfecto, Tina. Compartamos notas sobre la investigación.",
  ui_story_5043_50430202_40_dialog_content = "Entonces... digamos los dos lo que tenemos al mismo tiempo. Hasta ahora, he descubierto—",
  ui_story_5043_50430202_41_dialog_content = "Nada.",
  ui_story_5043_50430202_42_dialog_content = "Suspiro. Entonces, ¿tú tampoco has progresado?",
  ui_story_5043_50430202_43_dialog_content = "Revisé los documentos del caso que me dio el juez principal una y otra vez.",
  ui_story_5043_50430202_44_dialog_content = "Pero todo es tan ilógico e inconsistente. No puedo darle sentido a nada de eso.",
  ui_story_5043_50430202_45_dialog_content = "Tenemos una teoría potencial, al menos.",
  ui_story_5043_50430202_46_dialog_content = "PlayerName y sospecho que la cabeza de la estatua fue robada.",
  ui_story_5043_50430202_47_dialog_content = "Correcto... ¿Por qué alguien haría eso?",
  ui_story_5043_50430202_48_dialog_content = "¡Quién sabe! Tal vez Judge Jr. decidió comprarse un nuevo casco.",
  ui_story_5043_50430202_49_dialog_content = "Si no estamos haciendo ningún progreso, ¿tal vez deberíamos dejarlo por hoy?",
  ui_story_5043_50430202_50_dialog_content = "¡Esperar! En realidad, yo... Erm...",
  ui_story_5043_50430202_51_dialog_content = "El caso es que quería pedirles a todos un consejo sobre un asunto privado.",
  ui_story_5043_50430202_52_dialog_content = "Uh, ¿qué tipo de asunto privado, exactamente? No estoy seguro de querer involucrarme...",
  ui_story_5043_50430202_53_dialog_content = "F-Bien. Últimamente me he encontrado con un pequeño problema y quería una segunda opinión.",
  ui_story_5043_50430202_54_dialog_content = "Oooh. ¿Un asunto privado, en un momento como este?",
  ui_story_5043_50430202_55_dialog_content = "Déjame aventurarme a adivinar. Es un problema romántico, ¿no?",
  ui_story_5043_50430202_56_dialog_content = "Estás demasiado entusiasmado con esto.",
  ui_story_5043_50430202_57_dialog_content = "Mmm. De todos modos, ¿puedo invitarlos a todos a venir a mi casa? He preparado té y pasteles.",
  ui_story_5043_50430202_58_dialog_content = "PlayerName, Me gustaría que vinieras también.",
  ui_story_5043_50430202_59_dialog_content = "Escuché que los Caelestites son muy buenos para comprender las emociones de las personas. Así que tienes que ayudarme.",
  ui_story_5043_50430202_60_dialog_content = "Sería un honor. Aunque no estoy seguro de que tengamos esa habilidad en particular...",
  ui_story_5043_50430301_1_dialog_content = "<color=#e8d9bb>Jardines de Lumopolis, la casa de Tina</color>",
  ui_story_5043_50430301_2_dialog_content = "Vale, esto es lo que pasó.",
  ui_story_5043_50430301_3_dialog_content = "En el Día de la Corona de la Luna el mes pasado, recibí un regalo de <color=#FFB400>a él</color>.",
  ui_story_5043_50430301_4_dialog_content = "Eran solo algunas cosas ordinarias, pero me di cuenta de que <color=#FFB400>él</color> realmente se preocupaba por mí.",
  ui_story_5043_50430301_5_dialog_content = "¡W-Woah! Esperar, Tina. ¿Estas enamorado?",
  ui_story_5043_50430301_6_dialog_content = "¿Eh? No, no creo que sea eso...",
  ui_story_5043_50430301_7_dialog_content = "Bueno, esto suena como el tipo de cosas que hacen los amantes.",
  ui_story_5043_50430301_8_dialog_content = "Si tú también lo crees...",
  ui_story_5043_50430301_9_dialog_content = "¡Ay, no importa eso! Déjame terminar la historia.",
  ui_story_5043_50430301_10_dialog_content = "Ha pasado casi un mes desde el Día de la Corona de Luna y, según la tradición, debería enviar <color=#FFB400>a él</color> un regalo a cambio.",
  ui_story_5043_50430301_11_dialog_content = "Así que hice unas galletas para <color=#FFB400>a él</color>. Incluso hice cada galleta en una forma diferente.",
  ui_story_5043_50430301_12_dialog_content = "Entonces las cookies estaban listas para ser enviadas. Pero...",
  ui_story_5043_50430301_13_dialog_content = "Pero <color=#FFB400>él</color> no ha respondido a más de mis cartas.",
  ui_story_5043_50430301_14_dialog_content = "No he tenido la oportunidad de colarme en una reunión con <color=#FFB400>a él</color>. Y ahora ni siquiera recibo cartas.",
  ui_story_5043_50430301_15_dialog_content = "Estoy tan preocupado. Me ha estado manteniendo despierto. ¡Solo duermo 16 horas por noche!",
  ui_story_5043_50430301_16_dialog_content = "¡Qué despreciable hombre!",
  ui_story_5043_50430301_17_dialog_content = "Sí. Suena peor que Matthieu.",
  ui_story_5043_50430301_18_dialog_content = "Te sugiero que te rindas con él.",
  ui_story_5043_50430301_19_dialog_content = "No, no puedo hacer eso todavía. Estoy seguro de que tiene sus razones.",
  ui_story_5043_50430301_20_dialog_content = "Después de todo, <color=#FFB400>él</color> tiene una apariencia bastante singular. la gente se da cuenta <color=#FFB400>a él</color> donde quiera que vaya Así que tal vez no pueda mantenerse en contacto tanto como le gustaría.",
  ui_story_5043_50430301_21_dialog_content = "UH oh. Tina tiene un mal caso de estar enamorada.",
  ui_story_5043_50430301_22_dialog_content = "¿Mm...?",
  ui_story_5043_50430301_23_dialog_content = "<size=32>Ey, PlayerName, Matthieu, Loewe. tengo una teoria...</size>",
  ui_story_5043_50430301_24_dialog_content = "<size=32>Este <color=#FFB400>hombre</color> ¡Tina está hablando de sonidos un poco familiares!</size>",
  ui_story_5043_50430301_25_dialog_content = "<size=32>¡Verdadero! Alguien que se hace notar donde quiera que va...</size>",
  ui_story_5043_50430301_26_dialog_content = "<size=32>Y hace solo un esfuerzo mínimo para mantener felices a sus admiradores...</size>",
  ui_story_5043_50430301_27_dialog_content = "<size=32>Y es cruel, superficial, egoísta, egoísta...</size>",
  ui_story_5043_50430301_28_dialog_content = "<size=32>Parece que podría ser tu gemelo.</size>",
  ui_story_5043_50430301_29_dialog_content = "<size=32>De todos modos, esta persona de la que Tina está hablando tiene que ser <color=#FFB400>Schwab</color>, ¿bien?</size>",
  ui_story_5043_50430301_30_dialog_content = "Oye, ¿de qué estás susurrando?",
  ui_story_5043_50430301_31_dialog_content = "Ejem. Bueno, Tina. Sabemos quién es tu crush.",
  ui_story_5043_50430301_32_dialog_content = "¿Qué? ¿Ya lo adivinaste? Esperaba mantenerlo en secreto...",
  ui_story_5043_50430301_33_dialog_content = "(Parece Tina no tiene más remedio que admitirlo...)",
  ui_story_5043_50430301_34_dialog_content = "La primera vez que lo vi fue en Salar Manor.",
  ui_story_5043_50430301_35_dialog_content = "Me habían invitado a un baile allí.",
  ui_story_5043_50430301_36_dialog_content = "Pero llegué un poco temprano y me llevaron al jardín a esperar.",
  ui_story_5043_50430301_37_dialog_content = "Pero claro, los Salar tienen un jardín increíble, y me perdí en el laberinto de setos.",
  ui_story_5043_50430301_38_dialog_content = "Dios sabe cuánto tiempo pasé allí. Entonces, de repente, me encontré con un pequeño pabellón y él estaba sentado en él.",
  ui_story_5043_50430301_39_dialog_content = "Se sorprendió de ver a alguien allí. Y pasamos tanto tiempo mirándonos bajo ese hermoso cielo azul...",
  ui_story_5043_50430301_40_dialog_content = "Fue la primera vez que me di cuenta de lo gentil y amable que podía ser. Parecía ser uno con los árboles y las flores a su alrededor.",
  ui_story_5043_50430301_41_dialog_content = "Terminó saliendo antes que yo. Pero no pude prestar atención a nadie más ese día.",
  ui_story_5043_50430301_42_dialog_content = "Jejeje Qué romántico.",
  ui_story_5043_50430301_43_dialog_content = "(Salar Manor. Entonces tiene que ser Schwab Salar).",
  ui_story_5043_50430301_44_dialog_content = "(\"¿Gentil\"? ¿\"Amable\"? ¿Ese tipo? Si tú lo dices...)",
  ui_story_5043_50430301_45_dialog_content = "Dado que ya saben quién es, tengo un favor que pedirles a todos.",
  ui_story_5043_50430301_46_dialog_content = "necesito que me ayudes con <color=#FFB400>Operación Acci-Meet</color>.",
  ui_story_5043_50430301_47_dialog_content = "¿Qué diablos es un Acci-Meet?",
  ui_story_5043_50430301_48_dialog_content = "Bueno, quiero diseñar tantos <color=#FFB400>encuentros accidentales</color> con él como sea posible. accimeet. Inteligente, ¿eh?",
  ui_story_5043_50430301_49_dialog_content = "No te vas a rendir, ¿verdad? Incluso si no te ayudamos.",
  ui_story_5043_50430301_50_dialog_content = "No lo siento...",
  ui_story_5043_50430301_51_dialog_content = "Muy bien. Siempre estoy feliz de ayudar a un colega.",
  ui_story_5043_50430301_52_dialog_content = "Yo también.",
  ui_story_5043_50430301_53_dialog_content = "Gaah... Graaah...",
  ui_story_5043_50430301_54_dialog_content = "¡Eclipsites!",
  ui_story_5043_50430301_55_dialog_content = "¡Ah, de verdad! ¡Servidor! ¡Servidor!",
  ui_story_5043_50430301_56_dialog_content = "No importa. Han pasado años desde que le di un entrenamiento a la Mano Divina.",
  ui_story_5043_50430301_57_dialog_content = "Yo mismo limpiaré esta suciedad.",
  ui_story_5043_50430301_58_dialog_content = "¿No es esta tu propia casa? ¡Actúas como si fueran solo un par de cucarachas!",
  ui_story_5043_50430302_1_dialog_content = "Que pelea tan emocionante... *bostezos*",
  ui_story_5043_50430302_2_dialog_content = "No me había dado cuenta antes, pero ¿eres zurdo?",
  ui_story_5043_50430302_3_dialog_content = "Ja ja. Sí, lo soy. Fui entrenado de esta manera para manejar el poder de la Mano Divina.",
  ui_story_5043_50430302_4_dialog_content = "Pero siempre me siento tan cansado después de una pelea...",
  ui_story_5043_50430302_5_dialog_content = "Si te vas a la cama ahora, entonces nos vamos.",
  ui_story_5043_50430302_6_dialog_content = "¿Cama? ¡No! Estoy lleno de energía.",
  ui_story_5043_50430302_7_dialog_content = "Volvamos a los negocios. Necesito que todos me ayuden con la Operación Accimeet.",
  ui_story_5043_50430302_8_dialog_content = "Está bien, pero... ¿cómo?",
  ui_story_5043_50430302_9_dialog_content = "Bueno... Para ser honesto, nunca he perseguido a nadie antes. Por eso necesito tu ayuda.",
  ui_story_5043_50430302_10_dialog_content = "¿Que necesito hacer?",
  ui_story_5043_50430302_11_dialog_content = "Déjame pensar... Leí una vez en un libro que el primer paso para cambiar es reconocer tus propios defectos.",
  ui_story_5043_50430302_12_dialog_content = "Creo que la mejor manera de ganar su corazón es—<color=#FFB400> para confesarte tu amor</color>.",
  ui_story_5043_50430302_13_dialog_content = "Ve a algún lugar donde sea probable que aparezca y espéralo.",
  ui_story_5043_50430302_14_dialog_content = "Y cuando aparece, ¡golpeas! ¡Sorpréndelo!",
  ui_story_5043_50430302_15_dialog_content = "Oh. Veo...",
  ui_story_5043_50430302_16_dialog_content = "Equivocado de nuevo, plebeyo. Tina no puede confiar únicamente en tomar la iniciativa. Ella también necesita aprender. <color=#FFB400>el arte de ocultar</color>.",
  ui_story_5043_50430302_17_dialog_content = "Necesita ocultar sus verdaderos sentimientos. No se le puede permitir ver lo ansiosa que está ella.",
  ui_story_5043_50430302_18_dialog_content = "Si tienes el coraje de acercarte a él pero estás demasiado nervioso para mirarlo a los ojos, finge ser tímido.",
  ui_story_5043_50430302_19_dialog_content = "¡Ah, claro! Entiendo.",
  ui_story_5043_50430302_20_dialog_content = "Y también-<color=#FFB400>reconocimiento</color>.",
  ui_story_5043_50430302_21_dialog_content = "Tienes que vigilar su actitud mientras se habla de temas aparentemente inocuos.",
  ui_story_5043_50430302_22_dialog_content = "Podrás descubrir sus verdaderos sentimientos en dos o tres conversaciones.",
  ui_story_5043_50430302_23_dialog_content = "Eso suena difícil. Pero haré lo mejor que pueda...",
  ui_story_5043_50430302_24_dialog_content = "Después de una cuidadosa consideración, creo que es mejor simplemente <color=#FFB400>se honesto</color>.",
  ui_story_5043_50430302_25_dialog_content = "En el transcurso de una relación, todos tus hábitos y defectos estarán expuestos a la otra persona.",
  ui_story_5043_50430302_26_dialog_content = "No podrás cubrirlos para siempre. Entonces, la honestidad es lo más importante.",
  ui_story_5043_50430302_27_dialog_content = "¡Tienes razón! Aunque espero que podamos llegar a ese punto...",
  ui_story_5043_50430302_28_dialog_content = "¡Gracias a todos! Recordaré todos tus consejos.",
  ui_story_5043_50430302_29_dialog_content = "Por cierto... ¿hablais por experiencia?",
  ui_story_5043_50430302_30_dialog_content = "Ejem...",
  ui_story_5043_50430302_31_dialog_content = "Me temo que no tengo ninguna experiencia práctica, no...",
  ui_story_5043_50430302_32_dialog_content = "No quise criticar a nadie. Es sólo... Supongo que tendré que probarlo yo mismo.",
  ui_story_5043_50430302_33_dialog_content = "Pero donde puedo encontrarlo?",
  ui_story_5043_50430302_34_dialog_content = "Si es él, lo más probable es que esté en algún lugar ocupado, en algún lugar lleno de gente.",
  ui_story_5043_50430302_35_dialog_content = "Oh. Bueno...",
  ui_story_5043_50430302_36_dialog_content = "Hablando de lugares concurridos, hay una opción obvia.",
  ui_story_5043_50430302_37_dialog_content = "Ese lugar donde se congregan nobles y plebeyos por igual. Directamente debajo de la \"luna\".",
  ui_story_5043_50430302_38_dialog_content = "¿¡P-Por qué!?",
  ui_story_5043_50430302_39_dialog_content = "Escuché algunas noticias sobre la \"luna\" antes. Creo que deberíamos ir e investigar.",
  ui_story_5043_50430302_40_dialog_content = "Solo quieres ir a verlo.",
  ui_story_5043_50430302_41_dialog_content = "No le hagas caso, yo también tengo curiosidad. ¡Vamos ahora!",
  ui_story_5043_50430302_42_dialog_content = "Oh, no. ¡Espera un minuto!",
  ui_story_5043_50430302_43_dialog_content = "quiero usar el <color=#FFB400>guantes</color> Llevaba cuando nos conocimos y nos tomamos de la mano.",
  ui_story_5043_50430302_44_dialog_content = "Y también tengo que llevarme las galletas que le hice.",
  ui_story_5043_50430401_1_dialog_content = "<color=#e8d9bb>Jardines de Lumopolis, Barrio Residencial</color>",
  ui_story_5043_50430401_2_dialog_content = "Entonces, ¿este globo aerostático que parece una luna ha estado flotando allí durante días?",
  ui_story_5043_50430401_3_dialog_content = "yo ni me habia dado cuenta...",
  ui_story_5043_50430401_4_dialog_content = "Supongo que no había imaginado que habría nada allí arriba, excepto los Jardines de Lumopolis y el sol.",
  ui_story_5043_50430401_5_dialog_content = "Es bastante normal que te lo pierdas. Los plebeyos como tú nunca pensarían en levantar la cabeza y apreciar la belleza de los cielos.",
  ui_story_5043_50430401_6_dialog_content = "¡Oye, di eso otra vez!",
  ui_story_5043_50430401_7_dialog_content = "Bien bien. Más caminar, menos pelear, por favor.",
  ui_story_5043_50430401_8_dialog_content = "Recuerdo que cuando era niña, mi madre me llevó a la Escalera a los Cielos y dijo que ese era el único lugar donde podíamos ver las estrellas.",
  ui_story_5043_50430401_9_dialog_content = "Con cada paso, ves una estrella. Sube todos los escalones, ves mil.",
  ui_story_5043_50430401_10_dialog_content = "¡Estaba tan emocionada! Corrí todo el camino hasta la cima.",
  ui_story_5043_50430401_11_dialog_content = "¿Cuántas estrellas viste?",
  ui_story_5043_50430401_12_dialog_content = "Ninguno. Solo el sol. Era mediodía.",
  ui_story_5043_50430401_13_dialog_content = "¡Al menos podrías haber esperado hasta la noche!",
  ui_story_5043_50430401_14_dialog_content = "Pero ahí es cuando duermo...",
  ui_story_5043_50430401_15_dialog_content = "...",
  ui_story_5043_50430401_16_dialog_content = "Por cierto Matthieu, ¿qué escuchaste sobre la \"luna\"?",
  ui_story_5043_50430401_17_dialog_content = "Oh, es solo un evento inventado por esos entusiastas del Día de la Corona de la Luna.",
  ui_story_5043_50430401_18_dialog_content = "Envían un globo aerostático que se parece a la luna hacia el cielo sobre Lumopolis, para anunciar el reinado del amor libre.",
  ui_story_5043_50430401_19_dialog_content = "Y cuando el globo sube, todos saben reunirse debajo de él para un salón improvisado.",
  ui_story_5043_50430401_20_dialog_content = "A todos los nobles que siguen las tendencias les encanta.",
  ui_story_5043_50430401_21_dialog_content = "Veo. Recuerdo Carleen diciendo algo sobre los entusiastas del Día de la Corona de Luna.",
  ui_story_5043_50430401_22_dialog_content = "Por eso usan un globo que se parece a la luna... porque es el Día de la Corona de la Luna.",
  ui_story_5043_50430401_23_dialog_content = "Qué inteligentes son ustedes, los nobles.",
  ui_story_5043_50430401_24_dialog_content = "Creo que tiene sentido porque la luna y el amor son cosas puras y hermosas.",
  ui_story_5043_50430401_25_dialog_content = "Estoy seguro de que eso es lo que estaba pensando quien planeó estos eventos.",
  ui_story_5043_50430401_26_dialog_content = "Qué cosas por decir. ¿Así son las chicas cuando están enamoradas?",
  ui_story_5043_50430401_27_dialog_content = "¡Dije que no estoy enamorado! Lo que sea, solo deja de molestarme, ¿de acuerdo?",
  ui_story_5043_50430401_28_dialog_content = "De todos modos, parece que el globo está sobre el patio de Lumopolis, por lo que debe ser donde será la fiesta.",
  ui_story_5043_50430401_29_dialog_content = "Puaj. ¿Cómo es que tenemos que caminar aún más lejos? ¿Cuándo van a poner los Guardianes los carruajes en la Escalera a los Cielos?",
  ui_story_5043_50430401_30_dialog_content = "No todo el mundo puede permitirse el lujo de tomar carruajes, ya sabes.",
  ui_story_5043_50430401_31_dialog_content = "La Escalera a los cielos es la ruta principal desde Lumopolis Courtyard hasta Lumopolis Gardens.",
  ui_story_5043_50430401_32_dialog_content = "¿Estás listo para sumergirte en el mundo de los plebeyos, Matthieu?",
  ui_story_5043_50430401_33_dialog_content = "¡Cállate!",
  ui_story_5043_50430401_34_dialog_content = "<color=#e8d9bb>Patio de Lumopolis, Plaza de la Pradera</color>",
  ui_story_5043_50430401_35_dialog_content = "Guau-",
  ui_story_5043_50430401_36_dialog_content = "No sabía que Lumopolis Courtyard tenía un espacio verde tan hermoso. Es espectacular.",
  ui_story_5043_50430401_37_dialog_content = "Creo que se acaba de construir esta primavera. Usan Luminatics para mantenerlo.",
  ui_story_5043_50430401_38_dialog_content = "Oye, ¿escuchas eso?",
  ui_story_5043_50430401_39_dialog_content = "Parece que están tocando música en medio de la plaza, justo debajo del globo.",
  ui_story_5043_50430401_39X1_dialog_content = "Según lo que escuché, hay tres partes en el salón: una reunión, un baile y una sesión de apreciación de poesía.",
  ui_story_5043_50430401_40_dialog_content = "Mm... música de baile bastante estándar. Sabor sorprendentemente aceptable.",
  ui_story_5043_50430401_40X1_dialog_content = "Jóvenes, ¿es la primera vez que asisten al Salón Moonlight?",
  ui_story_5043_50430401_40X2_dialog_content = "¡No te quedes parado! ¡Venir venir!",
  ui_story_5043_50430401_40X3_dialog_content = "¡Ey! Espera, no me jales... ¡Dios mío, no puedo soportar esto!",
  ui_story_5043_50430401_41_dialog_content = "¡Debemos haber llegado a tiempo para el baile!",
  ui_story_5043_50430401_42_dialog_content = "Es de mala educación pararse a un lado con la espalda contra la pared. ¡Unámonos a ellos y observemos a la multitud mientras lo hacemos!",
  ui_story_5043_50430401_43_dialog_content = "P-Pero... ¡No sé nada sobre bailes o costumbres nobles!",
  ui_story_5043_50430401_44_dialog_content = "Y tengo dos pies izquierdos.",
  ui_story_5043_50430401_45_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5043_50430401_46_dialog_content = "Entonces... ¿Por qué soy yo el que está atrapado bailando con el plebeyo? ¡Me siento enferma!",
  ui_story_5043_50430401_47_dialog_content = "¿Crees que estoy disfrutando esto?",
  ui_story_5043_50430401_48_dialog_content = "¡Ay!",
  ui_story_5043_50430401_49_dialog_content = "Mira dónde pones los pies, tonto, ¡ay!",
  ui_story_5043_50430401_50_dialog_content = "¡Lo estás haciendo deliberadamente!",
  ui_story_5043_50430401_51_dialog_content = "¿¡Oye, qué haces aquí!?",
  ui_story_5043_50430401_52_dialog_content = "¡Para! ¡No me tires del pelo!",
  ui_story_5043_50430401_53_dialog_content = "¡Jajaja! Parece que se están divirtiendo.",
  ui_story_5043_50430401_54_dialog_content = "PlayerName, ¿Estás nervioso?",
  ui_story_5043_50430401_55_dialog_content = "No, no, estoy bien.",
  ui_story_5043_50430401_56_dialog_content = "Ir a la izquierda, levantar el pie, volver a la derecha, girar...",
  ui_story_5043_50430401_57_dialog_content = "HHH-¿¡Cómo te golpeó la mano!?",
  ui_story_5043_50430401_58_dialog_content = "No te preocupes, es solo un baile amistoso.",
  ui_story_5043_50430401_59_dialog_content = "¿Por qué no lo intentamos de nuevo?",
  ui_story_5043_50430401_60_dialog_content = "Bueno. Lo haré mejor esta vez.",
  ui_story_5043_50430401_61_dialog_content = "Ja ja. Mira, puedes hacerlo.",
  ui_story_5043_50430401_62_dialog_content = "Aprendes rápido.",
  ui_story_5043_50430401_63_dialog_content = "¡Uf! Bailar es un verdadero ejercicio.",
  ui_story_5043_50430401_64_dialog_content = "No quiero volver a hacer esto...",
  ui_story_5043_50430401_65_dialog_content = "Tch, si no fuera tan amable, te demandaría.",
  ui_story_5043_50430401_66_dialog_content = "¿Dónde desapareció Loewe?",
  ui_story_5043_50430401_67_dialog_content = "Parece que me perdí toda la diversión.",
  ui_story_5043_50430401_68_dialog_content = "Vi algunos personajes sospechosos afuera antes. Definitivamente no eran participantes del salón.",
  ui_story_5043_50430401_69_dialog_content = "Fui a investigar y me encontré con Lady Carleen.",
  ui_story_5043_50430401_70_dialog_content = "Gracias por mostrarme el camino. Y esos personajes sospechosos están conmigo, en realidad.",
  ui_story_5043_50430401_71_dialog_content = "¡Guau! Dama Carleen, tu también viniste!",
  ui_story_5043_50430401_72_dialog_content = "Cuál es la última, Carleen? ¿Algún progreso en la incursión al Eclipsite?",
  ui_story_5043_50430401_73_dialog_content = "No, pero he eliminado algunas posibilidades.",
  ui_story_5043_50430401_74_dialog_content = "Los pases de viaje están todos en orden, por lo que no podrían haberse colado en Lumopolis disfrazados.",
  ui_story_5043_50430401_75_dialog_content = "La Guardia Nocturna ha estado haciendo su trabajo y no hay agujeros en el escudo sobre Lumopolis.",
  ui_story_5043_50430401_76_dialog_content = "Últimamente ha habido más movimiento de mercancías y mercenarios, debido a todos los festivales.",
  ui_story_5043_50430401_77_dialog_content = "Así que es posible que los guardias no hayan estado registrando los envíos de mercancías correctamente y que los Eclipsites hayan estado escabulléndose de esa manera.",
  ui_story_5043_50430401_78_dialog_content = "¿Eh? ¿Estás buscando infiltrados en Eclipsites?",
  ui_story_5043_50430401_79_dialog_content = "En ese caso... tengo que encontrarlo lo antes posible.",
  ui_story_5043_50430401_80_dialog_content = "No creo que tengas que preocuparte por él. Estoy seguro de que está perfectamente a salvo.",
  ui_story_5043_50430401_81_dialog_content = "¿D-De verdad...?",
  ui_story_5043_50430401_82_dialog_content = "(La preocupación de Tina parece realmente extraña...)",
  ui_story_5043_50430401_83_dialog_content = "Bueno, el jefe Eclipsite debe saber algún tipo de <color=#FFB400>habilidad de camuflaje</color> para poder mezclarse con la multitud.",
  ui_story_5043_50430401_84_dialog_content = "No he autorizado una búsqueda completa porque no quiero causar pánico.",
  ui_story_5043_50430401_85_dialog_content = "Acabo de poner algunos guardias vestidos de civil y les dije que vigilen las áreas concurridas, por si acaso.",
  ui_story_5043_50430401_86_dialog_content = "Sabes, Carleen, eso se parece mucho a lo que el Señor de la Ciudad está haciendo con los casos del Día de la Corona de la Luna.",
  ui_story_5043_50430401_87_dialog_content = "... No lo considero un cumplido.",
  ui_story_5043_50430401_88_dialog_content = "Erm... Lo siento. ¿Qué tal si me disculpo ayudando un poco?",
  ui_story_5043_50430401_89_dialog_content = "Al menos podría confirmar que no hay Eclipses entre la multitud aquí...",
  ui_story_5043_50430401_90_option_content = "¡Potencia de fuerza!",
  ui_story_5043_50430401_91_dialog_content = "Gracias, PlayerName.",
  ui_story_5043_50430401_92_dialog_content = "¿Bien? ¿Algo inusual?",
  ui_story_5043_50430401_93_dialog_content = "Oh...",
  ui_story_5043_50430401_94_dialog_content = "Lo siento. Es demasiado ocupado y ruidoso aquí. No funciona.",
  ui_story_5043_50430401_95_dialog_content = "Dama Carleen! PlayerName! ¡Ey!",
  ui_story_5043_50430401_96_dialog_content = "No te quedes ahí parado. ¡Ven aquí!",
  ui_story_5043_50430401_97_dialog_content = "Como ya estoy aquí... vamos a ver qué pasa.",
  ui_story_5043_50430401_98_dialog_content = "Ese globo es realmente impresionante de cerca.",
  ui_story_5043_50430401_99_dialog_content = "Dama Carleen, tu tambien lo crees?",
  ui_story_5043_50430401_100_dialog_content = "Prados primaverales, parejas enamoradas, un coro cantando de fondo...",
  ui_story_5043_50430401_101_dialog_content = "Y bajo una luna rara vez vista, todos suben los escalones mientras intercambian pensamientos intelectuales, independientemente de sus clases...",
  ui_story_5043_50430401_102_dialog_content = "Vaya, es como algo sacado de un cuento de hadas.",
  ui_story_5043_50430401_103_dialog_content = "Pensamientos intelectuales, mi trasero. Esto es solo un festival de amor cursi para parejas que salen.",
  ui_story_5043_50430401_104_dialog_content = "Y nunca antes había visto tantos plebeyos en un solo lugar. El lugar apesta a Lower Lumopolis. Qué asco.",
  ui_story_5043_50430401_105_dialog_content = "Bueno, ya es demasiado tarde.",
  ui_story_5043_50430401_106_dialog_content = "Oye, plebeyo. ¿A que estas mirando?",
  ui_story_5043_50430401_107_dialog_content = "Estaba pensando... ese globo lunar es un poco extraño.",
  ui_story_5043_50430401_108_dialog_content = "No está atado al suelo pero permanece en un solo lugar. Me pregunto si lo están controlando con Luminatics.",
  ui_story_5043_50430401_109_dialog_content = "No importa. Solo las tontas preocupaciones de un plebeyo ordinario. ¿Por qué molestarse en preguntar lo que pienso?",
  ui_story_5043_50430401_110_dialog_content = "Tiene razón, señor. Y lo que es más...",
  ui_story_5043_50430401_111_dialog_content = "La Luminatics también mantiene la <color=#FFB400>regalos de festivales antiguos</color> dentro del globo.",
  ui_story_5043_50430401_112_dialog_content = "Lo siento, ¿eres...?",
  ui_story_5043_50430401_113_dialog_content = "Oh, solo una monja de Lumopolis. Puedes llamarme Hermana.",
  ui_story_5043_50430401_114_dialog_content = "Soy el organizador de estos Salones Moonlight.",
  ui_story_5043_50430401_115_dialog_content = "Y no creo haberte visto aquí antes. Espero que te estés divirtiendo.",
  ui_story_5043_50430401_116_dialog_content = "B-Bueno, no he estado aquí mucho tiempo. Todo parece muy emocionante.",
  ui_story_5043_50430401_117_dialog_content = "No se parece en nada a la Lumopolis que conozco.",
  ui_story_5043_50430401_118_dialog_content = "Jejeje Gracias y que el Dios de la Luz los bendiga. Los dejo para que se diviertan.",
  ui_story_5043_50430401_119_dialog_content = "Por favor, sírvanse el té y los postres. Y no te olvides de disfrutar del coro.",
  ui_story_5043_50430401_120_dialog_content = "(Ese coro... por favor no me digas...)",
  ui_story_5043_50430401_121_dialog_content = "Así que has venido a la fiesta de la luna. ♪",
  ui_story_5043_50430401_122_dialog_content = "Pero es un globo. ♪",
  ui_story_5043_50430401_123_dialog_content = "Los vemos deambular y mezclarse. ♪",
  ui_story_5043_50430401_124_dialog_content = "¿Sigues soltero? ¿Aún soltero? ♪",
  ui_story_5043_50430401_125_dialog_content = "¿Ver? Que lindos niños.",
  ui_story_5043_50430401_126_dialog_content = "¿Lindo? ¡Como si!",
  ui_story_5043_50430401_127_dialog_content = "¡Dale un golpe! Fatty hace pop! ♪",
  ui_story_5043_50430401_128_dialog_content = "¡Colgando allí, en lo alto de la cima! ♪",
  ui_story_5043_50430401_129_dialog_content = "¿Qué es lo que aparece tan pronto? ♪",
  ui_story_5043_50430401_130_dialog_content = "Tal vez un noble, tal vez un globo. ♪",
  ui_story_5043_50430401_131_dialog_content = "Ah, consiguieron el Dawn Coro de la academia para cantar para ellos, ¿eh?",
  ui_story_5043_50430401_132_dialog_content = "Veo que se están apegando a su estilo habitual.",
  ui_story_5043_50430401_133_dialog_content = "Hombres y mujeres coquetean bajo la luz de la luna. ♪",
  ui_story_5043_50430401_134_dialog_content = "Nobles y plebeyos comparten mesa y no pelean. ♪",
  ui_story_5043_50430401_135_dialog_content = "¡Oh honorable monja, linda monja! ♪",
  ui_story_5043_50430401_136_dialog_content = "¡Tus salones seguro que son divertidos! ♪",
  ui_story_5043_50430401_137_dialog_content = "No estoy seguro de que sus letras tengan mucho sentido, pero son buenos cantantes...",
  ui_story_5043_50430401_138_dialog_content = "Escuchar un coro siempre me da ganas de orar.",
  ui_story_5043_50430401_139_dialog_content = "Noche Blanca en lo alto, oh, Dios de la Luz, permíteme encontrarlo.",
  ui_story_5043_50430401_140_dialog_content = "No estoy del todo seguro de que el Dios de la Luz esté a cargo de estos asuntos...",
  ui_story_5043_50430401_141_dialog_content = "Todos en Lumopolis pueden alabar al Dios de la Luz. ♪",
  ui_story_5043_50430401_142_dialog_content = "¿Pero un noble se casa con un plebeyo? ¡Eso no está bien! ♪",
  ui_story_5043_50430401_143_dialog_content = "¡Oh honorable monja, pobre monja! ♪",
  ui_story_5043_50430401_144_dialog_content = "Viene el desastre. ¡Tú! ¡Debería! ¡Correr! ♪",
  ui_story_5043_50430401_145_dialog_content = "¡¿Esperar lo?!",
  ui_story_5043_50430401_146_dialog_content = "¡Limpiar el area! Quiero que arresten a todos los que asisten a esta reunión ilegal.",
  ui_story_5043_50430401_147_dialog_content = "¡Y tráeme el organizador!",
  ui_story_5043_50430401_148_dialog_content = "¡Eek!",
  ui_story_5043_50430401_149_dialog_content = "¡Los guardianes de Lumopolis Gardens! ¡Correr!",
  ui_story_5043_50430401_150_dialog_content = "Soy un noble de Uptown. no se atreverían...",
  ui_story_5043_50430401_151_dialog_content = "¿Ehhhh?",
  ui_story_5043_50430401_152_dialog_content = "¡Ay! Mi <color=#FFB400>galletas</color>!",
  ui_story_5043_50430401_153_dialog_content = "I <color=#FFB400>perdido</color> las galletas que le iba a dar!",
  ui_story_5043_50430401_154_dialog_content = "<color=#e8d9bb>*multitud murmurando*</color>",
  ui_story_5043_50430401_155_dialog_content = "(Esto no puede ser. ¡Estos no son mis guardias!)",
  ui_story_5043_50430401_156_dialog_content = "¡Yo no di tales órdenes! Quien se atreve...",
  ui_story_5043_50430401_157_dialog_content = "Capitán Carleen!",
  ui_story_5043_50430401_158_dialog_content = "No son Guardianes de Lumopolis Gardens.",
  ui_story_5043_50430401_159_dialog_content = "Pero pocos otros nobles tienen tales fuerzas.",
  ui_story_5043_50430401_160_dialog_content = "¡Los asistentes a la fiesta asumirán que esta incursión ha sido ordenada por Lumopolis Gardens!",
  ui_story_5043_50430401_161_dialog_content = "Veo lo que estás diciendo. Pero primero tenemos que restablecer el orden.",
  ui_story_5043_50430401_162_dialog_content = "Por favor, no se asuste. ¡Sígueme!",
  ui_story_5043_50430401_163_dialog_content = "<color=#e8d9bb>Aplastar-!</color>",
  ui_story_5043_50430401_164_dialog_content = "(¡¿Que fue ese ruido?!)",
  ui_story_5043_50430401_165_dialog_content = "PlayerName, Paladín giratorio, necesito tu ayuda.",
  ui_story_5043_50430401_166_dialog_content = "¡Únete a mis guardias de paisano y enfréntate a estos soldados, sean quienes sean!",
  ui_story_5043_50430401_167_dialog_content = "¡Encantado de ayudarle!",
  ui_story_5043_50430401_168_dialog_content = "¡Como desées!",
  ui_story_5043_50430501_1_dialog_content = "¡Esos guardias corren rápido!",
  ui_story_5043_50430501_2_dialog_content = "Capitán, ¿debo perseguirlo?",
  ui_story_5043_50430501_3_dialog_content = "No te molestes. Tienes otro trabajo que hacer.",
  ui_story_5043_50430501_4_dialog_content = "Sin embargo, es una pena. El Salón Moonlight está arruinado y no encontramos a quien buscábamos.",
  ui_story_5043_50430501_5_dialog_content = "¿Oh? ¿A quién estabas buscando?",
  ui_story_5043_50430501_6_dialog_content = "Tina quería encontrar a Schwab y darle algo a cambio de su regalo del Día de la Corona de la Luna.",
  ui_story_5043_50430501_7_dialog_content = "Oh, no sabía que ellos dos tenían este tipo de relación.",
  ui_story_5043_50430501_8_dialog_content = "Así que ese es el poder del Día de la Corona de la Luna. Jóvenes enamorándose sin que sus familias hagan arreglos previos.",
  ui_story_5043_50430501_9_dialog_content = "Pero... si puedo ser franco, ¿qué ve ella en ese playboy?",
  ui_story_5043_50430501_10_dialog_content = "Yo se, verdad...?",
  ui_story_5043_50430501_11_dialog_content = "Oye, ¿alguien ha visto a Loewe?",
  ui_story_5043_50430501_12_dialog_content = "No lo he visto desde que esos guardias huyeron.",
  ui_story_5043_50430501_13_dialog_content = "Lo envié a averiguar de dónde venían. Deberías seguir investigando tu caso.",
  ui_story_5043_50430501_14_dialog_content = "Ya tengo una muy buena idea de lo que pasó. Pero lo mejor es asegurarse.",
  ui_story_5043_50430501_15_dialog_content = "E-Esto no es bueno.",
  ui_story_5043_50430501_16_dialog_content = "Sé que sé. Tus cookies se han perdido, ¿verdad?",
  ui_story_5043_50430501_17_dialog_content = "Vamos a buscarlos. Probablemente estén mezclados con todos estos líos.",
  ui_story_5043_50430501_18_dialog_content = "¡Oh, desearía que ese fuera el único problema!",
  ui_story_5043_50430501_19_dialog_content = "Es la estatua a la entrada de la plaza. Es...",
  ui_story_5043_50430501_20_dialog_content = "Llegó <color=#FFB400>roto</color> durante todo el caos.",
  ui_story_5043_50430501_21_dialog_content = "¿¡Qué!?",
  ui_story_5043_50430501_22_dialog_content = "Escuché que algo se rompía mientras todos corrían.",
  ui_story_5043_50430501_23_dialog_content = "Lo extraño es que se rompió exactamente de la misma manera que lo hizo en el Salón de la Justicia.",
  ui_story_5043_50430501_24_dialog_content = "Es como si hubiera decapitadores de estatuas en el trabajo.",
  ui_story_5043_50430501_25_dialog_content = "Hmm... Creo que deberíamos ir e informar a nuestro juez principal temporal entonces.",
  ui_story_5043_50430501_26_dialog_content = "Sí. Y si no está aquí en el Salón Moonlight, entonces debe estar...",
  ui_story_5043_50430501_27_dialog_content = "<color=#e8d9bb>Jardines de Lumopolis, oficina de Schwab</color>",
  ui_story_5043_50430501_28_dialog_content = "Mmm... Está bien, lo tengo.",
  ui_story_5043_50430501_29_dialog_content = "Me alegro de que hayas vuelto. Necesito que dejes de lado el caso de la estatua por ahora, hasta que el demandante actualice su solicitud.",
  ui_story_5043_50430501_30_dialog_content = "Tenemos un nuevo caso de romance a punto de comenzar. Así que prepárense, mis queridos subordinados.",
  ui_story_5043_50430501_31_dialog_content = "¿Eso es todo?",
  ui_story_5043_50430501_32_dialog_content = "Así es la vida en la División Romance. Moviéndose constantemente hacia adelante, como un carruaje impulsado por Luminatics.",
  ui_story_5043_50430501_33_dialog_content = "Es muy difícil para ti entender, mi pequeño diente de león, ya que no eres el juez principal.",
  ui_story_5043_50430501_34_dialog_content = "D-Pequeño diente de león???",
  ui_story_5043_50430501_35_dialog_content = "(¿Me acaba de llamar pequeño diente de león? Qué nauseabundo).",
  ui_story_5043_50430501_36_dialog_content = "Te acostumbrarás, PlayerName...",
  ui_story_5043_50430501_37_dialog_content = "En realidad, el juez presidente Schwab, Tina tiene algo que ella quiere—",
  ui_story_5043_50430501_38_dialog_content = "No estoy seguro de que este sea el mejor momento para eso.",
  ui_story_5043_50430501_39_dialog_content = "(Sí. ¿Qué es Leyn ¿haciendo? No tengo nada que decirle a Schwab.)",
  ui_story_5043_50430501_40_dialog_content = "¿Mmm? Parece que mis subordinados están trabajando tan bien juntos que incluso tienen pequeños secretos para mí.",
  ui_story_5043_50430501_41_dialog_content = "De todos modos, aquí está la acusación y todo el papeleo. Todo es muy sencillo. ¡Te veo en la corte!",
  ui_story_5043_50430501_42_dialog_content = "Tiene razón, parece fácil. Y tiene que ver con el salón Moonlight en el que estuvimos...",
  ui_story_5043_50430501_43_dialog_content = "¿Eh? ¡Espera un minuto! ¡Todos, miren el motivo del caso!",
  ui_story_5043_50430501_44_dialog_content = "<color=#e8d9bb>Sala de Justicia, División Romance</color>",
  ui_story_5043_50430501_45_dialog_content = "El Señor de la Ciudad no hace las cosas a medias. ¡Mira el tamaño de este lugar!",
  ui_story_5043_50430501_46_dialog_content = "Y dada la cantidad de casos que manejamos en nuestro primer día, también obtiene una buena relación calidad-precio.",
  ui_story_5043_50430501_47_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5043_50430501_48_dialog_content = "¡La corte está en sesión!",
  ui_story_5043_50430501_49_dialog_content = "Primero, ¡presentemos a las partes involucradas en el litigio de hoy!",
  ui_story_5043_50430501_50_dialog_content = "El demandante es... un hombre de Lower Lumopolis, cuyo nombre no se puede identificar por razones de privacidad.",
  ui_story_5043_50430501_51_dialog_content = "La acusada es... una mujer de Lower Lumopolis, cuyo nombre no se puede identificar por razones de privacidad.",
  ui_story_5043_50430501_52_dialog_content = "(¡No escuché nada de eso!)",
  ui_story_5043_50430501_53_dialog_content = "Yo, Schwab Salar, presidiré como juez principal en el juicio de hoy.",
  ui_story_5043_50430501_54_dialog_content = "El tribunal judicial está compuesto por Matthieu Aserrador, Tina Campbell, y Leyn...",
  ui_story_5043_50430501_55_dialog_content = "Así como varios otros miembros de la corte.",
  ui_story_5043_50430501_56_dialog_content = "(¡Guau! Schwab en realidad parece bastante competente cuando se lo propone...)",
  ui_story_5043_50430501_57_dialog_content = "Si nadie tiene objeciones a nada de eso, podemos proceder.",
  ui_story_5043_50430501_58_dialog_content = "Aférrate. ¿Cómo es que todos somos simplemente \"otros miembros de la corte\"?",
  ui_story_5043_50430501_59_dialog_content = "¿Sin objeciones? Muy bien, comencemos.",
  ui_story_5043_50430501_60_dialog_content = "¿Si el demandante pudiera contarnos los hechos del caso?",
  ui_story_5043_50430501_61_dialog_content = "*sollozando* Esto es lo que pasó...",
  ui_story_5043_50430501_62_dialog_content = "Mi prometida, la acusada, y yo fuimos a Meadow Square en Lumopolis Courtyard para el Moonlight Salon...",
  ui_story_5043_50430501_63_dialog_content = "P-Pero ella...",
  ui_story_5043_50430501_64_dialog_content = "Por favor, no llores. Solo cuéntanos qué pasó.",
  ui_story_5043_50430501_65_dialog_content = "La amo tanto. ¡Llevamos juntos cuatro años! Le gusta tomar café con chocolate y—",
  ui_story_5043_50430501_66_dialog_content = "Si pudiera ceñirse a los asuntos relevantes, por favor.",
  ui_story_5043_50430501_67_dialog_content = "L-Lo siento. Oh, siempre hago un lío de todo...",
  ui_story_5043_50430501_68_dialog_content = "Fuimos al Moonlight Salon y lo pasamos muy bien. ¡Pero luego se enojó de repente y dijo que quería terminar conmigo!",
  ui_story_5043_50430501_69_dialog_content = "Quiero decir... ¿Qué le diría a mi familia? *sollozando*",
  ui_story_5043_50430501_70_dialog_content = "Muy bien. A continuación, el acusado.",
  ui_story_5043_50430501_71_dialog_content = "Yo tenía mis razones.",
  ui_story_5043_50430501_72_dialog_content = "Este hombre, el demandante, me llevó a una cita.",
  ui_story_5043_50430501_73_dialog_content = "¡Sin embargo, se atrevió a aceptar un regalo de otro!",
  ui_story_5043_50430501_74_dialog_content = "(Está actuando como si fuera la demandante).",
  ui_story_5043_50430501_75_dialog_content = "Yo no...",
  ui_story_5043_50430501_76_dialog_content = "Entonces, ¿puedes explicarme dónde está esa canasta de <color=#FFB400>galletas</color> ¿vino de?",
  ui_story_5043_50430501_77_dialog_content = "(¿Galletas? Son esas...)",
  ui_story_5043_50430501_78_dialog_content = "¡Allá! ¡Esa es la evidencia!",
  ui_story_5043_50430501_79_dialog_content = "Los pones en tu silla. Y hay una tarjeta.",
  ui_story_5043_50430501_80_dialog_content = "Y se pone peor. Quien escribió la tarjeta usa la misma <color=#FFB400>nombre de mascota</color> por ti que hago!",
  ui_story_5043_50430501_81_dialog_content = "Oh, estoy acabado.",
  ui_story_5043_50430501_82_dialog_content = "Teníamos razón. Estos dos encontraron las galletas que Tina había perdido.",
  ui_story_5043_50430501_83_dialog_content = "<color=#e8d9bb>¡Tom, tom, tom!</color>",
  ui_story_5043_50430501_84_dialog_content = "¡Ordenar!",
  ui_story_5043_50430501_85_dialog_content = "Cualquier ciudadano de Lumopolis encontrado en desacato al tribunal será condenado a muerte... ¡Es broma!",
  ui_story_5043_50430501_86_dialog_content = "<size=32>Ey, Tina. ¿Es esa la canasta de galletas que perdiste?</size>",
  ui_story_5043_50430501_87_dialog_content = "<size=32>¿eh? Es eso PlayerName?</size>",
  ui_story_5043_50430501_88_dialog_content = "<size=32>¡No puedes hablar conmigo cuando el tribunal está en sesión!</size>",
  ui_story_5043_50430501_89_dialog_content = "<size=32>En ese caso...</size>",
  ui_story_5043_50430501_90_option_content = "¡Potencia de fuerza!",
  ui_story_5043_50430501_91_dialog_content = "¡Oh, vaya! ¿Es esta tu habilidad Caelestite? Siempre me lo he preguntado.",
  ui_story_5043_50430501_92_dialog_content = "No importa eso ahora. Así que esas son tus galletas, ¿verdad?",
  ui_story_5043_50430501_93_dialog_content = "¡Sí, son míos! No puedo creer que haya causado tantos problemas a estas personas inocentes...",
  ui_story_5043_50430501_94_dialog_content = "PlayerName, ¿que crees que deberia hacer?",
  ui_story_5043_50430501_95_option_content = "Se honesto",
  ui_story_5043_50430501_96_dialog_content = "Creo que deberías admitir lo que pasó. Las cookies son suyas, pero estaban destinadas a dárselas a otra persona.",
  ui_story_5043_50430501_97_dialog_content = "Pero supongo que este no es el mejor momento para que Schwab escuche la verdad.",
  ui_story_5043_50430501_98_dialog_content = "Así que lo entendería si no estuvieras muy interesado en la idea.",
  ui_story_5043_50430501_99_dialog_content = "¿Eh? ¿Schwab? ¿Oír qué verdad?",
  ui_story_5043_50430501_100_option_content = "Espera y verás",
  ui_story_5043_50430501_101_dialog_content = "Creo que deberías esperar y ver cómo resultan las cosas.",
  ui_story_5043_50430501_102_dialog_content = "Si empieza a hablar ahora, corre el riesgo de que lo declaren en desacato al tribunal.",
  ui_story_5043_50430501_103_dialog_content = "Entonces, ¿qué hará el tribunal a continuación?",
  ui_story_5043_50430501_104_dialog_content = "Luego escuchamos argumentos de ambos lados.",
  ui_story_5043_50430501_105_dialog_content = "no estoy seguro de por qué PlayerName está tan interesado. Pero dejaré que Schwab continúe con el caso.",
  ui_story_5043_50430501_106_dialog_content = "Dado que tanto el demandante como el demandado parecen tan interesados en continuar, ahora escucharemos más argumentos.",
  ui_story_5043_50430501_107_dialog_content = "<size=32>¡Escucha, plebeyo! Esta no es la manera de hacer las cosas.</size>",
  ui_story_5043_50430501_108_dialog_content = "<size=32>Necesitamos hacer algo. Pero no podemos avergonzar Tina.</size>",
  ui_story_5043_50430501_109_dialog_content = "<size=32>Estoy de acuerdo. Pero no sabemos qué Tina quiere hacer.</size>",
  ui_story_5043_50430501_110_dialog_content = "<size=32>Ella no está hablando por sí misma. Entonces... ¿y si ayudamos a Schwab a descubrirlo por sí mismo?</size>",
  ui_story_5043_50430501_111_dialog_content = "<size=32>¡No está mal, chico! Buena idea.</size>",
  ui_story_5043_50430501_112_dialog_content = "Los jueces ahora comenzarán con los contrainterrogatorios.",
  ui_story_5043_50430501_113_dialog_content = "Ejem. Demandante, usted dice que esta canasta de galletas no es suya. ¿Podría decirnos a quién pertenece?",
  ui_story_5043_50430501_114_dialog_content = "Yo... no tengo ni idea. De repente apareció en la mesa frente a mí.",
  ui_story_5043_50430501_115_dialog_content = "solo puedo asumir <color=#FFB400>alguien lo dejo ahi</color>.",
  ui_story_5043_50430501_116_dialog_content = "Entonces, ¿diría que alguien que asistió al Salón Moonlight perdió la canasta de galletas?",
  ui_story_5043_50430501_117_dialog_content = "Y estoy seguro de que todos podemos imaginar para qué estaba destinado.",
  ui_story_5043_50430501_118_dialog_content = "Sí. Quiero decir, debe haber sido pensado como un <color=#FFB400>regalo</color>.",
  ui_story_5043_50430501_119_dialog_content = "Pero no es un regalo para mí. No tengo nada que ver con eso.",
  ui_story_5043_50430501_120_dialog_content = "Entonces me gustaría preguntarle al acusado, ¿por qué está tan seguro de que su amante le ha sido desleal?",
  ui_story_5043_50430501_121_dialog_content = "Seguro que es obvio. Cualquiera puede ver que la canasta de galletas fue un regalo de un <color=#FFB400>mujer</color>.",
  ui_story_5043_50430501_122_dialog_content = "No se atrevería a aceptar tal regalo a menos que estuviera planeando romper conmigo.",
  ui_story_5043_50430501_123_dialog_content = "Y aquí está el meollo del asunto. El demandante insiste en que no aceptó ningún regalo. Crees que lo hizo.",
  ui_story_5043_50430501_124_dialog_content = "Pero el mensaje en el <color=#FFB400>tarjeta</color> es claramente de un amante...",
  ui_story_5043_50430501_125_dialog_content = "Ah, okey. Quizá me apresuré demasiado. Pero entonces, ¿a quién estaban destinadas las cookies?",
  ui_story_5043_50430501_126_dialog_content = "¡Esa es la pregunta crucial!",
  ui_story_5043_50430501_127_dialog_content = "¡Y el destinatario previsto está aquí mismo!",
  ui_story_5043_50430501_128_dialog_content = "Aquí mismo...?",
  ui_story_5043_50430501_129_dialog_content = "<color=#e8d9bb>¡Tom, tom, tom!</color>",
  ui_story_5043_50430501_130_dialog_content = "Juez Leyn, Juez Matthieu, por favor no haga declaraciones de carácter tendencioso al acusado.",
  ui_story_5043_50430501_131_dialog_content = "Este es un tribunal. Culpable significa culpable.",
  ui_story_5043_50430501_132_dialog_content = "Ah, pero el juez presidente Schwab... Eres tan guapo, tan popular entre las damas. ¿Cómo puedes soportar interrumpir a una doncella tan hermosa?",
  ui_story_5043_50430501_133_dialog_content = "Y aquí está la prueba del amor de una dama por ti, pero no te das cuenta de quién es esa dama.",
  ui_story_5043_50430501_134_dialog_content = "¡Oh! Creo entender. Quiere decir que las cookies en realidad estaban destinadas a...",
  ui_story_5043_50430501_135_dialog_content = "¿Ah?",
  ui_story_5043_50430501_136_dialog_content = "¡Ordenar!",
  ui_story_5043_50430501_137_dialog_content = "¡Silencio en la corte! deseo hablar",
  ui_story_5043_50430501_138_dialog_content = "Juez Tina¡No puedes interrumpir los asuntos de la corte de esta manera!",
  ui_story_5043_50430501_139_dialog_content = "Juez presidente Schwab, como propietario de las cookies de evidencia, deseo hacer una <color=#FFB400>declaración de un testigo</color>.",
  ui_story_5043_50430501_140_dialog_content = "(Attachica, Tina! ¡Ese es el espíritu!)",
  ui_story_5043_50430501_141_dialog_content = "O-Está bien. El tribunal está de acuerdo. Puede hablar, testigo.",
  ui_story_5043_50430501_142_dialog_content = "Hice las galletas.",
  ui_story_5043_50430501_143_dialog_content = "Los hice yo mismo, con manos amorosas y un corazón palpitante.",
  ui_story_5043_50430501_144_dialog_content = "Batí la mantequilla. Canalicé los bonitos diseños. Los horneé hasta que adquirieron un color amarillo dorado y elegí los que se veían mejor.",
  ui_story_5043_50430501_145_dialog_content = "Todo para poder hacerle un regalo perfecto.",
  ui_story_5043_50430501_146_dialog_content = "Pero luego los perdí a todos en el Salón Moonlight.",
  ui_story_5043_50430501_147_dialog_content = "¡Y esta tarjeta es la prueba!",
  ui_story_5043_50430501_148_dialog_content = "Yo mismo hice esa tarjeta. Puedo decirle el nombre en la tarjeta y todo lo que está escrito en ella.",
  ui_story_5043_50430501_149_dialog_content = "¡Oh! ¿En realidad? Es tan extraño que nos hayamos conocido así...",
  ui_story_5043_50430501_150_dialog_content = "Es como una hermosa historia de amor.",
  ui_story_5043_50430501_151_dialog_content = "No sé qué hacer con ustedes, mis lindos. Todos ustedes son una carga tan encantadora para mí.",
  ui_story_5043_50430501_152_dialog_content = "¿Quizás el testigo y el acusado puedan confirmar lo que está escrito en la tarjeta? Entonces podemos concluir este caso.",
  ui_story_5043_50430501_153_dialog_content = "Bueno. Leámoslo juntos.",
  ui_story_5043_50430501_154_dialog_content = "Buena idea. Tres. Dos. ¡Uno!",
  ui_story_5043_50430501_155_dialog_content = "<size=45><color=#FFB400>Totó</color>!</size>",
  ui_story_5043_50430501_X156_dialog_content = "¿Decir ah?",
  ui_story_5043_50430501_156_dialog_content = "¿¡Qué!?",
  ui_story_5043_50430501_157_dialog_content = "Vaya, juez presidente Schwab, siempre he oído hablar de lo famoso y elegante que es.",
  ui_story_5043_50430501_158_dialog_content = "Nunca imaginé que tendrías un apodo tan lindo.",
  ui_story_5043_50430501_159_dialog_content = "Te hace parecer un poco menos intimidante para nosotros, la gente de Lower Lumopolis.",
  ui_story_5043_50430501_160_dialog_content = "Cariño, por fin he recuperado tu confianza. *sollozando*",
  ui_story_5043_50430501_161_dialog_content = "Totó. Jejeje. Un nombre tan lindo.",
  ui_story_5043_50430501_162_dialog_content = "Schwab, ¿es ese un apodo de la infancia? ¿Algo que te llamó tu mami?",
  ui_story_5043_50430501_163_dialog_content = "¡Jajajajaja!",
  ui_story_5043_50430501_164_dialog_content = "Pero esto...",
  ui_story_5043_50430501_165_dialog_content = "¡Detener! ¿¡Qué está pasando exactamente!?",
  ui_story_5043_50430501_166_dialog_content = "Sí, ¿qué está pasando?",
  ui_story_5043_50430501_167_dialog_content = "¿Qué tienen que ver la tarjeta y las cookies con el juez presidente Schwab?",
  ui_story_5043_50430601_1_dialog_content = "Así que... supongo que eso es lo que pasó.",
  ui_story_5043_50430601_2_dialog_content = "Hice las galletas para Toto. Pero parece que el acusado tuvo una idea equivocada...",
  ui_story_5043_50430601_3_dialog_content = "Nunca imaginé que algo así sucedería. Al menos hemos aclarado el malentendido entre los dos amantes.",
  ui_story_5043_50430601_4_dialog_content = "¿Decir ah?",
  ui_story_5043_50430601_5_dialog_content = "No fueron los únicos con un malentendido.",
  ui_story_5043_50430601_6_dialog_content = "Entonces, ¿quién es este Toto? ¡Pensamos que te gustaba nuestro juez jefe idiota!",
  ui_story_5043_50430601_7_dialog_content = "Sí, aunque eso nunca tuvo mucho sentido. Pero, ¿dónde nos equivocamos?",
  ui_story_5043_50430601_8_dialog_content = "Que es mi culpa. Es una situación embarazosa, así que estaba siendo muy vago.",
  ui_story_5043_50430601_9_dialog_content = "Debí haber explicado mejor las cosas antes de pedirles ayuda a todos.",
  ui_story_5043_50430601_10_dialog_content = "Aunque no entiendo cómo te equivocaste, Schwab.",
  ui_story_5043_50430601_11_dialog_content = "Apenas hemos hablado aparte del trabajo normal y el chat social.",
  ui_story_5043_50430601_12_dialog_content = "Quiero decir, es obvio cuando le gustas a alguien, ¿verdad? Eso es algo que la gente puede decir.",
  ui_story_5043_50430601_13_dialog_content = "Suficiente. Por favor, no digas más.",
  ui_story_5043_50430601_14_dialog_content = "Todo esto es... irrelevante. El asunto importante en cuestión es...",
  ui_story_5043_50430601_15_dialog_content = "<size=45>¡Todos en el Salón de la Justicia piensan que mi apodo es Toto!</size>",
  ui_story_5043_50430601_16_dialog_content = "<size=45>Judge Jr. ¡¡¡y esos jueces asistentes en el panel ya deben habérselo dicho a todos!!!</size>",
  ui_story_5043_50430601_17_dialog_content = "<size=45>¡¡¡Y pronto todos los nobles de la sociedad de Lumopolis Gardens habrán escuchado las noticias!!!</size>",
  ui_story_5043_50430601_18_dialog_content = "<size=45>¡Y todo es por ti y esas estúpidas galletas y esa estúpida tarjeta!</size>",
  ui_story_5043_50430601_19_dialog_content = "<size=45>¡Sois un montón de imbéciles enamorados! Y pegajosas mujeres problemáticas...</size>",
  ui_story_5043_50430601_20_dialog_content = "<size=45>¡Todos sois iguales!</size>",
  ui_story_5043_50430601_21_dialog_content = "¡Lo siento mucho!",
  ui_story_5043_50430601_22_dialog_content = "Ey. Tina podría haber cometido un error. Pero estás siendo demasiado duro con ella, Schwab.",
  ui_story_5043_50430601_23_dialog_content = "No estoy exactamente seguro de lo que ha estado pasando. Me siento aliviado Tina Sin embargo, no está enamorado de Schwab.",
  ui_story_5043_50430601_24_dialog_content = "...",
  ui_story_5043_50430601_25_dialog_content = "Suspiro...",
  ui_story_5043_50430601_26_dialog_content = "Bien, volvamos a los negocios.",
  ui_story_5043_50430601_27_dialog_content = "La estatua rota en Lumopolis Courtyard no tiene nada que ver con el Sr. Byron.",
  ui_story_5043_50430601_28_dialog_content = "Lo cual es una suerte para ti. No quiero verlo aparecer con nuevas acusaciones.",
  ui_story_5043_50430601_29_dialog_content = "Ahora ve y prepárate para la audiencia del caso. ¡Adelante, fuera!",
  ui_story_5043_50430601_30_dialog_content = "<color=#e8d9bb>Fuera del Salón de la Justicia, Lumopolis Gardens</color>",
  ui_story_5043_50430601_31_dialog_content = "¡Ptui!",
  ui_story_5043_50430601_32_dialog_content = "Oye, ¿notaste mucho la expresión de Schwab?",
  ui_story_5043_50430601_33_dialog_content = "Estuviste genial, Tina. ¡Tan despiadado!",
  ui_story_5043_50430601_34_dialog_content = "Jejeje. Apuesto a que nunca antes una mujer le había hablado así.",
  ui_story_5043_50430601_35_dialog_content = "Oh, por favor no te burles de mí...",
  ui_story_5043_50430601_36_dialog_content = "Lo lamento. Nos metí a todos en problemas.",
  ui_story_5043_50430601_37_dialog_content = "Eso no importa. Pero lo que quiero saber es—",
  ui_story_5043_50430601_38_dialog_content = "Tina, ¿nos dijiste que conociste a este hombre en el jardín de la mansión de Schwab?",
  ui_story_5043_50430601_39_dialog_content = "Entonces, si no fue Schwab, ¿quién fue?",
  ui_story_5043_50430601_40_dialog_content = "Oh, este terrible malentendido es todo mi culpa.",
  ui_story_5043_50430601_41_dialog_content = "Déjame tratar de explicarlo bien...",
  ui_story_5043_50430601_42_dialog_content = "Estaba en el jardín de Salar Manor. Y me encontré con Schwab. Estaba sentado solo, leyendo y bebiendo té.",
  ui_story_5043_50430601_43_dialog_content = "Me notó de inmediato y se sorprendió de que alguien apareciera en un lugar tan apartado.",
  ui_story_5043_50430601_44_dialog_content = "Pero aunque me vio, no se dio cuenta de que había otro invitado inesperado cerca.",
  ui_story_5043_50430601_45_dialog_content = "En los arbustos detrás de Schwab, vi la cabecita peluda de Toto asomando entre las hojas. Estaba temblando mientras me miraba.",
  ui_story_5043_50430601_46_dialog_content = "Creo que estaba preocupado de que revelara su escondite. Después de todo, nadie quiere un Eclipsite en su seto.",
  ui_story_5043_50430601_47_dialog_content = "Pero era tan lindo y claramente inofensivo. La pobre se había perdido en aquel enorme jardín.",
  ui_story_5043_50430601_48_dialog_content = "De hecho, incluso lo había visto quitar algunas moscas de la taza de té de Schwab. Eso fue antes de que Schwab me notara.",
  ui_story_5043_50430601_49_dialog_content = "Después del Salón de la Luz de la Luna, corrí de regreso al jardín. Tomé su mano y lo conduje a salvo fuera de Salar Manor.",
  ui_story_5043_50430601_50_dialog_content = "Tuve que usar mis guantes nuevos para asegurarme de que mi Lumina y su Darkflow no chocaran.",
  ui_story_5043_50430601_51_dialog_content = "Podía entender Universese, aunque solo podía decir unas pocas palabras básicas. Y el Día de la Corona de Luna, poco después de conocernos, recibí un regalo de él.",
  ui_story_5043_50430601_52_dialog_content = "Eso es todo. Esa es toda la historia.",
  ui_story_5043_50430601_53_dialog_content = "(Wow. Así que incluso un pequeño Eclipsite ordinario tiene un nombre...)",
  ui_story_5043_50430601_54_dialog_content = "Aférrate. ¿No dijiste algo acerca de que él no respondía a tus cartas?",
  ui_story_5043_50430601_55_dialog_content = "Bueno, no tendrá una dirección en Lumopolis, ¿verdad? Le respondí a la dirección del remitente en el presente, pero nunca escuché nada.",
  ui_story_5043_50430601_56_dialog_content = "¿Y dijiste que no habías tenido la oportunidad de reunirte con él a escondidas?",
  ui_story_5043_50430601_57_dialog_content = "Sí. No nos hemos encontrado en absoluto. No puedo encontrarlo en ningún lado.",
  ui_story_5043_50430601_58_dialog_content = "Y cuando dijiste que se hace notar donde quiera que vaya...",
  ui_story_5043_50430601_59_dialog_content = "Seguramente puedes entender eso. Un eclipse en Lumopolis seguramente causará pánico.",
  ui_story_5043_50430601_60_dialog_content = "Así que... cuando negaste que estabas enamorado...",
  ui_story_5043_50430601_61_dialog_content = "Los eclipses viven para atacar a los aurorianos. ¿Existe tal cosa como un Eclipsite inofensivo?",
  ui_story_5043_50430601_62_dialog_content = "Si hay me encantaría ver uno para mí.",
  ui_story_5043_50430601_63_dialog_content = "Creo que es una especie de sentimiento innecesario, sí. Pero es demasiado raro llamarlo amor.",
  ui_story_5043_50430601_64_dialog_content = "No hablaría de ello en términos románticos. Solo quiero cuidar de él.",
  ui_story_5043_50430601_64X1_dialog_content = "Pero de todos modos, yo tampoco soporto los eclipses.",
  ui_story_5043_50430601_64X2_dialog_content = "*sniff sniff*",
  ui_story_5043_50430601_64X3_dialog_content = "Extrañar Tina, no estoy tratando de alarmar a nadie, pero pareces tener el hedor de un eclipse a tu alrededor.",
  ui_story_5043_50430601_64X4_dialog_content = "¿Eh? ¿Aún puedes olerlo después de tanto tiempo...? Lo siento...",
  ui_story_5043_50430601_65_dialog_content = "Como dije antes, la ley es la ley en Lumopolis. No puedo dejar pasar esto.",
  ui_story_5043_50430601_66_dialog_content = "No hay señales del Eclipsite que mencionaste en ninguna de las hojas de arresto de los guardias.",
  ui_story_5043_50430601_67_dialog_content = "Entonces, ¿debería llevarse este asunto a su conclusión aquí?",
  ui_story_5043_50430601_68_dialog_content = "Oh. Gracias, dama Carleen. Y como parte del Salón de la Justicia, sé lo que está en juego.",
  ui_story_5043_50430601_69_dialog_content = "Para los Aurorianos, adoptar un Eclipsite no es una fantasía poco común.",
  ui_story_5043_50430601_69X1_dialog_content = "Lamento haber causado tantos problemas a todos... Volvamos al caso y hagamos todo lo posible para investigar más a fondo.",
  ui_story_5043_50430601_69X2_dialog_content = "No es como si todo lo que trajeras fueran problemas. ¿No sucedió algo interesante a raíz de todo esto?",
  ui_story_5043_50430601_70_dialog_content = "Tina, tu... tu realmente tomaste a todos en la División Romance por tontos.",
  ui_story_5043_50430601_71_dialog_content = "Jajajajaja! ¡Bien! Definitivamente tomé la decisión correcta cuando elegí trabajar contigo.",
  ui_story_5043_50430601_72_dialog_content = "Ciertamente encontré mucho más de lo que esperaba.",
  ui_story_5043_50430601_74_dialog_content = "Ja ja. Bueno, puede que no hayamos progresado mucho con el caso, pero mis galletas definitivamente causaron algo de entretenimiento.",
  ui_story_5043_50430601_75_dialog_content = "¡Pero! Yo siento lo mismo que todos ustedes...",
  ui_story_5043_50430601_76_dialog_content = "<color=#e8d9bb>¡Bang—!</color>",
  ui_story_5043_50430601_77_dialog_content = "Tina!? Tina!",
  ui_story_5043_50430601_78_dialog_content = "¿Qué le pasa a ella... Oye, no te quedes ahí parada, ven y ayuda!",
  ui_story_5043_50430601_79_dialog_content = "¡Uf! No te preocupes, se acaba de quedar dormida.",
  ui_story_5043_50430601_80_dialog_content = "Ha sido un día muy emocionante. Ella debe haber estado exhausta.",
  ui_story_5043_50430601_81_dialog_content = "Haré que uno de mis sirvientes la recoja en un carruaje y la lleve a casa.",
  ui_story_5043_50430601_82_dialog_content = "Huff Puff. Dama Carleen...",
  ui_story_5043_50430601_83_dialog_content = "Ah, Loewe. Tendrás que hacerlo mejor que esto si quieres ser un sirviente de Salar.",
  ui_story_5043_50430601_84_dialog_content = "¡Escúpelo!",
  ui_story_5043_50430601_85_dialog_content = "Dama Carleen, usted tenía razón.",
  ui_story_5043_50430601_86_dialog_content = "Todos esos guardias llevaban la heráldica de Troya.",
  ui_story_5043_50430601_87_dialog_content = "Y también hay algo extraño en el Salón Moonlight.",
  ui_story_5043_50430601_88_dialog_content = "¿Qué?",
  ui_story_5043_50430601_89_dialog_content = "Siempre hay un ataque de Eclipsite cuando termina uno de esos salones.",
  ui_story_5043_50430601_90_dialog_content = "Y la cabeza de la estatua cercana siempre desaparece.",
  ui_story_5043_50430601_91_dialog_content = "Lo siento, eso es todo lo que pude averiguar.",
  ui_story_5043_50430601_92_dialog_content = "...",
  ui_story_5043_50430601_93_dialog_content = "Has hecho un gran trabajo, Loewe.",
  ui_story_5043_50430601_94_dialog_content = "Y podrás descansar pronto. ¡Pero no todavía!",
  ui_story_5043_50430702_1_dialog_content = "Ya que sabemos de dónde vinieron los guardias, no puedo dejarlo así.",
  ui_story_5043_50430702_2_dialog_content = "PlayerName, necesito reunirme con los Guardianes y decidir qué hacer a continuación.",
  ui_story_5043_50430702_3_dialog_content = "Entonces necesitaré actualizar al Señor de la Ciudad sobre los problemas recientes de Eclipsite.",
  ui_story_5043_50430702_4_dialog_content = "Entonces ve. Podemos manejar las cosas aquí.",
  ui_story_5043_50430702_5_dialog_content = "Bueno. Te alcanzaré antes de la audiencia a más tardar.",
  ui_story_5043_50430702_6_dialog_content = "Cuidarse.",
  ui_story_5043_50430702_7_dialog_content = "Todos hemos tenido un día ajetreado. Deberíamos ir a casa y descansar.",
  ui_story_5043_50430702_8_dialog_content = "En cuanto a mañana...",
  ui_story_5043_50430702_9_dialog_content = "Bueno, todos sabemos lo que tenemos que hacer, ¿verdad?",
  ui_story_5043_50430702_10_dialog_content = "Estoy seguro de que el organizador de esos extraños salones Moonlight estará en la corte dentro de poco.",
  ui_story_5043_50430702_11_dialog_content = "Parece que algo extraño está pasando...",
  ui_story_5043_50430702_12_dialog_content = "Escucha, ¿por qué no vamos a buscar a esa monja mañana? Todo lo que tenemos que hacer es seguir el globo.",
  ui_story_5043_50430702_13_dialog_content = "¿Alguien puede decirme qué ha estado pasando?",
  ui_story_5043_50430702_14_dialog_content = "y porque es Tina dormido de nuevo?",
  ui_story_5043_50430702_15_dialog_content = "Es una larga historia. Te informaré en el camino de regreso.",
  ui_story_5043_50430702_16_dialog_content = "El carruaje está aquí. Tomaremos Tina hogar. PlayerName, Leyn, nos veremos mañana.",
  ui_story_5043_50430702_17_dialog_content = "¿Eh?",
  ui_story_5043_50430702_18_dialog_content = "¿Qué?",
  ui_story_5043_50430702_19_dialog_content = "No me llamaste plebeyo por una vez.",
  ui_story_5043_50430702_20_dialog_content = "¡Callate!",
  ui_story_5043_50430702_21_dialog_content = "<color=#e8d9bb>El día siguiente</color>",
  ui_story_5043_50430702_22_dialog_content = "Oh, ahora veo.",
  ui_story_5043_50430702_23_dialog_content = "Tienes razón. Elijo las ubicaciones de nuestros salones Moonlight con mucho cuidado.",
  ui_story_5043_50430702_24_dialog_content = "Me gustan los lugares con sentido de la cultura. Los lugares con estatuas son ideales.",
  ui_story_5043_50430702_25_dialog_content = "No me importa si las estatuas son de ancianos, niños, hombres o, como las dos que resultaron dañadas, mujeres.",
  ui_story_5043_50430702_26_dialog_content = "Son todos los componentes básicos de la civilización de Lumopolis.",
  ui_story_5043_50430702_27_dialog_content = "Pero no puedes negar que los Salones Moonlight parecen estar causando daños a las estatuas.",
  ui_story_5043_50430702_28_dialog_content = "Oh, no pretendo negar que las cosas han sido un poco caóticas. Y obviamente he estado cerca cuando las estatuas se dañaron.",
  ui_story_5043_50430702_29_dialog_content = "Pero puedo jurar por la Noche Blanca en lo alto que no tengo nada que ver con las estatuas dañadas o los ataques de Eclipsite.",
  ui_story_5043_50430702_30_dialog_content = "(Esta monja ciertamente se ve y suena tranquila y completamente despreocupada).",
  ui_story_5043_50430702_31_dialog_content = "(Y ella tiene un aura tan poderosa. ¿Quizás por su fe?)",
  ui_story_5043_50430702_32_dialog_content = "(Mi instinto me dice que ella no tiene nada que ver con nuestro caso).",
  ui_story_5043_50430702_33_dialog_content = "Gesto de desaprobación. Otro callejón sin salida, y supongo que no podemos andar arrestando gente según nuestras corazonadas.",
  ui_story_5043_50430702_34_dialog_content = "Hermana, si todo lo que dices es verdad...",
  ui_story_5043_50430702_35_dialog_content = "¿Estaría dispuesto a asistir a la audiencia como testigo?",
  ui_story_5043_50430702_36_dialog_content = "Bueno, me apresuré a organizar los Salones Moonlight, pero si eso es lo que desea el Salón de la Justicia, entonces sí.",
  ui_story_5043_50430702_37_dialog_content = "Haré todo lo que pueda para ayudar.",
  ui_story_5043_50430702_38_dialog_content = "¡Pero...!",
  ui_story_5043_50430702_39_dialog_content = "(Y si llevarla al Salón de la Justicia le causa más problemas...)",
  ui_story_5043_50430702_40_dialog_content = "¿Sí? Jovencita, ¿tiene algo que decir?",
  ui_story_5043_50430702_41_dialog_content = "Solo quiero saber cómo eres capaz de mantenerte tan calmado.",
  ui_story_5043_50430702_42_dialog_content = "No me opongo a los Salones Moonlight. Los disfruto, hacen que Lumopolis parezca un lugar diferente.",
  ui_story_5043_50430702_43_dialog_content = "Pero las costumbres de Lumopolis no aceptan ni siquiera el divorcio. Mucho menos amor libre.",
  ui_story_5043_50430702_44_dialog_content = "Y como mujer de fe, alguien que claramente es muy devota...",
  ui_story_5043_50430702_45_dialog_content = "¿Cómo llegaste a decidir organizar estos salones para la gente de Lumopolis?",
  ui_story_5043_50430702_46_dialog_content = "¿Y no tienes miedo de poner un pie dentro del Salón de la Justicia? Es tan... admirable.",
  ui_story_5043_50430702_47_dialog_content = "Tina...",
  ui_story_5043_50430702_48_dialog_content = "Jejeje... Mi niña, ¿acaso estás preguntando por tus propias preocupaciones?",
  ui_story_5043_50430702_49_dialog_content = "La cosa es que cuando llegas a mi edad, simplemente dejas de preocuparte y de pensar tanto.",
  ui_story_5043_50430702_50_dialog_content = "Todo lo que hago es escuchar la voluntad del Dios de la Luz.",
  ui_story_5043_50430702_51_dialog_content = "A lo largo de su larga historia, Lumopolis ha desarrollado complejos sistemas de etiqueta para controlar nuestros deseos.",
  ui_story_5043_50430702_52_dialog_content = "Pero originalmente fue fundado por hombres y mujeres ordinarios. Aurorianos simples y puros.",
  ui_story_5043_50430702_53_dialog_content = "A lo largo de los años, las enseñanzas del Dios de la Luz fueron reinterpretadas una y otra vez.",
  ui_story_5043_50430702_54_dialog_content = "Pero en el fondo, esas enseñanzas son simples y amables.",
  ui_story_5043_50430702_55_dialog_content = "Y esa es la verdadera bendición del Dios de la Luz. Su verdadera lección.",
  ui_story_5043_50430702_56_dialog_content = "Todo lo que estoy haciendo es llevar a los aurorianos a sus orígenes, a sus verdaderos deseos.",
  ui_story_5043_50430702_57_dialog_content = "No hay pecado en esto. Es simplemente algo que nuestras reglas y costumbres no entienden.",
  ui_story_5043_50430702_58_dialog_content = "Fe y amor... en sus raíces, son uno.",
  ui_story_5043_50430702_59_dialog_content = "Creo que entiendo. Muchas gracias.",
  ui_story_5043_50430702_60_dialog_content = "Entonces me despediré.",
  ui_story_5043_50430702_61_dialog_content = "Y déjame saber si puedo ayudarte más con tu investigación.",
  ui_story_5043_50430702_62_dialog_content = "Aunque si pudiera ofrecer una pequeña sugerencia al Salón de Justicia.",
  ui_story_5043_50430702_63_dialog_content = "Vaya...?",
  ui_story_5043_50430702_64_dialog_content = "Si realmente desea obtener más información antes de que comience la audiencia en la corte, en lugar de simplemente pasar por sus procesos...",
  ui_story_5043_50430702_65_dialog_content = "Entonces tendrás que dejar de trabajar tan mecánicamente. Piense en lo que el demandante realmente quiere.",
  ui_story_5043_50430702_66_dialog_content = "Gracias por el consejo. Pensaremos en esto...",
  ui_story_5043_50430702_67_dialog_content = "Seguro. Eso es todo. Hasta la proxima vez.",
  ui_story_5043_50430801_1_dialog_content = "<color=#e8d9bb>Al día siguiente</color>",
  ui_story_5043_50430801_2_dialog_content = "¿Qué, esto es todo lo que has encontrado?",
  ui_story_5043_50430801_3_dialog_content = "¡¿Así que no has resuelto el caso original, pero has logrado encontrar otra estatua sin cabeza?!",
  ui_story_5043_50430801_4_dialog_content = "Lo siento. Todavía estamos investigando, pero hasta ahora no hemos tenido ningún avance...",
  ui_story_5043_50430801_5_dialog_content = "¿¡Sin avances!? ¡No has progresado en absoluto!",
  ui_story_5043_50430801_6_dialog_content = "¿Es esto lo mejor que puede hacer el gran Salón de Justicia?",
  ui_story_5043_50430801_7_dialog_content = "También podría entregarle el caso a un perro ciego. ¡Tal vez podría olfatear al criminal!",
  ui_story_5043_50430801_8_dialog_content = "Lo lamento. Nos esforzaremos más...",
  ui_story_5043_50430801_9_dialog_content = "Puedo ver ahora que el Salón de Justicia no tiene interés en los problemas románticos de la ciudadanía.",
  ui_story_5043_50430801_10_dialog_content = "¡Y esta \"División de Romance\" es solo un hogar para gorrones!",
  ui_story_5043_50430801_11_dialog_content = "¡Todos aceptan paquetes de pago regordetes y trabajan duro para dormir!",
  ui_story_5043_50430801_12_dialog_content = "No puedo negar que tenemos tales empleados.",
  ui_story_5043_50430801_13_dialog_content = "P-Pero dormir me ayuda a trabajar mejor...",
  ui_story_5043_50430801_14_dialog_content = "Estoy perdiendo la paciencia. ¡La audiencia es en dos días!",
  ui_story_5043_50430801_15_dialog_content = "No diré más ahora. Si no puede encontrar algo nuevo mañana, no tendré más remedio que seguir demandando a mi vecino.",
  ui_story_5043_50430801_16_dialog_content = "Y me quejaré con Lady Irridon!",
  ui_story_5043_50430801_17_dialog_content = "¿De qué sirve pagarles tanto a todos si no pueden resolver nuestros problemas? ¡Vaya, Lumopolis estaría mejor si demoliéramos todo el edificio!",
  ui_story_5043_50430801_18_dialog_content = "¿Demoler?",
  ui_story_5043_50430801_19_dialog_content = "Oye, eso es un poco duro, ¿no?",
  ui_story_5043_50430801_20_dialog_content = "Sr. Byron, por favor, no se apresure.",
  ui_story_5043_50430801_21_dialog_content = "Hmph. ¡Todos ustedes necesitan hacerlo mejor!",
  ui_story_5043_50430801_22_dialog_content = "H-Se ha ido.",
  ui_story_5043_50430801_23_dialog_content = "Esto no está bien. La División de Romance podría estar en más problemas de los que pensaba.",
  ui_story_5043_50430801_24_dialog_content = "Oh, genial. Hemos terminado por ahora.",
  ui_story_5043_50430801_25_dialog_content = "Juez principal Irridon odia los malos comentarios del público. Si ella recibe una queja...",
  ui_story_5043_50430801_26_dialog_content = "Sí, se enfadará mucho.",
  ui_story_5043_50430801_27_dialog_content = "Y esto es sólo un arreglo temporal. Si el jefe decide que la División de Romance no está haciendo su trabajo...",
  ui_story_5043_50430801_28_dialog_content = "Podríamos perder todo esto.",
  ui_story_5043_50430801_29_dialog_content = "Supongo que tenía razón antes...",
  ui_story_5043_50430801_30_dialog_content = "Tal como se ven las cosas, realmente todos podrían perder sus trabajos.",
  ui_story_5043_50430801_31_dialog_content = "¿¡Perder nuestros trabajos!?",
  ui_story_5043_50430801_32_dialog_content = "Eso no puede pasar. ¡Y las cosas no están tan mal!",
  ui_story_5043_50430801_33_dialog_content = "P-Por favor, ni siquiera lo sugiera.",
  ui_story_5043_50430801_34_dialog_content = "Si perdiera mi trabajo, me moriría de aburrimiento quedándome en casa todo el día. ¡No podía salir y divertirme!",
  ui_story_5043_50430801_35_dialog_content = "Espera, ¿eso es todo lo que te preocupa? ¿Divirtiéndose?",
  ui_story_5043_50430801_36_dialog_content = "¿Dónde encontraré un lugar lo suficientemente tranquilo para dormir durante el día?",
  ui_story_5043_50430801_37_dialog_content = "¡No estás destinado a dormir en el trabajo!",
  ui_story_5043_50430801_38_dialog_content = "Y si no tengo trabajo, me harán ir a casa.",
  ui_story_5043_50430801_39_dialog_content = "Me obligarán a unirme al negocio familiar.",
  ui_story_5043_50430801_40_dialog_content = "Sí. Eso es familias. Nada más que montones de viejos aburridos.",
  ui_story_5043_50430801_41_dialog_content = "¿Quién en el mundo querría sentarse allí ayudándoles a contar su Nightium?",
  ui_story_5043_50430801_42_dialog_content = "Puedo ver que ustedes, los nobles, no necesitan que me preocupe por ustedes...",
  ui_story_5043_50430801_43_dialog_content = "¿Y qué si pierdes tu trabajo? ¡Estarás bien! Ánimo, todos.",
  ui_story_5043_50430801_44_dialog_content = "Sí. Incluso si perdemos nuestros trabajos, la vida continuará.",
  ui_story_5043_50430801_45_dialog_content = "Aunque sin sueldo... tendré que abastecerme de patatas y verduras.",
  ui_story_5043_50430801_46_dialog_content = "Y reducir a una comida al día.",
  ui_story_5043_50430801_47_dialog_content = "Espera, ¿cómo es que las cosas se ponen tan sombrías cuando venimos a ti?",
  ui_story_5043_50430801_48_dialog_content = "Porque la vida en Lumopolis es sombría, por eso.",
  ui_story_5043_50430801_49_dialog_content = "Comprar comida, mantenerse al día con la sociedad. Vivir no es gratis, ya sabes.",
  ui_story_5043_50430801_50_dialog_content = "Si pierdo mi salario, necesito empezar a contar cada centavo.",
  ui_story_5043_50430801_51_dialog_content = "Guau. La vida es dura...",
  ui_story_5043_50430801_52_dialog_content = "¡Pero aún no es hora de rendirse! Todavía tenemos un día. ¡Hagamos un buen uso de él!",
  ui_story_5043_50430801_53_dialog_content = "Sí. Si realmente hacemos algo, podríamos lograr algún progreso.",
  ui_story_5043_50430801_54_dialog_content = "Pero el problema es que no tenemos una sola pista que seguir.",
  ui_story_5043_50430801_55_dialog_content = "¿Qué línea de investigación debemos tomar?",
  ui_story_5043_50430801_56_dialog_content = "Damas y caballeros... ¡Tengo una idea!",
  ui_story_5043_50430801_57_dialog_content = "He estado pensando las cosas. Nuestro enfoque ha sido demasiado estrecho.",
  ui_story_5043_50430801_58_dialog_content = "El caso de decapitación de estatuas en serie no es un delito común.",
  ui_story_5043_50430801_59_dialog_content = "Las víctimas son estatuas. Eso significa que no podemos mirar sus círculos sociales para encontrar a alguien con un motivo.",
  ui_story_5043_50430801_60_dialog_content = "Del mismo modo, no hay posibilidad de encontrar al perpetrador entre los miembros de la familia de la víctima.",
  ui_story_5043_50430801_61_dialog_content = "Verdadero. Estos factores dificultan nuestras investigaciones.",
  ui_story_5043_50430801_62_dialog_content = "Pero pensemos fuera de la caja por un momento.",
  ui_story_5043_50430801_63_dialog_content = "Hay un factor crucial que ha resultado en que el daño a las estatuas se convierta en un caso aquí en la corte:",
  ui_story_5043_50430801_64_dialog_content = "<color=#FFB400>Amar</color>!",
  ui_story_5043_50430801_65_dialog_content = "Sí. Es el amor lo que hace de este un caso para la División de Romance.",
  ui_story_5043_50430801_66_dialog_content = "Y cuando se trata de amor, ya no es posible adoptar un enfoque puramente lógico.",
  ui_story_5043_50430801_67_dialog_content = "No nos enfrentamos a ningún caso ordinario. Este es un asunto del corazón.",
  ui_story_5043_50430801_68_dialog_content = "¡Oh! ¡Oh! ¡Esto hace que todo sea más claro!",
  ui_story_5043_50430801_69_dialog_content = "Aférrate. No estoy seguro de seguir...",
  ui_story_5043_50430801_70_dialog_content = "... ¿Pueden siquiera escucharse a sí mismos?",
  ui_story_5043_50430801_71_dialog_content = "No tenemos ninguna pista. Pero tal vez no necesitemos pistas.",
  ui_story_5043_50430801_72_dialog_content = "Mis queridos amigos, cuando se trata de amor no es necesario entenderlo todo.",
  ui_story_5043_50430801_73_dialog_content = "Lo importante es el corazón.",
  ui_story_5043_50430801_74_dialog_content = "Piensa en lo que dijo esa monja.",
  ui_story_5043_50430801_75_dialog_content = "\"Si realmente desea obtener más información antes de que comience la audiencia en la corte, en lugar de simplemente pasar por sus procesos...",
  ui_story_5043_50430801_76_dialog_content = "Entonces tendrás que dejar de trabajar tan mecánicamente. Piense en lo que el demandante realmente quiere\".",
  ui_story_5043_50430801_77_dialog_content = "Y podemos resolver el caso con... ¿corazón?",
  ui_story_5043_50430801_78_dialog_content = "¡A trabajar, amigos!",
  ui_story_5043_50430801_79_dialog_content = "¡Encontraremos las respuestas que el demandante necesita, con amor!",
  ui_story_5043_50430801_80_dialog_content = "<color=#e8d9bb>El día siguiente</color>",
  ui_story_5043_50430801_81_dialog_content = "Oye, ¿por qué estás bloqueando el camino?",
  ui_story_5043_50430801_82_dialog_content = "¡Déjame entrar!",
  ui_story_5043_50430801_83_dialog_content = "Espere un momento, Sr. Byron.",
  ui_story_5043_50430801_84_dialog_content = "Los jueces están actualmente ocupados en la sala del tribunal.",
  ui_story_5043_50430801_85_dialog_content = "Te dejaremos pasar tan pronto como tengan tiempo de hablar contigo.",
  ui_story_5043_50430801_86_dialog_content = "¿Ocupado? No seas ridículo. ¡Están ocupados con mi caso!",
  ui_story_5043_50430801_87_dialog_content = "¡Si quieren esconderse de mí, al menos podrían encontrar una mejor excusa!",
  ui_story_5043_50430801_88_dialog_content = "Sr. Byron, los jueces realmente son...",
  ui_story_5043_50430801_89_dialog_content = "No me importa lo que estén haciendo. Este es el horario de trabajo del juzgado.",
  ui_story_5043_50430801_90_dialog_content = "¡S-Señor, por favor espere!",
  ui_story_5043_50430801_91_dialog_content = "¡Hazte a un lado!",
  ui_story_5043_50430801_92_dialog_content = "Ah, pero...",
  ui_story_5043_50430801_93_dialog_content = "<size=45>Juez Matthieu! ¡¡¡Se ha metido!!!</size>",
  ui_story_5043_50430801_94_dialog_content = "<color=#e8d9bb>¡Estallido! ¡Estallido! ¡Estallido!</color>",
  ui_story_5043_50430801_95_dialog_content = "¡Felicitaciones, Sr. Byron!",
  ui_story_5043_50430801_96_dialog_content = "¡Estoy tan feliz por ustedes dos!",
  ui_story_5043_50430801_97_dialog_content = "¡Qué maravilloso para ti reunirte con tu verdadero amor en este día por lo demás ordinario!",
  ui_story_5043_50430801_98_dialog_content = "¿Eh? Esto es...",
  ui_story_5043_50430801_99_dialog_content = "Nos tomó un día entero pero hicimos de tu estatua una cabeza nueva.",
  ui_story_5043_50430801_100_dialog_content = "Si hubiéramos tenido un poco más de tiempo, ¡habríamos hecho que se viera aún mejor!",
  ui_story_5043_50430801_101_dialog_content = "Sí. Nos dimos cuenta de que necesitábamos adoptar un enfoque más romántico y esta fue nuestra solución.",
  ui_story_5043_50430801_102_dialog_content = "La pregunta no es qué has perdido. Es lo que aún puedes conseguir.",
  ui_story_5043_50430801_103_dialog_content = "Después de todo, seguramente la pérdida de una simple cabeza no se interpondrá en el camino de tu amor.",
  ui_story_5043_50430801_104_dialog_content = "No. Todavía necesitas amar. Pero era comprensible que su incompletitud te entristeciera.",
  ui_story_5043_50430801_105_dialog_content = "Y para quitar esa tristeza de tu corazón, teníamos que hacerla completa una vez más.",
  ui_story_5043_50430801_106_dialog_content = "Jejeje Una hermosa historia de pérdida y recuperación...",
  ui_story_5043_50430801_107_dialog_content = "Tú ...",
  ui_story_5043_50430801_108_dialog_content = "<size=45>¿¡Qué diablos has hecho!?</size>",
  ui_story_5043_50430801_109_dialog_content = "¿Qué es ese horrible bulto en el cuello de Galatea? ¿Estás tratando de insultarme?",
  ui_story_5043_50430801_110_dialog_content = "¿Este? ¿Horrible?",
  ui_story_5043_50430801_111_dialog_content = "No pareces contento...",
  ui_story_5043_50430801_112_dialog_content = "Gesto de desaprobación. Sabía que no deberíamos confiar en un plebeyo en cuestiones de estética.",
  ui_story_5043_50430801_113_dialog_content = "Si no está satisfecho con su nueva apariencia, podemos hacer otra...",
  ui_story_5043_50430801_114_dialog_content = "¡Para! ¡Imbéciles que se han burlado de mi amor!",
  ui_story_5043_50430801_115_dialog_content = "¿Qué sabrías tú del amor verdadero?",
  ui_story_5043_50430801_116_dialog_content = "¡El amor es único y verdadero! ¡El amor es una elección que nunca puede cambiar!",
  ui_story_5043_50430801_117_dialog_content = "¡Y cuando Galatea perdió la cabeza, murió mi amor!",
  ui_story_5043_50430801_118_dialog_content = "Incluso si pudieras producir una réplica exacta de su cabeza, ¡ella no sería mi Galatea!",
  ui_story_5043_50430801_119_dialog_content = "¡Ella no sería la que yo amaba!",
  ui_story_5043_50430801_120_dialog_content = "ah Así es como funciona...",
  ui_story_5043_50430801_121_dialog_content = "Erm, ¿así que entendí mal?",
  ui_story_5043_50430801_122_dialog_content = "Nosotros fallamos. Supongo que la División de Romance está condenada...",
  ui_story_5043_50430801_123_dialog_content = "Oh, no importa todo eso por ahora.",
  ui_story_5043_50430801_124_dialog_content = "Tengo cosas más importantes que discutir contigo.",
  ui_story_5043_50430801_125_dialog_content = "Mi <color=#FFB400>esposa</color> está en peligro de muerte justo en este mismo momento.",
  ui_story_5043_50430801_126_dialog_content = "¡Por el bien de nuestro amor, te ruego que envíes personas para protegerla!",
  ui_story_5043_50430801_127_dialog_content = "¡E-Espera! ¿Su esposa está en peligro de muerte?",
  ui_story_5043_50430801_128_dialog_content = "¿No es esta tu esposa?",
  ui_story_5043_50430801_129_dialog_content = "No, te has equivocado. Galatea es mi <color=#FFB400>amante</color>!",
  ui_story_5043_50430801_130_dialog_content = "La persona en peligro de muerte es mi <color=#FFB400>esposa</color>. No son la misma persona.",
  ui_story_5043_50430801_131_dialog_content = "¿¡Qué!?",
  ui_story_5043_50430801_132_dialog_content = "¿Tu esposa y tu amante son personas diferentes?",
  ui_story_5043_50430801_133_dialog_content = "Mi esposa es una hermosa estatua diferente. Ella se llama Afrodita.",
  ui_story_5043_50430801_134_dialog_content = "¿Y qué pasó con el amor siendo único y verdadero?",
  ui_story_5043_50430801_135_dialog_content = "¡Por supuesto que es!",
  ui_story_5043_50430801_136_dialog_content = "Entonces, ¿cómo es que estás enamorado de dos estatuas diferentes?",
  ui_story_5043_50430801_137_dialog_content = "El amor también es vasto y tolerante.",
  ui_story_5043_50430801_138_dialog_content = "Amo a mi esposa. Y amo a mi amante. Dos amores diferentes y únicos.",
  ui_story_5043_50430801_139_dialog_content = "Considera esto. Amas a tu madre, ¿no? ¿Y también amas a tu padre?",
  ui_story_5043_50430801_140_dialog_content = "Supongo que tiene algo de sentido...",
  ui_story_5043_50430801_141_dialog_content = "¡No es asi! Esos son tipos de relaciones completamente diferentes.",
  ui_story_5043_50430801_142_dialog_content = "Mirad, no tengo tiempo para educaros a vosotros, niños, sobre la naturaleza del amor.",
  ui_story_5043_50430801_143_dialog_content = "Acabo de ver el globo lunar flotando sobre la Escalera a los Cielos.",
  ui_story_5043_50430801_144_dialog_content = "Y ahí es donde está mi esposa.",
  ui_story_5043_50430801_145_dialog_content = "Ya sabes que globo significa que habrá un Salón de la Luz de la Luna. Y un Salón de la Luz de la Luna significa que una estatua perderá la cabeza.",
  ui_story_5043_50430801_146_dialog_content = "Y si algo le pasara a mi esposa... No tendré a nadie a quien amar.",
  ui_story_5043_50430801_147_dialog_content = "¿Seguramente es tu deber proteger el derecho al amor de los ciudadanos?",
  ui_story_5043_50430801_148_dialog_content = "Bueno, hemos aceptado su caso. Así que supongo que tenemos que proteger tu amor.",
  ui_story_5043_50430801_149_dialog_content = "Tut, o la mitad de su amor, al menos.",
  ui_story_5043_50430801_150_dialog_content = "Y existe la posibilidad de que encontremos una nueva pista que nos ayude con nuestro caso.",
  ui_story_5043_50430801_151_dialog_content = "Tenemos que ir para resolver el caso de decapitación de estatuas en serie.",
  ui_story_5043_50430801_152_dialog_content = "¿Entonces, Qué esperas? ¡Mover!",
  ui_story_5043_50430801_153_dialog_content = "¡El Salón Moonlight está a punto de comenzar!",
  ui_story_5043_50430801_154_dialog_content = "<color=#e8d9bb>Patio Lumopolis, cerca de la Escalera a los Cielos</color>",
  ui_story_5043_50430801_155_dialog_content = "Ah, ya casi llegamos.",
  ui_story_5043_50430801_156_dialog_content = "El Sr. Byron dijo que su esposa estaba aquí. Entonces ella debe ser...",
  ui_story_5043_50430801_157_dialog_content = "Entiendo. Debe ser este!",
  ui_story_5043_50430801_158_dialog_content = "Oh. Y sigue intacto.",
  ui_story_5043_50430801_159_dialog_content = "Entonces, ¿todo lo que tenemos que hacer es proteger la estatua?",
  ui_story_5043_50430801_160_dialog_content = "Sí. El criminal puede intentar atacar durante el salón.",
  ui_story_5043_50430801_161_dialog_content = "Pero, ¿dónde están todos los asistentes al salón?",
  ui_story_5043_50430801_162_dialog_content = "Los veo. Están todos al pie de las escaleras.",
  ui_story_5043_50430801_163_dialog_content = "Así son. ¿No están subiendo?",
  ui_story_5043_50430801_164_dialog_content = "Ah, esto significa que hemos tenido suerte.",
  ui_story_5043_50430801_165_dialog_content = "Si el salón está ahí abajo, será más fácil proteger una estatua aquí.",
  ui_story_5043_50430801_166_dialog_content = "Impresionante. Podemos hacer lo que pidió el Sr. Byron.",
  ui_story_5043_50430801_167_dialog_content = "Oh, veo que los jueces están aquí.",
  ui_story_5043_50430801_168_dialog_content = "¡Hermana! No esperaba volver a verte tan pronto.",
  ui_story_5043_50430801_169_dialog_content = "¿Dónde más esperarías encontrarme, sino bajo el globo lunar?",
  ui_story_5043_50430801_170_dialog_content = "Y ahora que estás aquí, ¿por qué no te unes a las celebraciones?",
  ui_story_5043_50430801_171_dialog_content = "¿El salón se lleva a cabo al pie de las escaleras?",
  ui_story_5043_50430801_172_dialog_content = "Nos encantaría ayudar, pero tenemos un...",
  ui_story_5043_50430801_173_dialog_content = "Oh, no. El evento de hoy no es un salón.",
  ui_story_5043_50430801_174_dialog_content = "¿Eh? Así que lo que...",
  ui_story_5043_50430801_175_dialog_content = "<size=45>¿Están todos listos?</size>",
  ui_story_5043_50430801_176_dialog_content = "<size=45>¡Que comience el desfile!</size>",
  ui_story_5043_50430901_1_dialog_content = "¡Estamos aquí para cantar alabanzas al amor! ♪",
  ui_story_5043_50430901_2_dialog_content = "¡Aquí en la sagrada Lumopolis! ♪",
  ui_story_5043_50430901_3_dialog_content = "Aquí a la vista de todos los amantes! ♪",
  ui_story_5043_50430901_4_dialog_content = "¡Canta en alabanza de la verdadera belleza del amor! ♪",
  ui_story_5043_50430901_5_dialog_content = "Cantamos en alabanza del amor! ♪",
  ui_story_5043_50430901_6_dialog_content = "¡Canta en alabanza al amor! ♪",
  ui_story_5043_50430901_7_dialog_content = "Marchantes... marcha!",
  ui_story_5043_50430901_8_dialog_content = "¿Guau? Hay una gran multitud de personas subiendo las escaleras.",
  ui_story_5043_50430901_9_dialog_content = "Esto no es bueno, ¿verdad?",
  ui_story_5043_50430901_10_dialog_content = "Sí. Si pasan junto a la estatua, será más difícil mantenerla a salvo.",
  ui_story_5043_50430901_11_dialog_content = "Y si la estatua se vuelve a dañar bajo tus narices, tus trabajos están prácticamente perdidos.",
  ui_story_5043_50430901_12_dialog_content = "Tenemos que encontrar una forma de detener el desfile.",
  ui_story_5043_50430901_13_dialog_content = "¿Detener el desfile? ¿Por qué, hemos hecho algo mal?",
  ui_story_5043_50430901_14_dialog_content = "Esto requirió mucha organización. No puedes evitar que siga adelante sin una buena razón.",
  ui_story_5043_50430901_15_dialog_content = "Se están moviendo rápidamente. No tenemos mucho tiempo.",
  ui_story_5043_50430901_16_dialog_content = "Intentaré detenerlos. ¡Tú le explicas a la monja!",
  ui_story_5043_50430901_17_dialog_content = "Oh, ¿por qué los plebeyos siempre son tan apresurados...?",
  ui_story_5043_50430901_18_dialog_content = "Hermana, escucha. No queremos detener el desfile.",
  ui_story_5043_50430901_19_dialog_content = "Pero tenemos que hacerlo. Por amor.",
  ui_story_5043_50430901_20_dialog_content = "¿Amar?",
  ui_story_5043_50430901_21_dialog_content = "Alguien va a usar el desfile como tapadera para cometer un crimen.",
  ui_story_5043_50430901_22_dialog_content = "Y estoy seguro de que no quieres que tus eventos tengan la reputación de causar angustia, ¿verdad?",
  ui_story_5043_50430901_23_dialog_content = "¡Nosotros! ¡Elogio! ¡Amar!",
  ui_story_5043_50430901_24_dialog_content = "¡Gratis! ¡Amar!",
  ui_story_5043_50430901_25_dialog_content = "¡Guau! ¡Espera, todos!",
  ui_story_5043_50430901_26_dialog_content = "Creo que vamos por el camino equivocado.",
  ui_story_5043_50430901_27_dialog_content = "¡Se suponía que íbamos a ir al distrito residencial en Lumopolis Courtyard!",
  ui_story_5043_50430901_28_dialog_content = "Tenemos que dar la vuelta y volver.",
  ui_story_5043_50430901_29_dialog_content = "¡Sí! ¡Regresa!",
  ui_story_5043_50430901_30_dialog_content = "¿Eh? ¿Vamos por el camino equivocado?",
  ui_story_5043_50430901_31_dialog_content = "Eso no está bien. Nos dijeron que subiéramos juntos la Escalera a los Cielos.",
  ui_story_5043_50430901_32_dialog_content = "Debemos haberlo entendido mal. Tal vez alguien escuchó mal las instrucciones.",
  ui_story_5043_50430901_33_dialog_content = "¿El barrio residencial?",
  ui_story_5043_50430901_34_dialog_content = "¡Escuché que era la plaza en Lumopolis Courtyard!",
  ui_story_5043_50430901_35_dialog_content = "¡Eso está a millas de distancia! ¡Date prisa, demos la vuelta y sigamos!",
  ui_story_5043_50430901_36_dialog_content = "¡Exactamente! ¡Date la vuelta y ponte en marcha!",
  ui_story_5043_50430901_37_dialog_content = "¿Regresa? Pero hemos llegado tan lejos...",
  ui_story_5043_50430901_38_dialog_content = "¡Sí!",
  ui_story_5043_50430901_39_dialog_content = "Pero estamos destinados a ir al distrito residencial.",
  ui_story_5043_50430901_40_dialog_content = "¡No! ¡Es la plaza!",
  ui_story_5043_50430901_41_dialog_content = "Esperar. Recuerdo muy claramente que me dijeron que íbamos a subir Stairway to the Skies.",
  ui_story_5043_50430901_42_dialog_content = "¡Bien! Y si no, ¿por qué nos reunimos todos al pie de las escaleras?",
  ui_story_5043_50430901_43_dialog_content = "Ustedes que quieren ir al barrio residencial oa la plaza, ¿de dónde sacaron la información?",
  ui_story_5043_50430901_44_dialog_content = "Un tipo con el pelo blanco atado en una cola de caballo. Parecía digno de confianza.",
  ui_story_5043_50430901_45_dialog_content = "Un tipo de aspecto digno de confianza con el pelo blanco atado en una cola de caballo.",
  ui_story_5043_50430901_46_dialog_content = "Oye, esa es la misma persona. ¡Te han engañado!",
  ui_story_5043_50430901_47_dialog_content = "¡¿Qué?!",
  ui_story_5043_50430901_48_dialog_content = "¡Oye, ese es él! ¡Mira, tiene el pelo blanco y una cola de caballo!",
  ui_story_5043_50430901_49_dialog_content = "¿Qué? ¿A mí? No, solo estoy de paso...",
  ui_story_5043_50430901_50_dialog_content = "¡Ese es el!",
  ui_story_5043_50430901_51_dialog_content = "¡Él es el que me dijo!",
  ui_story_5043_50430901_52_dialog_content = "Entonces, ¿quién es este extraño que intenta arruinar nuestro Love Parade?",
  ui_story_5043_50430901_53_dialog_content = "¡Llévenlo a la División de Romance!",
  ui_story_5043_50430901_54_dialog_content = "N-No hay necesidad. Voy allí de todos modos...",
  ui_story_5043_50430901_55_dialog_content = "¡Vamos! ¡Sigue subiendo los escalones!",
  ui_story_5043_50430901_56_dialog_content = "Y no dejes que ese tipo se escape.",
  ui_story_5043_50430901_57_dialog_content = "(Maldita sea. Mi brillante idea no fue tan buena como esperaba).",
  ui_story_5043_50430901_58_dialog_content = "(Y la gente se ha vuelto a poner en marcha. ¿Qué debo hacer?)",
  ui_story_5043_50430901_59_dialog_content = "¡Ay, ay, ay! ¡He volcado los cubos de leche y miel!",
  ui_story_5043_50430901_60_dialog_content = "Madre mía, qué torpe soy.",
  ui_story_5043_50430901_61_dialog_content = "¿Qué? Mira toda la leche que cae por las escaleras.",
  ui_story_5043_50430901_62_dialog_content = "¿De dónde en el mundo salió eso?",
  ui_story_5043_50430901_63_dialog_content = "¿¡Y por qué hay miel mezclada en la leche!?",
  ui_story_5043_50430901_64_dialog_content = "(¡E-Eso parece una de las estrategias más directas de Matthieu!)",
  ui_story_5043_50430901_65_dialog_content = "(Era una idea extraña, pero parece haber funcionado. La gente se ha detenido).",
  ui_story_5043_50430901_66_dialog_content = "Guau. Todo parece ir mal hoy.",
  ui_story_5043_50430901_67_dialog_content = "No podemos rendirnos. Como dice el Dios de la Luz, ¡el camino a la tierra bendita es de pruebas y tribulaciones!",
  ui_story_5043_50430901_68_dialog_content = "¡Exactamente! ¡La leche y la miel simplemente muestran que estamos en el camino correcto!",
  ui_story_5043_50430901_69_dialog_content = "Sigan adelante, todos. Pero tenga cuidado de no resbalar.",
  ui_story_5043_50430901_70_dialog_content = "(¿Han comenzado de nuevo?)",
  ui_story_5043_50430901_71_dialog_content = "(Seguro que son un grupo decidido...)",
  ui_story_5043_50430901_72_dialog_content = "<size=45>¡Ahhh!</size>",
  ui_story_5043_50430901_73_dialog_content = "<size=45>¡¡¡Las escaleras son tan resbaladizas!!!</size>",
  ui_story_5043_50430901_74_dialog_content = "¡¿Qué está pasando?!",
  ui_story_5043_50430901_75_dialog_content = "Creo que alguien se cayó.",
  ui_story_5043_50430901_76_dialog_content = "Boo-hoo... realmente duele...",
  ui_story_5043_50430901_77_dialog_content = "Estoy viendo estrellas, incluso si es de día.",
  ui_story_5043_50430901_78_dialog_content = "S-Parece gravemente herida.",
  ui_story_5043_50430901_79_dialog_content = "Estos pasos son un poco peligrosos en este momento...",
  ui_story_5043_50430901_80_dialog_content = "Tal vez... ¿deberíamos dejarlo por hoy?",
  ui_story_5043_50430901_81_dialog_content = "Sí. Podemos desfilar en otro lugar.",
  ui_story_5043_50430901_82_dialog_content = "No te quedes ahí parado bloqueando el camino. Encuentra a alguien que lleve a esta pobre chica al médico.",
  ui_story_5043_50430901_83_dialog_content = "¡Están retrocediendo!",
  ui_story_5043_50430901_84_dialog_content = "Excelente actuación, Tina!",
  ui_story_5043_50430901_85_dialog_content = "¡Sí, muy convincente!",
  ui_story_5043_50430901_86_dialog_content = "Jejeje. Si pierdo mi trabajo en el Salón de la Justicia, quizás suba al escenario.",
  ui_story_5043_50430901_87_dialog_content = "¿Y mi truco? Inteligente, ¿eh?",
  ui_story_5043_50430901_88_dialog_content = "fue increíble Simplemente perfecto.",
  ui_story_5043_50430901_89_dialog_content = "Hijos... eso era otra cosa.",
  ui_story_5043_50430901_90_dialog_content = "Pero como todo fue para proteger la reputación de estos eventos, que así sea.",
  ui_story_5043_50430901_91_dialog_content = "Todo amor es digno de protección. Incluso el amor de una estatua.",
  ui_story_5043_50430901_92_dialog_content = "Puedo ver por qué diriges tus salones. Gracias por ser tan comprensiva, hermana.",
  ui_story_5043_50430901_93_dialog_content = "Tengo que irme. Dirigiré a la gente del desfile en una dirección diferente.",
  ui_story_5043_50430901_94_dialog_content = "Y haremos nuestro mejor esfuerzo en nuestro trabajo también.",
  ui_story_5043_50430901_95_dialog_content = "¡Oh, no! ¡Todos, paren!",
  ui_story_5043_50430901_96_dialog_content = "¡Tenemos que volver a las escaleras!",
  ui_story_5043_50430901_97_dialog_content = "¿Qué está sucediendo? ¡Hay algún tipo de conmoción!",
  ui_story_5043_50430901_98_dialog_content = "¡Eclipsitos! ¿¡De dónde vienen ellos!?",
  ui_story_5043_50430901_99_dialog_content = "¡Rápido! ¡Sube las escaleras!",
  ui_story_5043_50430901_100_dialog_content = "¿Qué? ¿De dónde vienen estos eclipses?",
  ui_story_5043_50430901_101_dialog_content = "¡Los veo! Aunque solo unos pocos.",
  ui_story_5043_50430901_102_dialog_content = "Leyn ¡ya los está abordando!",
  ui_story_5043_50430901_103_dialog_content = "¡Vamos a ayudarlo, stat!",
  ui_story_5043_50430901_104_dialog_content = "¡No olvides la estatua! Esa multitud está a punto de pasar en estampida.",
  ui_story_5043_50430901_105_dialog_content = "Son solo unos pocos eclipses. Una persona extra debería ser suficiente.",
  ui_story_5043_50430901_106_dialog_content = "Tina, ve a ayudar Leyn. Todos los demás quédense aquí con la estatua.",
  ui_story_5043_50430901_107_dialog_content = "Usaré mis habilidades psíquicas para ayudarte a luchar contra los Eclipsites, Tina.",
  ui_story_5043_50430901_108_dialog_content = "Vale, suena bien.",
  ui_story_5043_50430901_109_dialog_content = "¡Asegúrense de cuidar la estatua!",
  ui_story_5043_50431001_1_dialog_content = "¡Ese es el último allí!",
  ui_story_5043_50431001_2_dialog_content = "¡Déjamelo a mí!",
  ui_story_5043_50431001_3_dialog_content = "Bueno. Eso es todo lo que trataron los Eclipsites.",
  ui_story_5043_50431001_4_dialog_content = "Pero... parece que toda la gente corrió escaleras arriba.",
  ui_story_5043_50431001_5_dialog_content = "Me pregunto cómo PlayerName y los demás están haciendo.",
  ui_story_5043_50431001_6_dialog_content = "¡Ey! ¡Cuidado todos!",
  ui_story_5043_50431001_7_dialog_content = "Hay una estatua muy valiosa aquí. ¡Lo rompiste, lo compraste!",
  ui_story_5043_50431001_8_dialog_content = "¡Eclipsitos! ¿¡Que estas esperando!? ¡Correr!",
  ui_story_5043_50431001_9_dialog_content = "¡Todos pueden dejar de entrar en pánico! ¡Los eclipses han sido tratados!",
  ui_story_5043_50431001_10_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5043_50431001_11_dialog_content = "¡¿Qué está pasando?!",
  ui_story_5043_50431001_12_dialog_content = "¡Oh, no! ¡Alguien se estrelló contra la estatua!",
  ui_story_5043_50431001_13_dialog_content = "Afortunadamente no parece estar dañado.",
  ui_story_5043_50431001_14_dialog_content = "¡Ahhhhhh!",
  ui_story_5043_50431001_15_dialog_content = "¡Están regresando!",
  ui_story_5043_50431001_16_dialog_content = "Matthieu, ¡detenerlos!",
  ui_story_5043_50431001_17_dialog_content = "Claro, pero como...",
  ui_story_5043_50431001_18_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5043_50431001_19_dialog_content = "¡Ay!",
  ui_story_5043_50431001_20_dialog_content = "¿Estás bien?",
  ui_story_5043_50431001_21_dialog_content = "¿Qué tal si me ayudas a levantarme en lugar de hacer preguntas estúpidas?",
  ui_story_5043_50431001_22_dialog_content = "¡Tonterías! ¡Hay eclipses en la multitud!",
  ui_story_5043_50431001_23_dialog_content = "¿Eclipsitos?",
  ui_story_5043_50431001_24_dialog_content = "Tienes razón. Puedo ver varios de ellos.",
  ui_story_5043_50431001_25_dialog_content = "¿De dónde están viniendo?",
  ui_story_5043_50431001_26_dialog_content = "¡No entrar en pánico! ¡Los herraré hasta la muerte!",
  ui_story_5043_50431001_27_dialog_content = "¿Puedes matar un Eclipsite con un zapato?",
  ui_story_5043_50431001_28_dialog_content = "¡Esperar! ¡Eso va a golpear la estatua!",
  ui_story_5043_50431001_29_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5043_50431001_30_dialog_content = "Espero que el Sr. Byron no se oponga a una pequeña huella...",
  ui_story_5043_50431001_31_dialog_content = "¡Ayudaré! ¡Ver este!",
  ui_story_5043_50431001_32_dialog_content = "¿¡Qué!? ¿Otro?",
  ui_story_5043_50431001_33_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5043_50431001_34_dialog_content = "Oye, ¿está bien la estatua?",
  ui_story_5043_50431001_35_dialog_content = "Parece estar bien por ahora, pero si esto continúa...",
  ui_story_5043_50431001_36_dialog_content = "Deja de tirar zapatos. ¡Ni siquiera estás dañando una estatua!",
  ui_story_5043_50431001_37_dialog_content = "¡Y mucho menos derrotar a los Eclipsites!",
  ui_story_5043_50431001_38_dialog_content = "El tiene razón. ¿Tenemos mejores armas?",
  ui_story_5043_50431001_39_dialog_content = "¡Sí! Algo de queso. ¡Es duro como una roca!",
  ui_story_5043_50431001_40_dialog_content = "¿¡Qué clase de persona lleva queso por ahí!?",
  ui_story_5043_50431001_41_dialog_content = "Oh, no. Si el queso golpea la estatua, entonces podría...",
  ui_story_5043_50431001_42_dialog_content = "¡Todos, cálmense! Dije, ¡cálmate! Deja de tirar cosas.",
  ui_story_5043_50431001_43_dialog_content = "¡No quiero ver más lanzamientos!",
  ui_story_5043_50431001_44_dialog_content = "Hermana!",
  ui_story_5043_50431001_45_dialog_content = "Todos dejen de tirar cosas. Podríamos golpear a la hermana.",
  ui_story_5043_50431001_46_dialog_content = "Uf... Creo que hemos evitado el desastre.",
  ui_story_5043_50431001_47_dialog_content = "Gracias hermana.",
  ui_story_5043_50431001_48_dialog_content = "No es nada. Solo estaba cumpliendo con mi deber.",
  ui_story_5043_50431001_49_dialog_content = "¡No puedo permitir que nuestros eventos temáticos del Día de la Corona de la Luna adquieran la reputación de arruinar el amor de la gente!",
  ui_story_5043_50431001_50_dialog_content = "(Bueno, dada la forma en que protegió la estatua, creo que podemos eliminarla de nuestras investigaciones).",
  ui_story_5043_50431001_51_dialog_content = "La multitud se está dispersando por fin.",
  ui_story_5043_50431001_52_dialog_content = "Parece que podemos relajarnos.",
  ui_story_5043_50431001_53_dialog_content = "Sí.",
  ui_story_5043_50431001_54_dialog_content = "Esa multitud en estampida daba más miedo que los Eclipsites.",
  ui_story_5043_50431001_55_dialog_content = "Seguro que lo era. Si hubiera sabido, me habría ido con Tina.",
  ui_story_5043_50431001_56_dialog_content = "¡Ey! ¿Por qué estás parado ahí?",
  ui_story_5043_50431001_57_dialog_content = "Leyn, ¡estás de vuelta!",
  ui_story_5043_50431001_58_dialog_content = "¡Detrás tuyo!",
  ui_story_5043_50431001_59_dialog_content = "¡Hay eclipses detrás de ti!",
  ui_story_5043_50431002_1_dialog_content = "Estos Eclipsites saben cómo acercarse sigilosamente a la gente.",
  ui_story_5043_50431002_2_dialog_content = "Pero no pueden hacer frente a una buena pelea.",
  ui_story_5043_50431002_3_dialog_content = "No te relajes todavía. Todavía quedan algunos.",
  ui_story_5043_50431002_4_dialog_content = "Vamos, acabemos con ellos.",
  ui_story_5043_50431002_5_dialog_content = "¡Espera!",
  ui_story_5043_50431002_6_dialog_content = "PlayerName, a tu lado...",
  ui_story_5043_50431002_7_dialog_content = "¿A mi lado?",
  ui_story_5043_50431002_8_dialog_content = "Es...",
  ui_story_5043_50431002_9_dialog_content = "<color=#e8d9bb>¡Golpe!</color>",
  ui_story_5043_50431002_10_dialog_content = "¡Oh, no! La estatua...",
  ui_story_5043_50431002_11_dialog_content = "¿¡Quien hizo esto!?",
  ui_story_5043_50431002_12_dialog_content = "¡Tengo la mano del vándalo!",
  ui_story_5043_50431002_13_dialog_content = "Rápido, sácalo de la pila de Eclipsites.",
  ui_story_5043_50431002_14_dialog_content = "¡Hazte a un lado! Todos ustedes están en mi camino.",
  ui_story_5043_50431002_15_dialog_content = "¿Eh? No hay nadie aquí.",
  ui_story_5043_50431002_16_dialog_content = "Lo siento. Se escapó.",
  ui_story_5043_50431002_17_dialog_content = "Se quitó el guante y escapó. Como un lagarto que abandona su cola...",
  ui_story_5043_50431002_18_dialog_content = "esto es horrible ¡La estatua se dañó justo debajo de mis narices!",
  ui_story_5043_50431002_19_dialog_content = "¿Cómo voy a explicar esto?",
  ui_story_5043_50431002_20_dialog_content = "Bueno... al menos tenemos el guante del culpable, ¿no?",
  ui_story_5043_50431002_21_dialog_content = "Esa es una pista valiosa.",
  ui_story_5043_50431002_22_dialog_content = "Supongo que podríamos llamarlo un gran avance en nuestra investigación.",
  ui_story_5043_50431002_23_dialog_content = "Pero... no creo que el Sr. Byron lo vea así.",
  ui_story_5043_50431002_24_dialog_content = "Oye, ¿dónde está? Tina?",
  ui_story_5043_50431002_25_dialog_content = "Pensé que ella estaba contigo, Leyn?",
  ui_story_5043_50431002_26_dialog_content = "Supongo que se quedó atrás mientras yo regresaba corriendo.",
  ui_story_5043_50431002_27_dialog_content = "¿Ey? ¿Estás bien?",
  ui_story_5043_50431002_28_dialog_content = "Lo siento, me encontré con algunos eclipses más mientras subía las escaleras.",
  ui_story_5043_50431002_29_dialog_content = "Espera, la estatua... ¿¡dónde está su cabeza!?",
  ui_story_5043_50431002_30_dialog_content = "Suspiro...",
  ui_story_5043_50431002_31_dialog_content = "Vamos. Regresemos e informemos.",
  ui_story_5043_50431002_32_dialog_content = "<color=#e8d9bb>El Salón de la Justicia, Jardines de Lumopolis</color>",
  ui_story_5043_50431002_33_dialog_content = "<size=45>¡Mi esposa! ¡Mi esposa!</size>",
  ui_story_5043_50431002_34_dialog_content = "<size=45>¡Mi querida Afrodita!</size>",
  ui_story_5043_50431002_35_dialog_content = "...",
  ui_story_5043_50431002_36_dialog_content = "Estamos muertos.",
  ui_story_5043_50431002_37_dialog_content = "Cómo... ¿Por qué tuvo que pasar esto?",
  ui_story_5043_50431002_38_dialog_content = "Te ame tanto. E hice todo lo que pude para protegerte.",
  ui_story_5043_50431002_39_dialog_content = "Y sin embargo... mi amor me ha sido robado...",
  ui_story_5043_50431002_40_dialog_content = "¿Por qué no puedo salvar a mis queridas estatuas? Ni siquiera uno de ellos...",
  ui_story_5043_50431002_41_dialog_content = "Sé lo que pasó y entiendo cómo debe sentirse, Sr. Byron.",
  ui_story_5043_50431002_42_dialog_content = "¿Tú? ¿Tú entiendes?",
  ui_story_5043_50431002_43_dialog_content = "¡No entiendes nada!",
  ui_story_5043_50431002_44_dialog_content = "¡No queda nada en este mundo digno de mi amor!",
  ui_story_5043_50431002_45_dialog_content = "Oh Dios de la Luz, por qué me castigas así...",
  ui_story_5043_50431002_46_dialog_content = "Tal vez si te calmas.",
  ui_story_5043_50431002_47_dialog_content = "Después de todo, lo hecho, hecho está.",
  ui_story_5043_50431002_48_dialog_content = "Pero nos aseguraremos de que se haga justicia.",
  ui_story_5043_50431002_49_dialog_content = "Ja. ¡El Salón de la Justicia no puede ayudar!",
  ui_story_5043_50431002_50_dialog_content = "Si el Salón de la Justicia pudiera hacer su trabajo, ¡entonces mi esposa no habría sufrido este destino!",
  ui_story_5043_50431002_51_dialog_content = "¡No importa el hecho de que tres de sus jueces no lograron encontrar al culpable! ¡Ni siquiera pudiste proteger una sola estatua!",
  ui_story_5043_50431002_52_dialog_content = "Solo espera hasta que el juez principal Irridon escucha de sus grandes éxitos!",
  ui_story_5043_50431002_53_dialog_content = "¡Estoy seguro de que no permitirá que una división llena de incompetentes arruine el buen nombre del Salón de Justicia!",
  ui_story_5043_50431002_54_dialog_content = "Lamento mucho haberlo decepcionado tanto, Sr. Byron.",
  ui_story_5043_50431002_55_dialog_content = "No pudimos proteger la estatua ni atrapar al culpable en la escena.",
  ui_story_5043_50431002_56_dialog_content = "Pero... pudimos conseguir un guante que llevaba puesto el culpable.",
  ui_story_5043_50431002_57_dialog_content = "¡Dios mío! Así que mi esposa ha perdido su hermosa cabeza y, a cambio, ¿usted tiene un guante?",
  ui_story_5043_50431002_58_dialog_content = "Seguramente no crees que este fue un intercambio que valió la pena.",
  ui_story_5043_50431002_59_dialog_content = "¿Cuántas personas viven en Lumópolis? ¿Cuántos pares de guantes tienen?",
  ui_story_5043_50431002_60_dialog_content = "¿Y qué harás con este guante, dado lo incompetente que es toda la División de Romance?",
  ui_story_5043_50431002_61_dialog_content = "Sr. Byron, por favor no despida a toda la División de Romance por las fallas de algunos empleados.",
  ui_story_5043_50431002_62_dialog_content = "Los jueces no han actuado bien. Pero como juez principal, me aseguro de que cada caso llegue a una conclusión justa.",
  ui_story_5043_50431002_63_dialog_content = "¿Una conclusión justa? Guarde las palabras bonitas para el juez principal Irridon!",
  ui_story_5043_50431002_64_dialog_content = "Mi amante y mi esposa han sido dañados. Y el culpable sigue prófugo.",
  ui_story_5043_50431002_65_dialog_content = "¿¡Llamas a esto justicia!?",
  ui_story_5043_50431002_66_dialog_content = "Todavía no, Sr. Byron. Pero no nos apresuremos demasiado.",
  ui_story_5043_50431002_67_dialog_content = "El culpable no ha escapado hasta que cae el mazo.",
  ui_story_5043_50431002_68_dialog_content = "Oh, ¿crees que puedes atrapar al criminal antes de que concluya el caso?",
  ui_story_5043_50431002_69_dialog_content = "Juez Leyn, presente el guante.",
  ui_story_5043_50431002_70_dialog_content = "Por supuesto.",
  ui_story_5043_50431002_71_dialog_content = "Este es un guante tomado de la mano del culpable en la escena. ¿Es eso correcto?",
  ui_story_5043_50431002_72_dialog_content = "Es. Casi atrapo al culpable, pero escapó quitándose el guante.",
  ui_story_5043_50431002_73_dialog_content = "Lo que simplifica las cosas. Quienquiera que sea el dueño del guante le quitó la cabeza a la estatua.",
  ui_story_5043_50431002_74_dialog_content = "Y da la casualidad que mi gente ha encontrado <color=#FFB400>el otro guante</color>.",
  ui_story_5043_50431002_75_dialog_content = "Como verás, los dos guantes son un par.",
  ui_story_5043_50431002_76_dialog_content = "¿¡El otro guante!?",
  ui_story_5043_50431002_77_dialog_content = "¡¿?!",
  ui_story_5043_50431002_78_dialog_content = "¿¡Pero cómo!?",
  ui_story_5043_50431002_79_dialog_content = "¿Dónde lo encontraste? ¿Y a quién pertenece?",
  ui_story_5043_50431002_80_dialog_content = "Y ahora que tenemos los guantes, podemos llevar fácilmente este caso a una conclusión justa.",
  ui_story_5043_50431002_81_dialog_content = "¡Guardias! ¡Prepárate!",
  ui_story_5043_50431002_82_dialog_content = "Y arrestar... Tina campbell!",
  ui_story_5043_50431002_83_dialog_content = "¿Qué? Arrestar Tina?",
  ui_story_5043_50431002_84_dialog_content = "¡Sí señor!",
  ui_story_5043_50431101_1_dialog_content = "¡Esperar! Esto no puede estar bien.",
  ui_story_5043_50431101_2_dialog_content = "Cómo puede ser Tina!",
  ui_story_5043_50431101_3_dialog_content = "Lo sé. No es posible.",
  ui_story_5043_50431101_4_dialog_content = "¿Es usted una especie de idiota, juez presidente Schwab?",
  ui_story_5043_50431101_5_dialog_content = "Ustedes, jueces, carecen de juicio. ¿No he dejado perfectamente claro mi razonamiento?",
  ui_story_5043_50431101_6_dialog_content = "El dueño del guante recogido por el juez Leyn es el culpable Eso es obvio.",
  ui_story_5043_50431101_7_dialog_content = "Y después de este último incidente, mi gente pudo identificar rápidamente a la otra mitad de la pareja.",
  ui_story_5043_50431101_8_dialog_content = "Y fue encontrado... en el cajón del escritorio de la jueza Tina.",
  ui_story_5043_50431101_9_dialog_content = "¿¡Qué!?",
  ui_story_5043_50431101_10_dialog_content = "Tina, ¿son estos tus guantes?",
  ui_story_5043_50431101_11_dialog_content = "Yo... yo tengo un par de guantes así.",
  ui_story_5043_50431101_12_dialog_content = "Pero no entiendo cómo aparecieron en la escena...",
  ui_story_5043_50431101_13_dialog_content = "Juez Tina, no estoy seguro de que entiendas cuán grave es tu situación.",
  ui_story_5043_50431101_14_dialog_content = "Dado que eres nuestro principal sospechoso, deberías contarnos cómo llegaron los guantes allí.",
  ui_story_5043_50431101_15_dialog_content = "Y nunca habría esperado que una cosita bonita como tú cometiera crímenes tan crueles.",
  ui_story_5043_50431101_16_dialog_content = "Ah, la tragedia de todo...",
  ui_story_5043_50431101_17_dialog_content = "¡Ey! Deja de calumniar a los pobres Tina!",
  ui_story_5043_50431101_18_dialog_content = "Tina estaba con nosotros cuando todo sucedió. ¡Lucha contra los eclipses!",
  ui_story_5043_50431101_19_dialog_content = "Todos podemos darle una coartada. ¡Ella no puede ser la culpable!",
  ui_story_5043_50431101_20_dialog_content = "Leyn, recuerda que debes responsabilizarte de tus declaraciones como juez.",
  ui_story_5043_50431101_21_dialog_content = "Estoy seguro de que no necesitas que te diga los castigos por perjurio.",
  ui_story_5043_50431101_22_dialog_content = "¡Pero tiene razón! ¡Y puedo probarlo!",
  ui_story_5043_50431101_23_dialog_content = "¿En realidad? Piénselo bien, todos ustedes.",
  ui_story_5043_50431101_24_dialog_content = "Cuando ocurrió el incidente, ¿era el juez Tina realmente a tu lado en la lucha contra los Eclipsites?",
  ui_story_5043_50431101_25_dialog_content = "Ella...",
  ui_story_5043_50431101_26_dialog_content = "Oye, ¿dónde está? Tina?",
  ui_story_5043_50431101_27_dialog_content = "Pensé que ella estaba contigo, Leyn?",
  ui_story_5043_50431101_28_dialog_content = "Supongo que se quedó atrás mientras yo regresaba corriendo.",
  ui_story_5043_50431101_29_dialog_content = "¿Ey? ¿Estás bien?",
  ui_story_5043_50431101_30_dialog_content = "(Oh no... ¡Ella realmente no estuvo con nosotros durante la pelea!)",
  ui_story_5043_50431101_31_dialog_content = "Parece que lo entiendes ahora.",
  ui_story_5043_50431101_32_dialog_content = "Al testificar bajo juramento, es imperativo que prestemos mucha atención a cada palabra que se pronuncie.",
  ui_story_5043_50431101_33_dialog_content = "Si no puede comprender un concepto básico como este, me temo que nunca será un juez digno en el Salón de Justicia.",
  ui_story_5043_50431101_34_dialog_content = "...",
  ui_story_5043_50431101_35_dialog_content = "En cualquier caso, el culpable ha sido capturado, así que pongamos fin a la farsa de hoy.",
  ui_story_5043_50431101_36_dialog_content = "¿Está satisfecho con los resultados de hoy, Sr. Byron?",
  ui_story_5043_50431101_37_dialog_content = "Nunca hubiera esperado que un juez fuera el culpable de todo esto...",
  ui_story_5043_50431101_38_dialog_content = "¡Con razón ustedes no hacen nada por aquí!",
  ui_story_5043_50431101_39_dialog_content = "Eso no es todo, Sr. Byron...",
  ui_story_5043_50431101_40_dialog_content = "Fui lo suficientemente tonto como para poner mi fe en ti...",
  ui_story_5043_50431101_41_dialog_content = "¿Y qué obtuve a cambio, eh? ¡Un grupo de inadaptados discutiendo sobre el amor mientras lo destruyen y me hacen perder el tiempo!",
  ui_story_5043_50431101_42_dialog_content = "¡Esta pésima criminal responde mejor por sus crímenes, Juez Jefe Schwab! ¡Lo digo en serio!",
  ui_story_5043_50431101_43_dialog_content = "Le aseguro que será llevada ante la justicia, Sr. Byron... Pero no hoy.",
  ui_story_5043_50431101_44_dialog_content = "No olvidemos que mañana se llevará a cabo el juicio del decapitador de estatuas.",
  ui_story_5043_50431101_45_dialog_content = "En ese momento, puede presentar su reclamo ante el tribunal.",
  ui_story_5043_50431101_46_dialog_content = "¡Soy muy consciente de eso!",
  ui_story_5043_50431101_47_dialog_content = "Mi amante, mi esposa... ¡Son las verdaderas víctimas de todo esto! ¡No se merecían lo que les pasó!",
  ui_story_5043_50431101_48_dialog_content = "¡Prométame que buscará justicia para ellos, juez presidente Schwab!",
  ui_story_5043_50431101_49_dialog_content = "Pero por supuesto. Después de todo, la División de Romance tiene el deber de proteger la santidad del amor.",
  ui_story_5043_50431101_50_dialog_content = "¡Guardias! ¡Llévatela!",
  ui_story_5043_50431101_51_dialog_content = "¡Un momento por favor!",
  ui_story_5043_50431101_52_dialog_content = "Señoría, me gustaría inspeccionar ese guante una vez más.",
  ui_story_5043_50431101_53_dialog_content = "No hay forma Tina podría haber cometido este crimen... ¿Quizás malinterpretamos algunas partes de la evidencia?",
  ui_story_5043_50431101_54_dialog_content = "¡De cualquier manera, no podemos tenerla detenida tan apresuradamente!",
  ui_story_5043_50431101_55_dialog_content = "¡Escucha Escucha! ¡El hecho de que sea el mismo estilo de guante no significa necesariamente que pertenezca al par original!",
  ui_story_5043_50431101_56_dialog_content = "De hecho, ¡se sabe que compro siete pares de los mismos guantes de vez en cuando!",
  ui_story_5043_50431101_57_dialog_content = "Leyn... Matthieu...",
  ui_story_5043_50431101_58_dialog_content = "Basta, jueces. Me he hartado de ridículas especulaciones por un día.",
  ui_story_5043_50431101_59_dialog_content = "Si tiene algo más que decir, le sugiero que lo guarde para el juicio de mañana.",
  ui_story_5043_50431101_60_dialog_content = "¿Pero por qué? Solo quiero echar un vistazo...",
  ui_story_5043_50431101_61_dialog_content = "Dije, ES SUFICIENTE.",
  ui_story_5043_50431101_62_dialog_content = "El sospechoso será llevado a confinamiento solitario en breve. Nadie podrá verla hasta el comienzo de los procedimientos de mañana.",
  ui_story_5043_50431101_63_dialog_content = "¡¿Confinamiento solitario?! ¡¿Te has vuelto loco?!",
  ui_story_5043_50431101_64_dialog_content = "¡No tienes derecho a ponerla en confinamiento solitario antes de su juicio! ¡Eso es contra la ley!",
  ui_story_5043_50431101_65_dialog_content = "Como juez principal de la División de Romance, se me ha otorgado la autoridad exclusiva para levantar la grava y decidir quién es culpable.",
  ui_story_5043_50431101_66_dialog_content = "Ponerla en confinamiento solitario es solo otro paso necesario en el proceso, ¿o dudas del Salón de Justicia y sus leyes?",
  ui_story_5043_50431101_67_dialog_content = "Tú—",
  ui_story_5043_50431101_68_dialog_content = "¡N-No se apresuren, todos!",
  ui_story_5043_50431101_69_dialog_content = "Seguiré la decisión del juez Schwab por ahora. Tendremos que disputar las acusaciones en la corte mañana.",
  ui_story_5043_50431101_70_dialog_content = "Tina...",
  ui_story_5043_50431101_71_dialog_content = "Soy juez, así que debo creer que el sistema de justicia de Lumopolis nunca castigaría injustamente a una persona inocente.",
  ui_story_5043_50431101_72_dialog_content = "Estoy seguro de que la verdad se aclarará durante el juicio de mañana...",
  ui_story_5043_50431101_73_dialog_content = "Porque creo en la División Romance.",
  ui_story_5043_50431101_74_dialog_content = "Y creo en todos ustedes.",
  ui_story_5043_50431101_75_dialog_content = "...",
  ui_story_5043_50431101_76_dialog_content = "...",
  ui_story_5043_50431101_77_dialog_content = "Llévatela, guardias.",
  ui_story_5043_50431101_78_dialog_content = "¡Sí señor!",
  ui_story_5043_50431101_79_dialog_content = "<color=#e8d9bb>Fuera del Salón de la Justicia, Lumopolis Gardens</color>",
  ui_story_5043_50431101_80_dialog_content = "ellos bloquearon Tina arriba. ¿Qué vamos a hacer?",
  ui_story_5043_50431101_81_dialog_content = "No crees que la encontrarán culpable mañana, ¿verdad?",
  ui_story_5043_50431101_82_dialog_content = "Si las cosas siguen como están ahora... lo harán.",
  ui_story_5043_50431101_83_dialog_content = "¡N-No podemos permitir que eso suceda! ¡Ella es inocente!",
  ui_story_5043_50431101_84_dialog_content = "¿Soy solo yo, o algo sobre Schwab parecía extraño hoy?",
  ui_story_5043_50431101_85_dialog_content = "¿Ah?",
  ui_story_5043_50431101_86_dialog_content = "Bueno, siempre he pensado en él como una persona muy extraña, pero ahora que lo mencionas...",
  ui_story_5043_50431101_87_dialog_content = "Su actitud hoy parecía un poco extrema.",
  ui_story_5043_50431101_88_dialog_content = "Se oponía muy claramente a nosotros, sí.",
  ui_story_5043_50431101_89_dialog_content = "Embelleció cualquier información que implicara Tinae ignoró todas nuestras refutaciones.",
  ui_story_5043_50431101_90_dialog_content = "Precisamente. Es demasiado para ser solo una coincidencia, ¿no crees?",
  ui_story_5043_50431101_91_dialog_content = "En el momento en que ocurrió el incidente, su gente se encontró con ese guante y lo presentó como evidencia.",
  ui_story_5043_50431101_92_dialog_content = "Es casi como si ya supiera dónde estaba el otro guante...",
  ui_story_5043_50431101_93_dialog_content = "No solo eso. Parecía tener una comprensión muy detallada de lo que sucedió en la escena del crimen.",
  ui_story_5043_50431101_94_dialog_content = "¿Recuerdas esa mirada repugnante y satisfecha que tenía en su rostro?",
  ui_story_5043_50431101_95_dialog_content = "¿En realidad? Piénselo bien, todos ustedes.",
  ui_story_5043_50431101_96_dialog_content = "Cuando ocurrió el incidente, ¿era el juez Tina realmente a tu lado en la lucha contra los Eclipsites?",
  ui_story_5043_50431101_97_dialog_content = "Para empezar, nunca estuvo allí, entonces, ¿qué le dio la confianza para preguntarnos eso?",
  ui_story_5043_50431101_98_dialog_content = "¡Estás en lo correcto!",
  ui_story_5043_50431101_99_dialog_content = "Cuando se tienen en cuenta todos estos factores, los procedimientos del tribunal contra Tina fue demasiado bien hoy.",
  ui_story_5043_50431101_100_dialog_content = "Todo apuntaba a Tina ser culpable sin duda...",
  ui_story_5043_50431101_101_dialog_content = "Pero ninguna de estas cosas fue tan extraña como su decisión final.",
  ui_story_5043_50431101_102_dialog_content = "La decisión de encerrarla.",
  ui_story_5043_50431101_103_dialog_content = "No podría estar mas de acuerdo.",
  ui_story_5043_50431101_104_dialog_content = "Encontrar ese guante, saber exactamente lo que sucedió en la escena del crimen... Podía explicar estas cosas fácilmente, tal vez hubo muchos testigos, o fue pura suerte.",
  ui_story_5043_50431101_105_dialog_content = "Todos los procedimientos eran legítimos y no habría cabos sueltos en su acusación.",
  ui_story_5043_50431101_106_dialog_content = "En efecto. Pero se había cansado de probarse a sí mismo al final.",
  ui_story_5043_50431101_107_dialog_content = "Nos prohibió inspeccionar la evidencia y encerró Tina en confinamiento solitario sin ofrecer una razón.",
  ui_story_5043_50431101_108_dialog_content = "Esto significa que está ocultando algo, algo que no puede permitirse que otros vean.",
  ui_story_5043_50431101_109_dialog_content = "Especialmente no nosotros.",
  ui_story_5043_50431101_110_dialog_content = "Debe ser una pista importante, para él romper las reglas para encubrirlo.",
  ui_story_5043_50431101_111_dialog_content = "¡Algo me dice que esa pista es la clave para descubrir la verdad y probar la inocencia de Tina!",
  ui_story_5043_50431101_112_dialog_content = "¡Guau! ¡Qué brillante deducción!",
  ui_story_5043_50431101_113_dialog_content = "Cuida tus palabras.",
  ui_story_5043_50431101_114_dialog_content = "Esta es la puerta del Salón de la Justicia.",
  ui_story_5043_50431101_115_dialog_content = "Oh, sí, deberíamos mantenerlo bajo.",
  ui_story_5043_50431101_116_dialog_content = "Entonces, todo lo que tenemos que hacer es descubrir qué nos está ocultando Schwab, y podremos probar la inocencia de Tina, ¿verdad?",
  ui_story_5043_50431101_117_dialog_content = "Suena fácil cuando lo pones de esa manera, pero me preocupa que no podamos resolverlo a tiempo.",
  ui_story_5043_50431101_118_dialog_content = "¿Ah?",
  ui_story_5043_50431101_119_dialog_content = "Schwab definitivamente va a atar cualquier cabo suelto antes del juicio de mañana.",
  ui_story_5043_50431101_120_dialog_content = "Él sabe lo que hay que hacer para cubrir sus huellas de las que no tenemos idea.",
  ui_story_5043_50431101_121_dialog_content = "Estoy seguro de que tiene muchas contingencias preparadas, en caso de que algo salga mal.",
  ui_story_5043_50431101_122_dialog_content = "Las probabilidades de que tenga éxito están fuertemente a su favor.",
  ui_story_5043_50431101_123_dialog_content = "Entonces, ¿estamos esperando hasta el juicio y esperando lo mejor?",
  ui_story_5043_50431101_124_dialog_content = "si lo hacemos, Tina definitivamente será declarado culpable.",
  ui_story_5043_50431101_125_dialog_content = "Lo que significa que debemos desenterrar algunas pistas antes de que comience el juicio.",
  ui_story_5043_50431101_126_dialog_content = "Si no podemos llegar al fondo del secreto de Schwab, tendremos que buscar otras pistas.",
  ui_story_5043_50431101_127_dialog_content = "Jajaja, una sugerencia interesante!",
  ui_story_5043_50431101_128_dialog_content = "Y algo me dice que ya sabes por dónde empezar, ¿no?",
  ui_story_5043_50431101_129_dialog_content = "Oigan, es mejor que ustedes tres no hagan nada estúpido, ¿me oyen?",
  ui_story_5043_50431101_130_dialog_content = "¡Vamos, Loewe! Nunca soñaríamos con eso.",
  ui_story_5043_50431101_131_dialog_content = "... Todavía tengo más investigaciones, así que me iré ahora.",
  ui_story_5043_50431101_132_dialog_content = "Si los atrapan haciendo algo estúpido, nunca estuve aquí, y nunca tuvimos esta conversación. ¿Entender?",
  ui_story_5043_50431101_133_dialog_content = "Tú...",
  ui_story_5043_50431101_134_dialog_content = "Es mejor de esta forma, Matthieu. Más gente sólo se interpondría en el camino.",
  ui_story_5043_50431101_135_dialog_content = "Ahora acérquense ustedes dos.",
  ui_story_5043_50431101_136_dialog_content = "Claro, ¿qué es?",
  ui_story_5043_50431101_137_dialog_content = "Si Schwab estaba dispuesto a romper las reglas para ocultar su secreto...",
  ui_story_5043_50431101_138_dialog_content = "Tendremos que hacer lo mismo si queremos vencerlo.",
  ui_story_5043_50431101_139_dialog_content = "Pero, ¿cómo exactamente?",
  ui_story_5043_50431101_140_dialog_content = "Vamos a irrumpir en la casa de Schwab.",
  ui_story_5043_50431101_141_dialog_content = "¡¿Qué?!",
  ui_story_5043_50431101_142_dialog_content = "Si no podemos acercarnos al sospechoso oa la evidencia, tendremos que ir con la siguiente mejor opción: el propio Schwab.",
  ui_story_5043_50431101_143_dialog_content = "Y su hogar es el lugar más seguro para guardar sus secretos.",
  ui_story_5043_50431101_144_dialog_content = "Si realmente está ocultando algo importante, ese sería el mejor lugar para comenzar a buscar.",
  ui_story_5043_50431101_145_dialog_content = "Pero... ¿no sería eso contra la ley?",
  ui_story_5043_50431101_146_dialog_content = "¡Esto es interesante! ¡Qué maravillosa idea!",
  ui_story_5043_50431101_147_dialog_content = "¡Entonces eso lo resuelve! ¡Vamos a visitar la mansión del buen juez!",
  ui_story_5043_50431101_148_dialog_content = "Supongo que soy el único al que le importa la ley... Bien, me apunto.",
  ui_story_5043_50431101_149_dialog_content = "La única razón por la que estamos en esta situación es porque nuestro oponente nos hizo lo mismo.",
  ui_story_5043_50431101_150_dialog_content = "Cuando llegue el momento, con mucho gusto asumiré toda la responsabilidad por irrumpir en su casa.",
  ui_story_5043_50431101_151_dialog_content = "Pero lo que más importa ahora es asegurarse de que Tina no es castigada por un crimen que no cometió.",
  ui_story_5043_50431101_152_dialog_content = "Hmph. ¿Toda la responsabilidad, dices?",
  ui_story_5043_50431101_153_dialog_content = "Suspiro, ese tipo de honestidad solo te causará problemas en el futuro, ya sabes.",
  ui_story_5043_50431101_154_dialog_content = "Tienes razón... ¡Probar la inocencia de Tina es lo primero!",
  ui_story_5043_50431101_155_dialog_content = "Entonces, ¿deberíamos irnos ahora?",
  ui_story_5043_50431101_156_dialog_content = "Todavía hay una última cosa que tenemos que hacer antes de eso.",
  ui_story_5043_50431101_157_dialog_content = "No sé si ustedes dos se dieron cuenta, pero esos guardias detrás de nosotros nos han estado siguiendo durante bastante tiempo.",
  ui_story_5043_50431101_158_dialog_content = "Schwab debe haberles ordenado que nos vigilaran. No hay forma de que simplemente nos deje ir.",
  ui_story_5043_50431101_159_dialog_content = "Parece que tendremos que quitárnoslos de encima, entonces.",
  ui_story_5043_50431101_160_dialog_content = "Mis pensamientos exactamente.",
  ui_story_5043_50431101_161_dialog_content = "Debería ser bastante fácil. Después de todo, soy un profesional cuando se trata de huir.",
  ui_story_5043_50431101_162_dialog_content = "No lo olvides, tengo un par extra de \"ojos\" en ellos.",
  ui_story_5043_50431101_163_dialog_content = "¡Así es! ¡Podemos usar tus habilidades psíquicas en ellos!",
  ui_story_5043_50431101_164_dialog_content = "Entonces, como nuestro artista de escape residente, ¿cuál debería ser nuestro primer paso?",
  ui_story_5043_50431101_165_dialog_content = "Es bastante simple, en realidad.",
  ui_story_5043_50431101_166_dialog_content = "El primer paso para huir—",
  ui_story_5043_50431101_167_dialog_content = "—es para empezar a correr!!!",
  ui_story_5043_50431102_1_dialog_content = "¡Gire a la derecha más adelante!",
  ui_story_5043_50431102_2_dialog_content = "Ah, esto es positivamente agotador.",
  ui_story_5043_50431102_3_dialog_content = "¿Bien? ¿Hay algún guardia siguiendo nuestro rastro?",
  ui_story_5043_50431102_4_dialog_content = "¡No! ¡Ni uno solo!",
  ui_story_5043_50431102_5_dialog_content = "¿Qué? ¡¿Entonces por qué seguimos corriendo?!",
  ui_story_5043_50431102_6_dialog_content = "A-¿No vamos a ir a la casa de Schwab ahora mismo?",
  ui_story_5043_50431102_7_dialog_content = "Estoy seguro de que este es el camino correcto.",
  ui_story_5043_50431102_8_dialog_content = "Sí, pero si nadie nos persigue, ¡podemos caminar el resto del camino hasta allí!",
  ui_story_5043_50431102_9_dialog_content = "Además, ¿cómo sabes que su casa está por aquí?",
  ui_story_5043_50431102_10_dialog_content = "Porque yo le dije.",
  ui_story_5043_50431102_11_dialog_content = "Estamos cortos de tiempo, así que pensé que correr hasta allí sería más rápido.",
  ui_story_5043_50431102_12_dialog_content = "¡Al menos podrías haberme dicho que perdimos a los guardias! ¡Estaba aterrorizado de que estuvieran pisándonos los talones todo este tiempo!",
  ui_story_5043_50431102_13_dialog_content = "Está bien, está bien, baja la voz. Su casa está justo adelante.",
  ui_story_5043_50431102_14_dialog_content = "Por qué tú...",
  ui_story_5043_50431102_15_dialog_content = "<color=#e8d9bb>Fuera del Salar Manor, Lumopolis Gardens</color>",
  ui_story_5043_50431102_16_dialog_content = "Parece que tienen muchos guardias y sirvientes apostados en la entrada.",
  ui_story_5043_50431102_17_dialog_content = "¿Cómo se supone que debemos evitarlos Y buscar pistas?",
  ui_story_5043_50431102_18_dialog_content = "Tienes razón, no será fácil.",
  ui_story_5043_50431102_19_dialog_content = "Si alguno de ellos nos ve, estaremos sentados al lado Tina en el muelle mañana.",
  ui_story_5043_50431102_20_dialog_content = "Sabiendo eso, ¿ustedes dos todavía están dispuestos a seguir adelante con esto?",
  ui_story_5043_50431102_21_dialog_content = "Esta es nuestra única opción si queremos probar Tina inocente...",
  ui_story_5043_50431102_22_dialog_content = "¡Debemos hacerlo, no importa lo peligroso que sea!",
  ui_story_5043_50431102_23_dialog_content = "Hay un lado positivo en este esquema imprudente. La casa de Schwab definitivamente es lo suficientemente grande como para permitirnos muchos lugares para escondernos.",
  ui_story_5043_50431102_24_dialog_content = "Con eso y algunas habilidades psíquicas, deberíamos poder evitar los peligros lo suficientemente bien.",
  ui_story_5043_50431102_25_dialog_content = "¡Me aseguraré de vigilar de cerca nuestro entorno! ¡Sólo déjamelo a mi!",
  ui_story_5043_50431102_26_dialog_content = "Entonces, ¿cómo exactamente ponemos un pie dentro de la mansión?",
  ui_story_5043_50431102_27_dialog_content = "No estoy seguro de que tengamos suficiente tiempo para esperar a que los guardias cambien de turno...",
  ui_story_5043_50431102_28_dialog_content = "No importa, ya que no entraremos por la puerta principal.",
  ui_story_5043_50431102_29_dialog_content = "¿Oh? Entonces, ¿viste otra puerta por casualidad?",
  ui_story_5043_50431102_30_dialog_content = "No, pero mira ese jardín de allí. Tiene muchos setos que podemos usar para cubrirnos.",
  ui_story_5043_50431102_31_dialog_content = "Una vez que estemos lo suficientemente cerca, simplemente saltaremos la pared.",
  ui_story_5043_50431102_32_dialog_content = "Saltar sobre la pared?!",
  ui_story_5043_50431102_33_dialog_content = "¡Tienes razón! Es perfecto para pasar desapercibido, y mira, ¡la pared tampoco es tan alta!",
  ui_story_5043_50431102_34_dialog_content = "Vamos, pongámonos en movimiento.",
  ui_story_5043_50431102_35_dialog_content = "¡Entendido!",
  ui_story_5043_50431102_36_dialog_content = "¡E-esperen un minuto, ustedes dos! ¿No crees que saltar la pared es un poco impropio?",
  ui_story_5043_50431102_37_dialog_content = "Después de todo, soy un miembro orgulloso de Sawyer—",
  ui_story_5043_50431102_38_dialog_content = "—Uf, olvídalo. Honestamente, ustedes, los plebeyos, van a ser mi muerte.",
  ui_story_5043_50431201_1_dialog_content = "Ugh... ¿Por qué debo hacer algo tan tonto...?",
  ui_story_5043_50431201_2_dialog_content = "Sólo sonreír y aguantar, Matthieu. Estamos haciendo esto para limpiar el nombre de Tina.",
  ui_story_5043_50431201_3_dialog_content = "¿Ver? ¡Ya hemos llegado a la mansión!",
  ui_story_5043_50431201_4_dialog_content = "Todo se ve tan elegante aquí...",
  ui_story_5043_50431201_5_dialog_content = "Así que esta es la casa de Schwab, ¿eh?",
  ui_story_5043_50431201_6_dialog_content = "Sí... Tengo que admitir que me da un poco de envidia.",
  ui_story_5043_50431201_7_dialog_content = "La Familia Salar es una de las más influyentes de todo Lumopolis.",
  ui_story_5043_50431201_8_dialog_content = "Lo que vemos aquí es solo la punta del iceberg cuando se trata de su riqueza, estoy seguro—",
  ui_story_5043_50431201_9_dialog_content = "Muy bien, dale un descanso ya. Creo que veo a alguien más adelante.",
  ui_story_5043_50431201_10_dialog_content = "Vamos a echar un vistazo.",
  ui_story_5043_50431201_11_dialog_content = "¡Oye, yo también los veo!",
  ui_story_5043_50431201_12_dialog_content = "Espera, ¿eso es... Schwab?",
  ui_story_5043_50431201_13_dialog_content = "Perdónenos, Maestro Schwab, les perdimos el rastro.",
  ui_story_5043_50431201_14_dialog_content = "Caelestite y los dos jueces aprovecharon los caminos sinuosos para que no pudiéramos alcanzarlos...",
  ui_story_5043_50431201_15_dialog_content = "¿Es por eso que los contraté tontos, hmm?",
  ui_story_5043_50431201_16_dialog_content = "¡Inútil! ¡La suerte de ustedes!",
  ui_story_5043_50431201_17_dialog_content = "¡Perdónanos, mi señor!",
  ui_story_5043_50431201_18_dialog_content = "... Suficiente. Lo hecho, hecho está.",
  ui_story_5043_50431201_19_dialog_content = "Ahora que están huyendo, tal vez algo bueno salga de tu estúpido error.",
  ui_story_5043_50431201_20_dialog_content = "Regresa a tus publicaciones.",
  ui_story_5043_50431201_21_dialog_content = "¡Sí, maestro Schwab!",
  ui_story_5043_50431201_22_dialog_content = "Así que sus hombres nos estaban espiando... ¡Ja! ¡Como si fuera a dejarlo hacer lo que le plazca!",
  ui_story_5043_50431201_23_dialog_content = "Me alegro de que hayamos podido encontrar a Schwab tan rápido.",
  ui_story_5043_50431201_24_dialog_content = "Sigamos siguiéndolo, y veamos qué va a hacer.",
  ui_story_5043_50431201_25_dialog_content = "¡Cualquier cambio en su comportamiento podría proporcionarnos las pistas que necesitamos!",
  ui_story_5043_50431201_26_dialog_content = "¡Entendido!",
  ui_story_5043_50431201_27_dialog_content = "Para que ustedes dos no lo olviden, Schwab no es un hombre que se pueda entender fácilmente.",
  ui_story_5043_50431201_28_dialog_content = "Si está dispuesto a infringir la ley ante todo el Salón de la Justicia, quién sabe qué actos indescriptibles es capaz de realizar en la privacidad de su propia casa...",
  ui_story_5043_50431201_29_dialog_content = "O-Está bien, ahora me estás empezando a asustar.",
  ui_story_5043_50431201_30_dialog_content = "Bien. Tu miedo te mantendrá alerta.",
  ui_story_5043_50431201_31_dialog_content = "Ven, no lo perdamos de vista.",
  ui_story_5043_50431201_32_dialog_content = "Su té, mi señor.",
  ui_story_5043_50431201_33_dialog_content = "Bien, dale aquí.",
  ui_story_5043_50431201_34_dialog_content = "La cocina está preparando unos postres. ¿Le traigo un plato, Maestro?",
  ui_story_5043_50431201_35_dialog_content = "Eso no será necesario. Tengo otros asuntos que atender en este momento.",
  ui_story_5043_50431201_36_dialog_content = "No me molestes hasta que haya terminado con ellos.",
  ui_story_5043_50431201_37_dialog_content = "¡S-Sí, Maestro Schwab!",
  ui_story_5043_50431201_38_dialog_content = "Despidió a su sirviente.",
  ui_story_5043_50431201_39_dialog_content = "Shhh... ¿Podrían estos asuntos ser tan perversos que incluso su propia gente no puede estar al tanto de ellos?",
  ui_story_5043_50431201_40_dialog_content = "Er... ¿M-Tal vez solo quiere estar solo por un tiempo?",
  ui_story_5043_50431201_41_dialog_content = "Honestamente, PlayerName... ¿No tienes imaginación?",
  ui_story_5043_50431201_42_dialog_content = "¿Dije o no acabo de decir que Schwab no es un hombre que pueda entenderse fácilmente?",
  ui_story_5043_50431201_43_dialog_content = "Bien, bien. Lo entiendo.",
  ui_story_5043_50431201_44_dialog_content = "Aún así, ¿qué tan malo podría ser? ¿Qué podría hacer un hombre complicado como él en su propio jardín?",
  ui_story_5043_50431201_45_dialog_content = "¡Mirar! ¡Está levantando la mano ahora!",
  ui_story_5043_50431201_46_dialog_content = "Parece que está sosteniendo algo.",
  ui_story_5043_50431201_47_dialog_content = "¡Es una aguja! ¡Tiene una aguja en la mano!",
  ui_story_5043_50431201_48_dialog_content = "¡¿Una aguja?!",
  ui_story_5043_50431201_49_dialog_content = "¿Con qué propósito? ¿Quiere usarlo en sí mismo?",
  ui_story_5043_50431201_50_dialog_content = "No, no en sí mismo...",
  ui_story_5043_50431201_51_dialog_content = "<color=#e8d9bb>¡Puñalada!</color>",
  ui_story_5043_50431201_52_dialog_content = "Lo está usando en esa muñeca en su otra mano...",
  ui_story_5043_50431201_53_dialog_content = "¡¿P-Por qué le está haciendo eso a una muñeca?!",
  ui_story_5043_50431201_54_dialog_content = "He oído hablar de esto antes... Un tipo de maldición que involucra el uso de muñecas.",
  ui_story_5043_50431201_55_dialog_content = "¿Una maldicion?",
  ui_story_5043_50431201_56_dialog_content = "Funciona tomando algo del cuerpo de una persona, generalmente cabello o sangre, y colocándolo dentro de una muñeca.",
  ui_story_5043_50431201_57_dialog_content = "Al hacerlo, la muñeca se vincula espiritualmente con esa persona.",
  ui_story_5043_50431201_58_dialog_content = "Pinchar o dañar a la muñeca inflige el mismo dolor y lesiones al objetivo de la maldición.",
  ui_story_5043_50431201_59_dialog_content = "¡Y eventualmente, la persona moriría de una muerte insoportablemente dolorosa!",
  ui_story_5043_50431201_60_dialog_content = "<color=#e8d9bb>¡Puñalada!</color>",
  ui_story_5043_50431201_61_dialog_content = "¡Tsk, lo hizo de nuevo!",
  ui_story_5043_50431201_62_dialog_content = "Creo que he oído hablar de maldiciones como esa, pero nunca esperé que alguien como Schwab incursionara en las artes oscuras...",
  ui_story_5043_50431201_63_dialog_content = "Bueno, no me sorprende en absoluto. ¡Desde hace mucho tiempo he visto a través de su gentil y noble farsa!",
  ui_story_5043_50431201_64_dialog_content = "No sé... Maldiciones como esta suelen ser solo una superstición espeluznante, ¿verdad?",
  ui_story_5043_50431201_65_dialog_content = "Además, esto sería una violación atroz de la fe de Lumopolis...",
  ui_story_5043_50431201_66_dialog_content = "Veo. No importa si la maldición es real o no. Lo que importa es si la gente cree o no en ello.",
  ui_story_5043_50431201_67_dialog_content = "Y me queda claro que Schwab cree en ello.",
  ui_story_5043_50431201_68_dialog_content = "Lo que significa que en algún lugar del mundo... Hay una persona a la que Schwab odia lo suficiente como para querer matarla...",
  ui_story_5043_50431201_69_dialog_content = "<color=#e8d9bb>¡Puñalada!</color>",
  ui_story_5043_50431201_70_dialog_content = "¿Pero quién? ¡¿Quien podría ser?!",
  ui_story_5043_50431201_71_dialog_content = "¿Quién podría haberlo agraviado tanto, que les desearía la muerte?",
  ui_story_5043_50431201_72_dialog_content = "No tengo idea... Pero realmente te hace preguntarte, ¿no?",
  ui_story_5043_50431201_73_dialog_content = "Según la mayoría de las versiones, Schwab vive una vida casi perfecta... No puedo imaginar quién podría arruinarle eso.",
  ui_story_5043_50431201_74_dialog_content = "A menos que... su odio provenga de un lugar donde nadie pueda verlo fácilmente.",
  ui_story_5043_50431201_75_dialog_content = "Cuando lo pones de esa manera... ¡Sí, ahora tiene mucho sentido!",
  ui_story_5043_50431201_76_dialog_content = "Claramente, su ira proviene de un recuerdo perdido pero inolvidable. <color=#FFB400>amar</color>!",
  ui_story_5043_50431201_77_dialog_content = "<color=#e8d9bb>¡Puñalada!</color>",
  ui_story_5043_50431201_78_dialog_content = "Si eso es cierto, ¡tenemos que hacer algo al respecto de inmediato! ¡Podría significar la diferencia entre la vida y la muerte para alguien!",
  ui_story_5043_50431201_79_dialog_content = "No nos apresuremos. Debemos esperar a que muestre pruebas claras e innegables de haber actuado mal antes de que podamos interferir.",
  ui_story_5043_50431201_80_dialog_content = "¿Qué podríamos hacer ahora mismo, dados nuestros conocimientos actuales? ¿Evitar que pinche a esa pobre muñeca?",
  ui_story_5043_50431201_81_dialog_content = "Oye, no crees que esas supersticiones sean ciertas... ¿verdad?",
  ui_story_5043_50431201_82_dialog_content = "¿Te refieres a usar una muñeca para maldecir a alguien?",
  ui_story_5043_50431201_83_dialog_content = "Sí...",
  ui_story_5043_50431201_84_dialog_content = "Porque si lo son, es posible...",
  ui_story_5043_50431201_85_dialog_content = "... que estamos presenciando una escena del crimen!",
  ui_story_5043_50431201_86_dialog_content = "Ahora el toque final...",
  ui_story_5043_50431201_87_dialog_content = "Deja que esta pequeña y miserable existencia...",
  ui_story_5043_50431201_88_dialog_content = "¡Tenemos que detenerlo! ¡Apurarse!",
  ui_story_5043_50431201_89_dialog_content = "<color=#e8d9bb>¡Puñalada!</color>",
  ui_story_5043_50431201_90_dialog_content = "-¡¡¡ser renacido!!!",
  ui_story_5043_50431201_91_dialog_content = "Mi... Eres lindo, ¿no?",
  ui_story_5043_50431201_92_dialog_content = "Ahora bien, ¿cómo debería llamarte? ¿Qué tal... Castaño?",
  ui_story_5043_50431201_93_dialog_content = "E-Así que eso es... ¿un erizo de peluche?",
  ui_story_5043_50431201_94_dialog_content = "Seguro que parece un erizo.",
  ui_story_5043_50431201_95_dialog_content = "Incluso le dio un nombre apropiado. ¿Ver? Parece un pequeño castaño.",
  ui_story_5043_50431201_96_dialog_content = "<size=45>Entonces, ¿de qué nos estamos volviendo locos?</size>",
  ui_story_5043_50431201_97_dialog_content = "¡Shhh! Tranquilo, PlayerName!",
  ui_story_5043_50431201_98_dialog_content = "Suspiro... No puedo creer lo estúpidos que somos hablando de que Schwab asesinó a alguien.",
  ui_story_5043_50431201_99_dialog_content = "Er, bueno, prueba y error es sólo una parte natural de una investigación.",
  ui_story_5043_50431201_100_dialog_content = "Solo eliminando todas las demás posibilidades se revelará la verdad. Todo es parte del proceso.",
  ui_story_5043_50431201_101_dialog_content = "Lo que sea que te ayude a dormir por la noche, Leyn...",
  ui_story_5043_50431201_102_dialog_content = "Ejem... De todos modos, olvidémonos de nuestra conversación de hace un momento y concentrémonos en ayudar. Tina.",
  ui_story_5043_50431201_103_dialog_content = "Schwab va a volver adentro ahora, lo más probable es que se prepare para el juicio de mañana.",
  ui_story_5043_50431201_104_dialog_content = "Deberíamos ir a echar un vistazo más de cerca.",
  ui_story_5043_50431201_105_dialog_content = "Suspiro, parece que mi pequeño experimento aún está lejos de estar completo. ¿Quizás progrese más hoy...?",
  ui_story_5043_50431201_106_dialog_content = "¿Se enteró que? ¡Un experimento!",
  ui_story_5043_50431201_107_dialog_content = "Sí, ¿qué podría estar investigando allí?",
  ui_story_5043_50431201_108_dialog_content = "Nada bueno, supongo. Después de todo, es un hombre difícil de entender.",
  ui_story_5043_50431201_109_dialog_content = "Otra vez esto no, Matthieu...",
  ui_story_5043_50431201_110_dialog_content = "No saquemos conclusiones locas de nuevo. No después de la última vez.",
  ui_story_5043_50431201_111_dialog_content = "¿Tal vez es solo un pequeño experimento en casa? Podría ser un pasatiempo suyo...",
  ui_story_5043_50431201_112_dialog_content = "<color=#e8d9bb>¡Bang—!</color>",
  ui_story_5043_50431201_113_dialog_content = "¡Wow!",
  ui_story_5043_50431201_114_dialog_content = "¡¿Eso fue una explosión?! ¡¿Qué diablos está haciendo ahí dentro?!",
  ui_story_5043_50431201_115_dialog_content = "No sé. ¿Deberíamos acercarnos un poco más y ver?",
  ui_story_5043_50431201_116_dialog_content = "¿Cómo? ¡No hay dónde esconderse en esa habitación!",
  ui_story_5043_50431201_117_dialog_content = "Si nos acercamos más de lo que estamos ahora, nuestra tapadera será descubierta...",
  ui_story_5043_50431201_118_dialog_content = "<color=#e8d9bb>¡Bang—!</color>",
  ui_story_5043_50431201_119_dialog_content = "¡Otra explosión! ¿Podría ser que está haciendo una bomba?",
  ui_story_5043_50431201_120_dialog_content = "¡¿Una bomba?! ¡Espera, estamos sacando conclusiones precipitadas otra vez!",
  ui_story_5043_50431201_121_dialog_content = "¿Y por qué no? ¡Este es más o menos el negocio familiar de los Salar!",
  ui_story_5043_50431201_122_dialog_content = "<color=#e8d9bb>¡Bang—!</color>",
  ui_story_5043_50431201_123_dialog_content = "Pero, ¿por qué estaría investigando explosivos?",
  ui_story_5043_50431201_124_dialog_content = "Bueno, cuanto más intrincado es el diseño de un lugar, más susceptible es a los explosivos. Lumópolis no es una excepción.",
  ui_story_5043_50431201_125_dialog_content = "Piénsalo: alguien acudiría a los tribunales por el vandalismo de las estatuas.",
  ui_story_5043_50431201_126_dialog_content = "¿Y si es una torre de reloj o una iglesia? Las consecuencias serían mucho más inimaginables.",
  ui_story_5043_50431201_127_dialog_content = "¡Al aprovechar el poder destructivo de las bombas, pueden usar el miedo para obligar a otros a obedecerlos!",
  ui_story_5043_50431201_128_dialog_content = "No sé... Su \"bomba\" no hizo ni un rasguño en su casa.",
  ui_story_5043_50431201_129_dialog_content = "¡Por eso lo llamó su \"pequeño experimento\"!",
  ui_story_5043_50431201_130_dialog_content = "Una vez que comprenda completamente la ciencia detrás de esto, ¡puede usar Luminatics para hacer que sus bombas sean cien veces más poderosas!",
  ui_story_5043_50431201_131_dialog_content = "¡Si tiene éxito, Schwab podría poner patas arriba a toda nuestra sociedad tal como la conocemos!",
  ui_story_5043_50431201_132_dialog_content = "Todo Lumopolis podría incluso caer bajo su control...",
  ui_story_5043_50431201_133_dialog_content = "¡¿E-Es realmente tan serio?!",
  ui_story_5043_50431201_134_dialog_content = "<color=#e8d9bb>¡Bang—!</color>",
  ui_story_5043_50431201_135_dialog_content = "Tose, tose.",
  ui_story_5043_50431201_136_dialog_content = "Ah, otro intento fallido.",
  ui_story_5043_50431201_137_dialog_content = "Quien sabia que hacer <color=#FFB400>budín de caramelo</color> puede ser tan dificil?",
  ui_story_5043_50431201_138_dialog_content = "...",
  ui_story_5043_50431201_139_dialog_content = "Entonces, ¿¡¿estás diciendo que se va a apoderar de Lumopolis... con PUDÍN?!?",
  ui_story_5043_50431201_140_dialog_content = "¡¿E-Es algún tipo de idiota?! ¡¿Cómo se las arregla para producir explosiones mientras hornea postres?!",
  ui_story_5043_50431201_141_dialog_content = "Aquí hay una mejor pregunta: ¡¿cómo es posible que ambas conjeturas estén tan completa y completamente equivocadas?!",
  ui_story_5043_50431201_142_dialog_content = "¡Shhh! ¡Vuelve afuera! ¡Escondite rapido!",
  ui_story_5043_50431201_143_dialog_content = "Suspiro... Otra pérdida de tiempo y esfuerzo.",
  ui_story_5043_50431201_144_dialog_content = "¿Quizás es hora de hacer algo más productivo? Ahora, ¿dónde puse la llave del sótano? Ah, aquí está.",
  ui_story_5043_50431201_145_dialog_content = "Debería revisar las cosas por última vez antes del juicio de mañana...",
  ui_story_5043_50431201_146_dialog_content = "Perdóneme, maestro Schwab, pero la cena está lista.",
  ui_story_5043_50431201_147_dialog_content = "¡¿No dejé perfectamente claro que no deseo que me molesten en este momento?!",
  ui_story_5043_50431201_148_dialog_content = "¡P-Perdóname, Maestro! No quise ofender... Pero la comida ya está en la mesa...",
  ui_story_5043_50431201_149_dialog_content = "Ugh... Muy bien, ¡pero que sea la última vez que me interrumpas!",
  ui_story_5043_50431201_150_dialog_content = "Schwab fue a cenar. No creo que podamos seguirlo hasta allí, no con todos esos sirvientes alrededor.",
  ui_story_5043_50431201_151_dialog_content = "¿Escuchaste lo que dijo antes de irse?",
  ui_story_5043_50431201_152_dialog_content = "Déjame adivinar, ¿tiene algo que ver con que sea \"difícil de entender\"?",
  ui_story_5043_50431201_153_dialog_content = "Muy divertido, pero no, mencionó algo sobre una bodega.",
  ui_story_5043_50431201_154_dialog_content = "Usa tu cerebro por una vez, ¿quieres? Justo antes de que lo llamaran a cenar, sacó una llave del sótano de la mansión.",
  ui_story_5043_50431201_155_dialog_content = "¡Y mira! ¡Dejó esa llave en la cerradura de allí!",
  ui_story_5043_50431201_156_dialog_content = "¿Vamos a mirar por dentro? ¡Quién sabe qué secretos encontraremos más allá de esa puerta!",
  ui_story_5043_50431201_157_dialog_content = "Parece la oportunidad perfecta y todo eso, pero...",
  ui_story_5043_50431201_158_dialog_content = "¡Aún no hemos encontrado nada que nos ayude a probar la inocencia de Tina! No sé si irrumpir en el sótano de Schwab es la idea correcta.",
  ui_story_5043_50431201_159_dialog_content = "Si de verdad crees que es inocente, entonces la verdad tiene que estar aquí, en la casa de Schwab, en alguna parte.",
  ui_story_5043_50431201_160_dialog_content = "Incluso si él es solo un peón en todo esto, debe haber algún tipo de pista.",
  ui_story_5043_50431201_161_dialog_content = "¡Si aún no lo hemos encontrado, es porque no hemos cavado lo suficientemente profundo!",
  ui_story_5043_50431201_162_dialog_content = "... Tienes razón. Ya no hay vuelta atrás... ¡Así que vamos a ver qué hay en ese sótano!",
  ui_story_5043_50431201_163_dialog_content = "<color=#e8d9bb>Crujido—</color>",
  ui_story_5043_50431201_164_dialog_content = "Está negro como la brea ahí dentro... ¡No puedo ver nada!",
  ui_story_5043_50431201_165_dialog_content = "Parece que hay una escalera que conduce más abajo. Podemos intentar sentir nuestro camino a seguir...",
  ui_story_5043_50431201_166_dialog_content = "Tina? Tina! ¿Estás aquí?",
  ui_story_5043_50431201_167_dialog_content = "Espera... pensé PlayerName tenía algunos poderes psíquicos?",
  ui_story_5043_50431201_168_dialog_content = "¿Puedes usarlos para sentir lo que está por venir?",
  ui_story_5043_50431201_169_dialog_content = "Puedo intentarlo, sí.",
  ui_story_5043_50431201_170_option_content = "¡Potencia de fuerza!",
  ui_story_5043_50431201_171_dialog_content = "Tener un Caelestite al lado puede resultar bastante útil a veces, ¿no?",
  ui_story_5043_50431201_172_dialog_content = "¿Bien? ¿Que ves?",
  ui_story_5043_50431201_173_dialog_content = "¿Hay alguna fuente de luz que podamos usar, como velas o una antorcha?",
  ui_story_5043_50431201_174_dialog_content = "Esta bodega parece descender muy lejos...",
  ui_story_5043_50431201_175_dialog_content = "... ¿Eh? ¡Algo se dirige hacia nosotros!",
  ui_story_5043_50431201_176_dialog_content = "Es eso...",
  ui_story_5043_50431201_177_dialog_content = "Graaaaah—",
  ui_story_5043_50431201_178_dialog_content = "Wahhhhhhhh—",
  ui_story_5043_50431201_179_dialog_content = "¿Qué es? ¡¿Qué viste?!",
  ui_story_5043_50431201_180_dialog_content = "¡R-Corre! ¡Vuelve a la entrada!",
  ui_story_5043_50431201_181_dialog_content = "¡Una multitud de Eclipsites está cargando hacia nosotros!",
  ui_story_5043_50431202_1_dialog_content = "Graah...",
  ui_story_5043_50431202_2_dialog_content = "¿Eclipsitos? ¡¿Qué hacen estas sucias criaturas en el sótano de Schwab?!",
  ui_story_5043_50431202_3_dialog_content = "¡Aparentemente, a los nobles les gustan más que las cosas buenas de la vida!",
  ui_story_5043_50431202_4_dialog_content = "¡No nos mezcles a todos con tus viles calumnias! ¡Quiero que sepas que mi familia nunca albergaría monstruos tan repugnantes en nuestra casa!",
  ui_story_5043_50431202_5_dialog_content = "¡Basta, chicos! ¡Se están acercando!",
  ui_story_5043_50431202_6_dialog_content = "¡Me detendré en los Eclipsites! ¡Salgan de aquí lo más rápido que puedan!",
  ui_story_5043_50431202_7_dialog_content = "A-¿Estás seguro?",
  ui_story_5043_50431202_8_dialog_content = "¡Claro que soy yo! ¡No subestimes a un juez de Lumopolis!",
  ui_story_5043_50431202_9_dialog_content = "Muy bien, escoria de Eclipsite... ¡Toma esto!",
  ui_story_5043_50431202_10_dialog_content = "<color=#e8d9bb>Chocar-!</color>",
  ui_story_5043_50431202_11_dialog_content = "¡Oh querido! ¡Acabas de romper su candelabro!",
  ui_story_5043_50431202_12_dialog_content = "¿Parece estar hecho de cristales de Northland? Lo que significa que era un accesorio bastante caro.",
  ui_story_5043_50431202_13_dialog_content = "¡Vaya! ¿Crees que me pedirán que pague por ello...?",
  ui_story_5043_50431202_14_dialog_content = "¿Estás preocupado por el dinero en un momento como este? ¡Concéntrate en los eclipses!",
  ui_story_5043_50431202_15_dialog_content = "Aquí vienen de nuevo...",
  ui_story_5043_50431202_16_dialog_content = "<color=#e8d9bb>Chocar-!</color>",
  ui_story_5043_50431202_17_dialog_content = "¡Excelente! ¡Ahora su mesa de té también está arruinada!",
  ui_story_5043_50431202_18_dialog_content = "Y a juzgar por su exquisita artesanía, estoy seguro de que Schwab también perderá el sueño.",
  ui_story_5043_50431202_19_dialog_content = "¡Realmente lo siento! Pero no creo que sea yo quien pague, ya que es culpa de los Eclipsites en primer lugar...",
  ui_story_5043_50431202_20_dialog_content = "¡Ahora no es el momento, ustedes dos! ¡Mira, ahí está la puerta!",
  ui_story_5043_50431202_21_dialog_content = "¡Tenemos que irnos ahora mismo!",
  ui_story_5043_50431202_22_dialog_content = "<color=#e8d9bb>Diez minutos tarde...</color>",
  ui_story_5043_50431202_23_dialog_content = "Hemos buscado en todo el perímetro de la propiedad, maestro Schwab... pero todavía no hay señales de intrusos.",
  ui_story_5043_50431202_24_dialog_content = "Qué lío... ¿Quién o qué pudo haber causado todo esto?",
  ui_story_5043_50431202_25_dialog_content = "... ¿Está seguro de que no vio intrusos?",
  ui_story_5043_50431202_26_dialog_content = "Si señor. Todo parece seguro, al menos por el momento.",
  ui_story_5043_50431202_27_dialog_content = "Es muy posible que el culpable o los culpables sean expertos... Si dejaron alguna pista, todavía tenemos que encontrarla.",
  ui_story_5043_50431202_28_dialog_content = "¿Quizás sería mejor... dejar esto en manos del Salón de Justicia?",
  ui_story_5043_50431202_29_dialog_content = "Seguramente, investigarían el asunto con toda la seriedad debida, dado su estado.",
  ui_story_5043_50431202_30_dialog_content = "Una investigación...",
  ui_story_5043_50431202_31_dialog_content = "No, eso no será necesario.",
  ui_story_5043_50431202_32_dialog_content = "Eran simplemente unos pocos muebles después de todo. Lo que se perdió se puede reemplazar fácilmente.",
  ui_story_5043_50431202_33_dialog_content = "Por ahora, pida a alguien que limpie este desastre de inmediato.",
  ui_story_5043_50431202_34_dialog_content = "¡Sí, señor Schwab!",
  ui_story_5043_50431202_35_dialog_content = "(La puerta del sótano está abierta...)",
  ui_story_5043_50431202_36_dialog_content = "(¿Lo desbloqueé antes de irme a cenar?)",
  ui_story_5043_50431202_37_dialog_content = "(Para mí, cometer un error tan tonto... Es casi insondable).",
  ui_story_5043_50431202_38_dialog_content = "(Debería acostarme temprano esta noche. Necesitaré tener la cabeza despejada para el juicio de mañana).",
  ui_story_5043_50431202_39_dialog_content = "Suspiro, ¿qué diablos pasó aquí?",
  ui_story_5043_50431202_40_dialog_content = "¿Qué tipo de villano irrumpe en la casa de alguien solo para destruir su lámpara de araña y su mesa de té?",
  ui_story_5043_50431202_41_dialog_content = "Aún así... estos pedazos rotos podrían obtener un buen precio con el chatarrero adecuado.",
  ui_story_5043_50431202_42_dialog_content = "Huff, huff...",
  ui_story_5043_50431202_43_dialog_content = "(¡Finalmente... finalmente fuera!)",
  ui_story_5043_50431202_44_dialog_content = "¿Alguien logró seguirnos?",
  ui_story_5043_50431202_45_dialog_content = "No me parece. Parece que la costa está despejada.",
  ui_story_5043_50431202_46_dialog_content = "Tsk. Qué vergüenza: un día entero desperdiciado en travesuras sin sentido.",
  ui_story_5043_50431202_47_dialog_content = "Lo peor es que no pudimos encontrar Tina, o incluso la pista más pequeña que podría ayudarla.",
  ui_story_5043_50431202_48_dialog_content = "¿Cómo se supone que va a pasar el juicio ahora?",
  ui_story_5043_50431202_49_dialog_content = "Hemos hecho todo lo que hemos podido... Sólo nos queda cumplir con nuestro deber de jueces.",
  ui_story_5043_50431202_50_dialog_content = "Antes de que comience el juicio, debemos tener en cuenta todo lo que ha sucedido hoy.",
  ui_story_5043_50431202_51_dialog_content = "Es posible que las pistas que estamos buscando estén escondidas en los detalles en alguna parte.",
  ui_story_5043_50431202_52_dialog_content = "No hace falta decir que realizaremos nuestras funciones lo mejor que podamos. Sin embargo...",
  ui_story_5043_50431202_53_dialog_content = "Sin una prueba definitiva, somos tan impotentes como cualquier otra persona para cambiar el resultado del juicio.",
  ui_story_5043_50431202_54_dialog_content = "Sin mencionar que no tenemos idea de qué otros trucos tiene Schwab bajo la manga.",
  ui_story_5043_50431202_55_dialog_content = "Ir a juicio contra él de esta manera sería inútil, por decir lo menos.",
  ui_story_5043_50431202_56_dialog_content = "Hay más de una manera de ganar, Matthieu.",
  ui_story_5043_50431202_57_dialog_content = "Puede que no tengamos todas las cartas que necesitamos en la mano, pero eso no significa que estemos fuera del juego todavía.",
  ui_story_5043_50431202_58_dialog_content = "Vaya, vaya, sintiéndonos tan seguros de nosotros mismos, ¿no es así?",
  ui_story_5043_50431202_59_dialog_content = "No en nosotros mismos, sino en la verdad.",
  ui_story_5043_50431202_60_dialog_content = "El trabajo de un lado es ocultar la verdad, mientras que el del otro es revelarla. Sabiendo eso, tenemos una clara ventaja en el caso.",
  ui_story_5043_50431202_61_dialog_content = "Además, nuestro pequeño viaje a la casa de Schwab no fue del todo infructuoso...",
  ui_story_5043_50431301_1_dialog_content = "<color=#e8d9bb>El día siguiente</color>",
  ui_story_5043_50431301_2_dialog_content = "(Así que finalmente está a punto de comenzar...)",
  ui_story_5043_50431301_3_dialog_content = "(El juicio de Decapitaciones de estatuas en serie comenzará pronto).",
  ui_story_5043_50431301_4_dialog_content = "(Leyn, Matthieu, y Tina... ¿Serán capaces de exponer la verdad ante el tribunal?)",
  ui_story_5043_50431301_5_dialog_content = "¡PlayerName!",
  ui_story_5043_50431301_6_dialog_content = "Carleen! ¡Y Loewe también!",
  ui_story_5043_50431301_7_dialog_content = "¡Regresaste!",
  ui_story_5043_50431301_8_dialog_content = "Por supuesto. Les di a todos mi palabra de que estaría aquí para el juicio, ¿no?",
  ui_story_5043_50431301_9_dialog_content = "Sin embargo, me llamó la atención algo preocupante...",
  ui_story_5043_50431301_10_dialog_content = "Escuche eso Tina es el acusado?",
  ui_story_5043_50431301_11_dialog_content = "Matthieu, realmente te has superado a ti mismo esta vez.",
  ui_story_5043_50431301_12_dialog_content = "¡Te reto a que digas eso otra vez...!",
  ui_story_5043_50431301_13_dialog_content = "E-Así es, sí...",
  ui_story_5043_50431301_14_dialog_content = "Tina fue nombrado el principal sospechoso en el caso después de que salieran a la luz algunas pruebas extrañas.",
  ui_story_5043_50431301_15_dialog_content = "¡Pero estoy seguro de que todo saldrá bien!",
  ui_story_5043_50431301_16_dialog_content = "¿Qué sucedió exactamente en los últimos dos días?",
  ui_story_5043_50431301_17_dialog_content = "Es una especie de larga historia. Te diré más una vez que estemos dentro de la sala del tribunal.",
  ui_story_5043_50431301_18_dialog_content = "<color=#e8d9bb>El Salón de la Justicia, División Romance, Jardines de Lumopolis</color>",
  ui_story_5043_50431301_19_dialog_content = "¡Orden orden!",
  ui_story_5043_50431301_20_dialog_content = "Primero, permítanme disculparme con todos por tener que hacer tantos viajes a la corte para este caso.",
  ui_story_5043_50431301_21_dialog_content = "Desafortunadamente, no pudimos evitar que el culpable cometiera múltiples instancias de este crimen atroz.",
  ui_story_5043_50431301_22_dialog_content = "¡Parece que hoy es el día en que este villano finalmente es llevado ante la justicia!",
  ui_story_5043_50431301_23_dialog_content = "Ahora, sin más preámbulos—",
  ui_story_5043_50431301_24_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5043_50431301_25_dialog_content = "¡El juicio de Decapitaciones de estatuas en serie ya está en sesión!",
  ui_story_5043_50431301_26_dialog_content = "...",
  ui_story_5043_50431301_27_dialog_content = "...",
  ui_story_5043_50431301_28_dialog_content = "<size=30>Ustedes...</size>",
  ui_story_5043_50431301_29_dialog_content = "<size=30>Cree en ellos. Es todo lo que podemos hacer ahora.</size>",
  ui_story_5043_50431301_30_dialog_content = "Primero, ¡presentemos a las partes involucradas en el litigio de hoy!",
  ui_story_5043_50431301_31_dialog_content = "Por la fiscalía, Sr. Byron.",
  ui_story_5043_50431301_32_dialog_content = "Y para la defensa, Tina campbell",
  ui_story_5043_50431301_33_dialog_content = "Nos trae una gran vergüenza ver a uno de nuestros propios jueces de la División de Romance ser juzgado por un crimen tan vil. Pero todos son iguales ante la ley, y todos deben rendir cuentas por sus pecados.",
  ui_story_5043_50431301_34_dialog_content = "Increíble...",
  ui_story_5043_50431301_35_dialog_content = "Yo, Schwab Salar, presidiré como juez principal en el juicio de hoy.",
  ui_story_5043_50431301_36_dialog_content = "jueces Matthieu Sawyer y Leyn se unirá al juicio, así como otros miembros respetados del jurado.",
  ui_story_5043_50431301_37_dialog_content = "Hmph, finalmente has aprendido a mostrar algo de respeto a los mayores.",
  ui_story_5043_50431301_38_dialog_content = "¡Nuestras contribuciones a la investigación son tan importantes como las de cualquier otra persona!",
  ui_story_5043_50431301_39_dialog_content = "Dime, ¿cuáles son tus pensamientos sobre el caso hasta ahora?",
  ui_story_5043_50431301_40_dialog_content = "...",
  ui_story_5043_50431301_41_dialog_content = "...",
  ui_story_5043_50431301_42_dialog_content = "Ah, sí, casi se me olvida que debemos guardar silencio por ahora...",
  ui_story_5043_50431301_43_dialog_content = "Los detalles básicos del caso se describen en los documentos colocados frente a usted. Todos están invitados a revisarlos a su propia discreción.",
  ui_story_5043_50431301_44_dialog_content = "Gracias en gran parte a nuestros minuciosos esfuerzos de investigación, finalmente hemos establecido una clara cadena de eventos.",
  ui_story_5043_50431301_45_dialog_content = "A continuación, haré una breve exposición sobre los resultados de dichas labores investigativas en relación con el caso de las Decapitaciones Seriales de Estatuas.",
  ui_story_5043_50431301_46_dialog_content = "Nuestros hallazgos muestran que el acusado, Tina Campbell, recurrió a la destrucción de estatuas para dar a conocer su profundo resentimiento hacia la ola de amor que barría todo Lumopolis.",
  ui_story_5043_50431301_47_dialog_content = "En los dos incidentes anteriores, ella abusó de su autoridad como jueza para destruir cualquier evidencia que apuntara a su mala conducta.",
  ui_story_5043_50431301_48_dialog_content = "Pero gracias al Sr. Byron y su informe oportuno, el juez Leyn estaba completamente preparado para el tercer y último incidente.",
  ui_story_5043_50431301_49_dialog_content = "Y fue en la escena del crimen, donde pudo obtener una prueba vital del perpetrador...",
  ui_story_5043_50431301_50_dialog_content = "¡Este guante!",
  ui_story_5043_50431301_51_dialog_content = "¡Espléndido! ¡Esto debería ser más que suficiente para incriminar al acusado!",
  ui_story_5043_50431301_52_dialog_content = "En efecto. Inicié una investigación sobre el dueño de este guante, y mis subordinados se toparon con un descubrimiento sorprendente: el otro guante se encontró en el cajón de un escritorio que pertenecía nada menos que al juez Tina campbell!",
  ui_story_5043_50431301_53_dialog_content = "¡Por qué, es una combinación perfecta!",
  ui_story_5043_50431301_54_dialog_content = "Y nuestra investigación lo confirmó. Ambos guantes formaban parte de un conjunto perteneciente a un único propietario...",
  ui_story_5043_50431301_55_dialog_content = "Y ese dueño está hoy ante nosotros, en el asiento del acusado—Tina campbell!",
  ui_story_5043_50431301_56_dialog_content = "No es así...",
  ui_story_5043_50431301_X56_dialog_content = "¡Guau! ¡El juez jefe Schwab es rudo más allá de su edad!",
  ui_story_5043_50431301_57_dialog_content = "¡Con base en la evidencia irrefutable proporcionada, el tribunal propone que el acusado sea acusado de la destrucción de la propiedad pública, así como de la subversión del romance!",
  ui_story_5043_50431301_58_dialog_content = "Naturalmente, eres libre de justificar tu comportamiento abominable como mejor te parezca.",
  ui_story_5043_50431301_59_dialog_content = "Solo sepa que nada menos que la intervención divina convencerá al jurado para que lo absuelva de todos los cargos.",
  ui_story_5043_50431301_60_dialog_content = "Por qué tú...",
  ui_story_5043_50431301_61_dialog_content = "¡Difícilmente creo que eso sea posible!",
  ui_story_5043_50431301_62_dialog_content = "¡La cualidad más importante que tenemos aquí cuando presidimos un caso es la imparcialidad!",
  ui_story_5043_50431301_63_dialog_content = "¿No es así, mis compañeros del jurado?",
  ui_story_5043_50431301_64_dialog_content = "...",
  ui_story_5043_50431301_65_dialog_content = "...",
  ui_story_5043_50431301_66_dialog_content = "No se que mas decir de ese guante...",
  ui_story_5043_50431301_67_dialog_content = "Es cierto que me pertenece, pero nunca lo llevé a la escena del crimen.",
  ui_story_5043_50431301_68_dialog_content = "Estaba luchando contra Eclipsites en ese momento, y no tenía forma de acercarme a esa estatua, y mucho menos desfigurarla.",
  ui_story_5043_50431301_69_dialog_content = "Cuando llegué a la estatua, el daño ya estaba hecho...",
  ui_story_5043_50431301_70_dialog_content = "¿Hay algún testigo que pueda dar fe de eso?",
  ui_story_5043_50431301_71_dialog_content = "Yo...",
  ui_story_5043_50431301_72_dialog_content = "Lo siento, pero me había separado de todos en ese momento, así que no hubo testigos...",
  ui_story_5043_50431301_73_dialog_content = "Entonces parece que su testimonio no puede revocar nuestra conclusión actual.",
  ui_story_5043_50431301_74_dialog_content = "Si no tiene otra evidencia convincente que ofrecer, entonces por los delitos de destrucción de la propiedad pública y subversión del amor, por la presente lo encontramos—",
  ui_story_5043_50431301_75_dialog_content = "<size=45>¡¡¡Esperar!!!</size>",
  ui_story_5043_50431301_76_dialog_content = "... Sí, juez Matthieu?",
  ui_story_5043_50431301_77_dialog_content = "¡Me temo que debo objetar su fallo, juez Schwab!",
  ui_story_5043_50431301_78_dialog_content = "Tina ¡No es posible que sea el culpable de estas decapitaciones en serie de estatuas! ¡Ella tiene pruebas que prueban que nunca estuvo en la escena del crimen!",
  ui_story_5043_50431301_79_dialog_content = "Heh, ella, ahora?",
  ui_story_5043_50431301_80_dialog_content = "Entonces escuchemos lo que tiene que decir, juez Matthieu.",
  ui_story_5043_50431301_81_dialog_content = "Y recuerda ser lo más racional y objetivo posible en su defensa.",
  ui_story_5043_50431301_82_dialog_content = "De lo contrario, podemos encontrar evidencia de cómplices en sus crímenes.",
  ui_story_5043_50431301_83_dialog_content = "Ejem. Volvamos al principio mismo del caso.",
  ui_story_5043_50431301_84_dialog_content = "A saber, el primer incidente de una estatua decapitada.",
  ui_story_5043_50431301_85_dialog_content = "Ya he investigado a fondo las acciones de los culpables ese día.",
  ui_story_5043_50431301_86_dialog_content = "Desafortunadamente, la acusada no puede probar que ella no estuvo en la escena del crimen.",
  ui_story_5043_50431301_87_dialog_content = "No, Su Señoría... ¡Pero lo que más importa es lo que sucedió DESPUÉS de que se cometió el crimen!",
  ui_story_5043_50431301_88_dialog_content = "Esa tarde, Tina y yo estuvimos en el Salón de Justicia, donde trabajamos juntos durante aproximadamente cuatro horas.",
  ui_story_5043_50431301_89_dialog_content = "Puedo dar fe personalmente de ello, al igual que los demás miembros del Salón que estuvieron presentes ese día.",
  ui_story_5043_50431301_90_dialog_content = "Muy bien, trabajaron juntos durante cuatro horas. ¿Entonces que?",
  ui_story_5043_50431301_91_dialog_content = "Fácilmente podría haber perpetrado el crimen antes de volver a trabajar contigo en el Salón de la Justicia.",
  ui_story_5043_50431301_92_dialog_content = "¡Error, señoría! ¡Esas cuatro horas son una prueba positiva de que ella nunca estuvo en la escena del crimen!",
  ui_story_5043_50431301_93_dialog_content = "Verás, Tina sufre de una forma rara de hipersomnia. Cualquier hospital en Lumopolis también puede dar fe de esto.",
  ui_story_5043_50431301_94_dialog_content = "Como resultado, ¡lo más que puede permanecer despierta durante un día determinado es aproximadamente cuatro horas!",
  ui_story_5043_50431301_95_dialog_content = "...",
  ui_story_5043_50431301_96_dialog_content = "En otras palabras, fuera de las cuatro horas que pasamos trabajando juntos, ¡ella tuvo que haber estado dormida el resto del tiempo!",
  ui_story_5043_50431301_97_dialog_content = "Como tal, ¡no hay forma de que ella haya destrozado la primera estatua!",
  ui_story_5043_50431301_98_dialog_content = "¿¡Incluso está durmiendo en el trabajo!?",
  ui_story_5043_50431301_99_dialog_content = "¿No tiene vergüenza? ¿Puede alguien realmente cobrar por no hacer nada en estos días?",
  ui_story_5043_50431301_100_dialog_content = "¡Así es! ¡Yo estaba dormido en ese momento!",
  ui_story_5043_50431301_101_dialog_content = "No me enteré de la estatua hasta que me desperté.",
  ui_story_5043_50431301_102_dialog_content = "¿Bien entonces? ¿Es eso prueba de que ella no tiene la culpa de la primera estatua?",
  ui_story_5043_50431301_103_dialog_content = "¿Llamas a eso un argumento?",
  ui_story_5043_50431301_104_dialog_content = "¡Usar la mera especulación no solo para establecer una coartada para el acusado, sino también para emitir un juicio sobre todo su juicio!",
  ui_story_5043_50431301_105_dialog_content = "¡Si nuestro sistema de justicia fuera tan frívolo, no tendríamos necesidad de cosas como pruebas o testimonios!",
  ui_story_5043_50431301_106_dialog_content = "¡Entiendo, Su Señoría! Desea ver pruebas, ¿sí?",
  ui_story_5043_50431301_107_dialog_content = "Entonces permítanme pasar al segundo caso de decapitación de estatuas.",
  ui_story_5043_50431301_108_dialog_content = "Al igual que el primer incidente, aquí hay suficiente evidencia que prueba Tina Campbell no estaba en la escena del crimen.",
  ui_story_5043_50431301_109_dialog_content = "Por esto, juez Leyn y ambos puedo servir como testigos.",
  ui_story_5043_50431301_110_dialog_content = "¡Hmph! ¿Está seguro de que quiso decir testigos y no cómplices, juez? Matthieu?",
  ui_story_5043_50431301_111_dialog_content = "Vaya, vaya, como respetados jueces del Salón de Justicia, ¿no estamos todos del mismo lado, Su Señoría?",
  ui_story_5043_50431301_112_dialog_content = "Ah, pero no importa... Hay otra persona aquí hoy que también puede servir como testigo.",
  ui_story_5043_50431301_113_dialog_content = "Y creo que alguien en su posición sería más que suficiente para probar la inocencia de Tina.",
  ui_story_5043_50431301_114_dialog_content = "A menos, por supuesto, que quieras dar a entender que la princesa de Lumopolis también es cómplice de este crimen.",
  ui_story_5043_50431301_115_dialog_content = "...",
  ui_story_5043_50431301_116_dialog_content = "... ¿Su?",
  ui_story_5043_50431301_117_dialog_content = "En el momento del segundo incidente, todos estábamos en Meadow Square del Lumopolis Courtyard, respondiendo a una crisis.",
  ui_story_5043_50431301_118_dialog_content = "Veo lo que estás diciendo. Pero primero tenemos que restaurar el orden.",
  ui_story_5043_50431301_119_dialog_content = "Por favor, no se asuste. ¡Sígueme!",
  ui_story_5043_50431301_120_dialog_content = "<color=#e8d9bb>Aplastar-!</color>",
  ui_story_5043_50431301_121_dialog_content = "(¡¿Que fue ese ruido?!)",
  ui_story_5043_50431301_122_dialog_content = "Fui el primero en escuchar el sonido de la estatua siendo destruida. Poco tiempo después, el juez Tina y fui a investigar.",
  ui_story_5043_50431301_123_dialog_content = "Al llegar a la escena del crimen, ambos descubrimos que a la estatua le faltaba la cabeza.",
  ui_story_5043_50431301_124_dialog_content = "En ningún momento en el curso de los acontecimientos de ese día el juez Tina nunca dejar mi vista. Como tal, puedo atestiguar, con total certeza, que ella no estaba en la escena del crimen cuando la segunda estatua fue decapitada.",
  ui_story_5043_50431301_125_dialog_content = "yo creo señora Carleen y la monja puede corroborar esto.",
  ui_story_5043_50431301_126_dialog_content = "Es cierto. Antes del incidente, Tina estuvo con nosotros todo el tiempo.",
  ui_story_5043_50431301_127_dialog_content = "Ella no tenía manera de llevar a cabo el crimen.",
  ui_story_5043_50431301_128_dialog_content = "En efecto. Yo también puedo ser testigo de la falta de participación de la jueza Tina en el crimen.",
  ui_story_5043_50431301_129_dialog_content = "Bueno, su señoría?",
  ui_story_5043_50431301_130_dialog_content = "¿Son estos testimonios evidencia suficiente para usted?",
  ui_story_5043_50431301_131_dialog_content = "Bien, bien.",
  ui_story_5043_50431301_132_dialog_content = "El tribunal respeta y reconoce cualquier testimonio dado por Lady Carleen.",
  ui_story_5043_50431301_133_dialog_content = "Además, sus palabras y su pasión me han afectado, juez Matthieu.",
  ui_story_5043_50431301_134_dialog_content = "Parece que me equivoqué al acusar a la señorita Tina Campbell, después de todo.",
  ui_story_5043_50431301_135_dialog_content = "(¿A-acabamos de ganar?)",
  ui_story_5043_50431301_136_dialog_content = "¡El tribunal se retracta de su sentencia anterior! Encontramos que el acusado, Tina Campbell, no es el perpetrador detrás de las decapitaciones de estatuas en serie.",
  ui_story_5043_50431301_137_dialog_content = "Sin embargo, la encontramos culpable de la <color=#FFB400>tercera instancia</color> de la decapitación de una estatua!",
  ui_story_5043_50431301_138_dialog_content = "¿eh...?",
  ui_story_5043_50431301_139_dialog_content = "Tch.",
  ui_story_5043_50431301_140_dialog_content = "Siéntete orgulloso de tus esfuerzos, juez. Matthieu! Sin ellos, la sentencia del acusado se reducirá considerablemente.",
  ui_story_5043_50431301_141_dialog_content = "¡Sin embargo! Siempre y cuando la pieza crucial de evidencia provista anteriormente permanezca indiscutible...",
  ui_story_5043_50431301_142_dialog_content = "... el tribunal aún encontrará Tina ¡Campbell culpable de destruir la propiedad pública, así como de subvertir el romance!",
  ui_story_5043_50431301_143_dialog_content = "Pero ya lo sabía, ¿no es así, juez? Matthieu?",
  ui_story_5043_50431301_144_dialog_content = "Completa tontería...",
  ui_story_5043_50431301_145_dialog_content = "Dicho esto, ¿todavía desea continuar negando la evidencia irrefutable presentada ante el tribunal hoy?",
  ui_story_5043_50431301_146_dialog_content = "...",
  ui_story_5043_50431301_147_dialog_content = "<size=30>Cuelga ahí, Matthieu...</size>",
  ui_story_5043_50431301_148_dialog_content = "<size=30>Todavía no es suficiente...</size>",
  ui_story_5043_50431301_149_dialog_content = "No, Su Señoría. He dicho todo lo que necesitaba decir.",
  ui_story_5043_50431301_150_dialog_content = "¿Qué...?",
  ui_story_5043_50431301_151_dialog_content = "Jejeje, ¿es así?",
  ui_story_5043_50431301_152_dialog_content = "Sí, Su Señoría.",
  ui_story_5043_50431301_153_dialog_content = "En ese caso, el tribunal por la presente—",
  ui_story_5043_50431301_154_dialog_content = "Es tu turno, Leyn.",
  ui_story_5043_50431301_155_dialog_content = "!",
  ui_story_5043_50431301_156_dialog_content = "Leyn?",
  ui_story_5043_50431301_157_dialog_content = "Adelante, entonces. A los recién llegados rara vez se les presentan oportunidades como esta.",
  ui_story_5043_50431301_158_dialog_content = "Entendido.",
  ui_story_5043_50431301_159_dialog_content = "El juez presidente Schwab, los miembros del jurado y todos los que están aquí reunidos hoy.",
  ui_story_5043_50431301_160_dialog_content = "Humildemente solicito unos minutos de su tiempo.",
  ui_story_5043_50431301_161_dialog_content = "para que podamos <color=#FFB400>sacar inferencias</color> de nuestra comprensión del delito.",
  ui_story_5043_50431301_162_dialog_content = "Eh, este chico está un poco loco.",
  ui_story_5043_50431301_163_dialog_content = "Haría bien en elegir sabiamente sus palabras, juez. Leyn. Especialmente considerando tu pasado \"humilde\".",
  ui_story_5043_50431301_164_dialog_content = "A diferencia del juez Matthieu, no cuentas con el apoyo de una familia noble en caso de que se cuestione la calidad de tu trabajo.",
  ui_story_5043_50431301_165_dialog_content = "Y a diferencia de usted, juez presidente Schwab, no creo que mis antecedentes comunes sean necesariamente un obstáculo.",
  ui_story_5043_50431301_166_dialog_content = "Por lo menos, mis acciones no tienen forma de reflejar innoblemente sobre la ilustre casta noble.",
  ui_story_5043_50431301_167_dialog_content = "Tú...",
  ui_story_5043_50431301_168_dialog_content = "Pero volvamos al caso que nos ocupa, ¿de acuerdo? Su Señoría parece ser bastante insistente en esa pieza de evidencia crucial...",
  ui_story_5043_50431301_169_dialog_content = "Sugiero que realicemos una revisión aún más detallada de este caso y no dejemos piedra sin remover.",
  ui_story_5043_50431301_170_dialog_content = "Al examinar de cerca cada detalle, creo que encontraremos algún rastro del verdadero culpable, ¡algo que nos señalará la dirección de la verdad!",
  ui_story_5043_50431301_171_dialog_content = "¡Oh! ¡Qué profesional! ¡Me gusta cómo van las cosas!",
  ui_story_5043_50431301_172_dialog_content = "(Algún rastro del verdadero culpable, eh...)",
  ui_story_5043_50431301_173_dialog_content = "(¿Finalmente descubriste algo, Leyn?)",
  ui_story_5043_50431301_174_dialog_content = "Recordemos lo que sucedió ayer en Stairway to the Skies, justo antes del incidente.",
  ui_story_5043_50431301_175_dialog_content = "Para proteger la estatua en la parte superior de las escaleras, intentamos detener el desfile.",
  ui_story_5043_50431301_176_dialog_content = "Para nuestra sorpresa, encontramos un grupo de pequeños Eclipsites acechando justo detrás de la procesión.",
  ui_story_5043_50431301_177_dialog_content = "Inmediatamente los enfrenté en la batalla. No mucho después, el juez Tina me atrapó...",
  ui_story_5043_50431302_1_dialog_content = "Pateé el primer Eclipsite por las escaleras.",
  ui_story_5043_50431302_2_dialog_content = "El segundo, lo empalé con mi arma.",
  ui_story_5043_50431302_3_dialog_content = "El último, sin embargo, fue volado en pedazos por el puño de Tina.",
  ui_story_5043_50431302_4_dialog_content = "¡Bien bien! ¿Son realmente necesarios esos detalles?",
  ui_story_5043_50431302_5_dialog_content = "Con el pequeño grupo de Eclipsites derrotado, Tina y comencé a hacer nuestro camino de regreso a la estatua y reunirme con los demás.",
  ui_story_5043_50431302_6_dialog_content = "Pero las multitudes eran espesas ese día, y atravesarlas resultó ser una tarea difícil.",
  ui_story_5043_50431302_7_dialog_content = "Como resultado, me separaron de Tina en la multitud... No fue hasta después del incidente que finalmente la volví a ver.",
  ui_story_5043_50431302_8_dialog_content = "Tratar de atravesar a toda esa gente fue una pesadilla... ¡Apenas podía moverme la mitad del tiempo!",
  ui_story_5043_50431302_9_dialog_content = "En eso podemos estar de acuerdo.",
  ui_story_5043_50431302_10_dialog_content = "Pero esto no prueba que Tina Campbell no estuvo en la escena del crimen ese día.",
  ui_story_5043_50431302_11_dialog_content = "Dejemos eso a un lado por un momento, Su Señoría. En cambio, dirijamos nuestra atención al momento en que ocurrió el incidente.",
  ui_story_5043_50431302_12_dialog_content = "Cuando finalmente llegué a la estatua, fui emboscado por otro grupo de Eclipsites.",
  ui_story_5043_50431302_13_dialog_content = "Mientras luchábamos contra los Eclipsites, el culpable tuvo una oportunidad perfecta para atacar.",
  ui_story_5043_50431302_14_dialog_content = "Aprovechando el caos que los rodeaba, extendieron una mano enguantada y destrozaron la cabeza de la estatua.",
  ui_story_5043_50431302_15_dialog_content = "Logré agarrarlos de la mano, pero el culpable se escondía entre los Eclipsites, lo que me impedía ver claramente su rostro o su cuerpo.",
  ui_story_5043_50431302_16_dialog_content = "Al final, el culpable pudo escabullirse de mi agarre y escapar, dejando atrás un solo guante...",
  ui_story_5043_50431302_17_dialog_content = "El guante que se ha aportado como prueba clave en el caso, sí.",
  ui_story_5043_50431302_18_dialog_content = "Dama Carleen y juez Matthieu poco después, hizo un trabajo breve con los Eclipsites, pero el culpable no estaba a la vista.",
  ui_story_5043_50431302_19_dialog_content = "Una vez que el polvo se asentó, el juez Tina finalmente reapareció y se unió a nosotros.",
  ui_story_5043_50431302_20_dialog_content = "Y eso, damas y caballeros de la corte, es el relato completo de los eventos que rodearon la decapitación de la estatua.",
  ui_story_5043_50431302_21_dialog_content = "Y una cuenta muy bien redactada, además. Gracias por su aporte, juez. Leyn.",
  ui_story_5043_50431302_22_dialog_content = "Con esto en mente, es lógico que el dueño del guante sea el perpetrador del crimen.",
  ui_story_5043_50431302_23_dialog_content = "Esa, a su vez, fue la razón que nos llevó a arrestar al acusado, Tina campbell",
  ui_story_5043_50431302_24_dialog_content = "Perdóneme, Su Señoría... Pero está sacando conclusiones precipitadas.",
  ui_story_5043_50431302_25_dialog_content = "¿Te ruego me disculpes?",
  ui_story_5043_50431302_26_dialog_content = "Basado en la información que reunimos en la escena del crimen sobre el culpable—",
  ui_story_5043_50431302_27_dialog_content = "Sabemos que el culpable logró aplastar la cabeza de la estatua con su mano desnuda mientras usaba ese guante.",
  ui_story_5043_50431302_28_dialog_content = "La persona que detuviste, por otro lado...",
  ui_story_5043_50431302_29_dialog_content = "Es solo la joven que es la dueña legítima del guante.",
  ui_story_5043_50431302_30_dialog_content = "Si compara los dos más de cerca, encontrará más inconsistencias que cualquier otra cosa.",
  ui_story_5043_50431302_31_dialog_content = "Siento que está pensando demasiado en las cosas, juez. Leyn.",
  ui_story_5043_50431302_32_dialog_content = "¿No es lógico que el propietario del guante sea la persona que probablemente lo haya usado en la escena del crimen?",
  ui_story_5043_50431302_33_dialog_content = "Lo hace, Su Señoría... Pero no entiende el punto.",
  ui_story_5043_50431302_34_dialog_content = "Juzga Tina parece que puede pulverizar la cabeza de una estatua con sus propias manos?",
  ui_story_5043_50431302_35_dialog_content = "¿Oh? ¿Un nuevo ángulo?",
  ui_story_5043_50431302_36_dialog_content = "Cuando realmente lo piensas, ¿cómo podría una niña pequeña romper una estatua con sus propias manos?",
  ui_story_5043_50431302_37_dialog_content = "Parece que se ha perdido en sus propios procesos de pensamiento, juez. Leyn.",
  ui_story_5043_50431302_38_dialog_content = "¿Ya olvidaste lo que dijiste hace no dos minutos?",
  ui_story_5043_50431302_39_dialog_content = "Pateé el primer Eclipsite por las escaleras.",
  ui_story_5043_50431302_40_dialog_content = "El segundo, lo empalé con mi arma.",
  ui_story_5043_50431302_41_dialog_content = "El último, sin embargo, fue <color=#FFB400>volado en pedazos por el puño de Tina</color>.",
  ui_story_5043_50431302_42_dialog_content = "Seguramente, conoces a tu colega mejor que eso. Después de todo, ella es la heredera de la Mano Divina de la Familia Campbell.",
  ui_story_5043_50431302_43_dialog_content = "Para alguien que puede destruir por completo un Eclipsite con un solo golpe, la cabeza de una estatua no debería representar ningún problema.",
  ui_story_5043_50431302_44_dialog_content = "¡Así es! ¡Ella no es una chica ordinaria!",
  ui_story_5043_50431302_45_dialog_content = "Joven, necesita pensar un poco más en sus deducciones.",
  ui_story_5043_50431302_46_dialog_content = "(Supongo que no alcanzó la marca, ¿eh?)",
  ui_story_5043_50431302_47_dialog_content = "(Si solo Leyn fue capaz de dar solo un pequeño paso por delante del enemigo, y encontrar algo que pasó desapercibido...)",
  ui_story_5043_50431302_48_dialog_content = "Ah, sí... Tina heredó la Mano Divina.",
  ui_story_5043_50431302_49_dialog_content = "Entonces se supone que lo usó para aplastar la cabeza de la estatua, ¿correcto?",
  ui_story_5043_50431302_50_dialog_content = "Correcto. Es la única conclusión lógica después de todo.",
  ui_story_5043_50431302_51_dialog_content = "Y aunque debo aplaudirle por su riguroso método de análisis, juez Leyn...",
  ui_story_5043_50431302_52_dialog_content = "Para juicios futuros, le sugiero que comparta sus análisis conmigo antes del inicio de nuestros procedimientos en lugar de perder el valioso tiempo de la corte.",
  ui_story_5043_50431302_53_dialog_content = "No creo haberle hecho perder el tiempo a nadie, Su Señoría.",
  ui_story_5043_50431302_54_dialog_content = "Todas mis inferencias fueron con el único propósito de llegar a esta misma conclusión.",
  ui_story_5043_50431302_55_dialog_content = "A saber, Tina usó la Mano Divina para aplastar la cabeza de la estatua.",
  ui_story_5043_50431302_56_dialog_content = "... Vaya al grano, juez Leyn. ¿Qué es lo que estás tratando de decir?",
  ui_story_5043_50431302_57_dialog_content = "Ahora que hemos llegado a esta conclusión, todo lo que tenemos que hacer es mirar hacia atrás una vez más para darnos cuenta de la verdad.",
  ui_story_5043_50431302_58_dialog_content = "¡Ese guante, esa prueba crucial, no es una prueba irrefutable de su culpabilidad, sino de su inocencia!",
  ui_story_5043_50431302_59_dialog_content = "¡¿Qué?!",
  ui_story_5043_50431302_60_dialog_content = "¡Su Señoría, permítame mostrarles a todos en la corte el guante del perpetrador!",
  ui_story_5043_50431302_61_dialog_content = "Es posible que el guante haya sido eliminado de cualquier evidencia incriminatoria mientras estaba en su posesión, Su Señoría...",
  ui_story_5043_50431302_62_dialog_content = "Pero no importa, mientras siga siendo el mismo guante de la escena del crimen. Podemos estar seguros de eso, ¿verdad, Su Señoría?",
  ui_story_5043_50431302_63_dialog_content = "¿Estás cuestionando mi capacidad para preservar las pruebas del caso, una de las responsabilidades más fundamentales de la Sala de Justicia?",
  ui_story_5043_50431302_64_dialog_content = "Contento de escuchar.",
  ui_story_5043_50431302_65_dialog_content = "Les pido a todos que miren bien este guante.",
  ui_story_5043_50431302_66_dialog_content = "Es un guante para diestros, ¿no?",
  ui_story_5043_50431302_67_dialog_content = "Basta, juez Leyn. ¡Llegar al punto!",
  ui_story_5043_50431302_68_dialog_content = "¿Qué diferencia hace en qué mano va?",
  ui_story_5043_50431302_69_dialog_content = "!",
  ui_story_5043_50431302_70_dialog_content = "¿Ah?",
  ui_story_5043_50431302_71_dialog_content = "¡Ah—!",
  ui_story_5043_50431302_72_dialog_content = "¡La mano derecha! ¡Eso lo explica todo!",
  ui_story_5043_50431302_73_dialog_content = "¡Espera, no lo entiendo! ¡¿Qué está sucediendo?!",
  ui_story_5043_50431302_74_dialog_content = "Parece que usted también se ha dado cuenta, Su Señoría.",
  ui_story_5043_50431302_75_dialog_content = "Sólo hay un único error fatal en su conclusión...",
  ui_story_5043_50431302_76_dialog_content = "La Mano Divina de Tina, que de hecho es capaz de destruir la cabeza de una estatua, requiere el uso de su <color=#FFB400>mano izquierda</color>.",
  ui_story_5043_50431302_77_dialog_content = "Sin embargo, este guante es un <color=#FFB400>diestro</color> ¡guante!",
  ui_story_5043_50431302_78_dialog_content = "¡Oh! ¡¡¡Ahora lo entiendo!!!",
  ui_story_5043_50431302_79_dialog_content = "Izquierda derecha...",
  ui_story_5043_50431302_80_dialog_content = "Después de pasar todo el juicio enfatizando la importancia de esta prueba crucial.",
  ui_story_5043_50431302_81_dialog_content = "Creo que todos podemos estar seguros de estar de acuerdo con usted ahora, Su Señoría.",
  ui_story_5043_50431302_82_dialog_content = "Ahora que sabemos que este no es el guante que cubre la Mano Divina de Tina, me pregunto qué tipo de conclusión se sacará.",
  ui_story_5043_50431302_83_dialog_content = "Bueno, su señoría? ¿Serías tan amable de honrar a la corte con tus pensamientos?",
  ui_story_5043_50431302_84_dialog_content = "¡Tú... Tú...!",
  ui_story_5043_50431302_85_dialog_content = "Camino a seguir, Leyn! Las mismas pruebas utilizadas para incriminar Tina también demuestra su inocencia!",
  ui_story_5043_50431302_86_dialog_content = "¡Parece que la balanza finalmente se está inclinando a nuestro favor!",
  ui_story_5043_50431302_87_dialog_content = "Es increíble...",
  ui_story_5043_50431302_88_dialog_content = "Muy bien entonces. No tengo más remedio que reconocer y aceptar su refutación.",
  ui_story_5043_50431302_89_dialog_content = "Debido a la insuficiencia de pruebas en este momento, el tribunal no puede encontrar al acusado culpable de los delitos antes mencionados.",
  ui_story_5043_50431302_90_dialog_content = "Por lo tanto, el verdadero decapitador de estatuas sigue prófugo.",
  ui_story_5043_50431302_91_dialog_content = "¡¡¡Esto es genial!!!",
  ui_story_5043_50431302_92_dialog_content = "Ellos lo hicieron, Carleen! ¡Realmente lo lograron!",
  ui_story_5043_50431302_93_dialog_content = "¡En efecto! ¡Esto es maravilloso!",
  ui_story_5043_50431302_94_dialog_content = "¡Ser testigo de la preservación de la justicia en el Salón de Justicia ha sido un gran honor!",
  ui_story_5043_50431302_95_dialog_content = "Así que si el perpetrador sigue prófugo...",
  ui_story_5043_50431302_96_dialog_content = "¿Eso significa que soy inocente?",
  ui_story_5043_50431302_97_dialog_content = "Por supuesto, Tina. Siempre fuiste inocente.",
  ui_story_5043_50431302_98_dialog_content = "Tienes una gran deuda de gratitud con nosotros, ¿sabes? Especialmente a nuestro plebeyo novato.",
  ui_story_5043_50431302_99_dialog_content = "Para su primer caso importante, lo hizo notablemente bien.",
  ui_story_5043_50431302_100_dialog_content = "¡No podría estar mas de acuerdo! ¡Muchas gracias a los dos por todo lo que habéis hecho por mí!",
  ui_story_5043_50431302_101_dialog_content = "¡Estoy orgulloso de llamarlos mis queridos colegas!",
  ui_story_5043_50431302_102_dialog_content = "¡Ey! ¡¿Qué se supone que significa esto?!",
  ui_story_5043_50431302_103_dialog_content = "Después de perder medio día debatiéndonos hasta dejarnos roncos, ¿quieres decirme que te equivocaste de persona?",
  ui_story_5043_50431302_104_dialog_content = "...",
  ui_story_5043_50431302_105_dialog_content = "Increíble. ¡Simplemente increíble!",
  ui_story_5043_50431302_106_dialog_content = "¿Obligarme a sentarme durante toda esa deliberación, solo para decir que estamos justo donde empezamos?",
  ui_story_5043_50431302_107_dialog_content = "¡Te dije muchas cosas antes! ¡Mi paciencia está al límite!",
  ui_story_5043_50431302_108_dialog_content = "¡¡¡Si no cierra este caso para el final del día, cerraré toda esta División de Romance de los tribunales!!!",
  ui_story_5043_50431302_109_dialog_content = "No nos apresuremos, mi buen señor. Tal como está, solo hemos discutido la mitad del asunto.",
  ui_story_5043_50431302_110_dialog_content = "Medio...?",
  ui_story_5043_50431302_111_dialog_content = "Tome asiento aquí con nosotros, juez Tina.",
  ui_story_5043_50431302_112_dialog_content = "Es hora de que alguien más actúe como acusado ahora.",
  ui_story_5043_50431302_113_dialog_content = "¿Eh? A quién te refieres...?",
  ui_story_5043_50431302_114_dialog_content = "Después de la investigación exhaustiva del caso por parte de la División de Romance y de todas las pruebas proporcionadas, yo, el juez Leyn—",
  ui_story_5043_50431302_115_dialog_content = "Y yo, juez Matthieu—",
  ui_story_5043_50431302_116_dialog_content = "¡Acusar al señor Schwab Salar de los delitos de destrucción de bienes públicos y subversión del amor!",
  ui_story_5043_50431302_117_dialog_content = "Juez presidente Schwab, por favor suba al estrado.",
  ui_story_5043_50431302_118_dialog_content = "¿Qué? ¿Está acusando a Schwab?",
  ui_story_5043_50431302_119_dialog_content = "No me digas que esto también es parte del plan, PlayerName?!",
  ui_story_5043_50431302_120_dialog_content = "Oh...",
  ui_story_5043_50431302_121_dialog_content = "Bueno, ayer teníamos nuestras sospechas sobre Schwab, pero...",
  ui_story_5043_50431302_122_dialog_content = "No sabía que en realidad lo iban a acusar de algo...",
  ui_story_5043_50431302_123_dialog_content = "¿Conseguisteis tú y los demás encontrar pruebas incriminatorias?",
  ui_story_5043_50431302_124_dialog_content = "Para nada...",
  ui_story_5043_50431302_125_dialog_content = "Acusándome, ¿verdad?",
  ui_story_5043_50431302_126_dialog_content = "¿Tiene alguna idea de lo que está haciendo, juez? Leyn?",
  ui_story_5043_50431302_127_dialog_content = "Sólo estoy cumpliendo con mi deber, señor.",
  ui_story_5043_50431302_128_dialog_content = "Hmph. Será mejor que lo esperes.",
  ui_story_5043_50431302_129_dialog_content = "Porque puedo decirle ahora que tengo una coartada incuestionable para cada uno de los tres incidentes.",
  ui_story_5043_50431302_130_dialog_content = "Dondequiera que lleve esta tonta investigación, sepa que todo el Salón de Justicia corroborará mi historia.",
  ui_story_5043_50431302_131_dialog_content = "No tengo nada más que decir sobre tus ilógicas acusaciones por ahora.",
  ui_story_5043_50431302_132_dialog_content = "Tenga la seguridad, juez Schwab, que mi investigación será breve y sencilla.",
  ui_story_5043_50431302_133_dialog_content = "Yo también puedo dar fe de sus coartadas herméticas para los tres casos de irregularidades en este caso.",
  ui_story_5043_50431302_134_dialog_content = "¿Y aún así te niegas a retirar tu acusación sin sentido?",
  ui_story_5043_50431302_135_dialog_content = "Eso es correcto, señor, porque el culpable no tenía necesidad de estar presente en las escenas del crimen.",
  ui_story_5043_50431302_136_dialog_content = "May ¿Llamo a un nuevo testigo?",
  ui_story_5043_50431302_137_dialog_content = "¿Un testigo?",
  ui_story_5043_50431302_138_dialog_content = "Acérquese al estrado y prepárese para jurar bajo juramento.",
  ui_story_5043_50431302_139_dialog_content = "(¿Cuándo encontró un testigo para esto?)",
  ui_story_5043_50431302_140_dialog_content = "(Me pregunto quién es...)",
  ui_story_5043_50431302_141_dialog_content = "P-puedo...",
  ui_story_5043_50431302_142_dialog_content = "¿Puedo hablar ahora?",
  ui_story_5043_50431302_143_dialog_content = "¡Un eclipse! ¡Y uno que puede hablar, nada menos!",
  ui_story_5043_50431302_144_dialog_content = "T-Toto?!?",
  ui_story_5043_50431302_145_dialog_content = "¿Eh? ¡¿Qué está haciendo aquí?!",
  ui_story_5043_50431302_146_dialog_content = "Tener un Eclipsite como testigo... ¿En qué estaba pensando?",
  ui_story_5043_50431302_147_dialog_content = "¡¿Has perdido la cabeza?! ¡Cómo te atreves a llevar a esa sucia criatura a un tribunal sagrado del Salón de la Justicia!",
  ui_story_5043_50431302_148_dialog_content = "¡¿Buscas socavar todo lo que hemos establecido?!",
  ui_story_5043_50431302_149_dialog_content = "No hay razón para preocuparse. Hemos confirmado, sin duda, que este Eclipsite es perfectamente inofensivo.",
  ui_story_5043_50431302_150_dialog_content = "Aquí nadie está en peligro. Solo está aquí para ayudarnos a descubrir la verdad con su testimonio, nada más.",
  ui_story_5043_50431302_151_dialog_content = "Creo que todos estamos aquí por la misma razón, ¿no?",
  ui_story_5043_50431302_152_dialog_content = "Hmmm... Bueno, si su testimonio promueve el juicio, supongo que es aceptable.",
  ui_story_5043_50431302_153_dialog_content = "Toto se ve aún más delgado que la última vez...",
  ui_story_5043_50431302_154_dialog_content = "Esto probablemente no tenga precedentes en toda la historia del Salón de Justicia... Me pregunto qué tipo de testimonio va a dar.",
  ui_story_5043_50431302_155_dialog_content = "A-Permítame presentarme m-yo mismo.",
  ui_story_5043_50431302_156_dialog_content = "¡P-Por favor, no me tengas miedo!",
  ui_story_5043_50431302_157_dialog_content = "No soy nada más que un Eclipsite promedio de bajo nivel.",
  ui_story_5043_50431302_158_dialog_content = "Accidentalmente me comí un objeto experimental en Gannon City...",
  ui_story_5043_50431302_159_dialog_content = "No tengo ni idea de lo que era, pero...",
  ui_story_5043_50431302_160_dialog_content = "¡Mi cuerpo comenzó a transformarse y, al mismo tiempo, gané cierto nivel de sensibilidad!",
  ui_story_5043_50431302_161_dialog_content = "¡Hmph! ¡Qué típico de la Federación Illumina incursionar en una investigación tan indescriptible!",
  ui_story_5043_50431302_162_dialog_content = "Wow... ¿Su Universese se ha vuelto mucho más suave desde la última vez que hablamos?",
  ui_story_5043_50431302_163_dialog_content = "A partir de ese momento, m-mi conexión con otros eclipses se debilitó...",
  ui_story_5043_50431302_164_dialog_content = "¡Ya no podía controlarlos, pero ellos tampoco podían controlarme a mí!",
  ui_story_5043_50431302_165_dialog_content = "Vivir entre los otros Eclipsites se hizo cada vez más difícil... No había forma de que terminara mi trabajo sin complicaciones constantes...",
  ui_story_5043_50431302_166_dialog_content = "El líder no pudo tolerarlo y finalmente me obligó a irme...",
  ui_story_5043_50431302_167_dialog_content = "Ella dijo, si quieres causar problemas, ve y causa problemas a los aurorianos...",
  ui_story_5043_50431302_168_dialog_content = "Emm, entonces hay Eclipsites que incluso los Eclipsites no pueden soportar.",
  ui_story_5043_50431302_169_dialog_content = "No sientas pena por ello. El enemigo de tu enemigo puede no ser necesariamente tu amigo.",
  ui_story_5043_50431302_170_dialog_content = "No mucho después, comencé a aprender todo lo que pude sobre los aurorianos. Su lengua, sus culturas...",
  ui_story_5043_50431302_171_dialog_content = "Yo viajaba por todo el país, buscando trabajo donde podía. Pero no importaba adónde fuera, me seguían despidiendo...",
  ui_story_5043_50431302_172_dialog_content = "La vida ha sido dura, ¡pero soy mucho más feliz que nunca!",
  ui_story_5043_50431302_173_dialog_content = "Nunca lastimaría a nadie.",
  ui_story_5043_50431302_174_dialog_content = "¡P-Porque me gusta vivir como un auroriano!",
  ui_story_5043_50431302_X174_dialog_content = "¡Ya no quiero que me odien!",
  ui_story_5043_50431302_175_dialog_content = "¡El tiene razón! ¡Toto nunca le haría daño a una mosca!",
  ui_story_5043_50431302_176_dialog_content = "¡Es incluso más dulce que la mayoría de los aurorianos! ¡Por favor, no te sientas amenazado por él!",
  ui_story_5043_50431302_177_dialog_content = "Tsk, Eclipsite que vive como un Aurorian...",
  ui_story_5043_50431302_178_dialog_content = "¡Los tiempos han cambiado, parece!",
  ui_story_5043_50431302_179_dialog_content = "Gracias, Toto. Eso servirá como introducción.",
  ui_story_5043_50431302_180_dialog_content = "Indique al tribunal el motivo por el que ha venido aquí y ha sido testigo en el juicio de hoy.",
  ui_story_5043_50431302_181_dialog_content = "¡Vine a denunciar a un auroriano por comportamiento ilegal!",
  ui_story_5043_50431302_182_dialog_content = "¿Y quién sería?",
  ui_story_5043_50431302_183_dialog_content = "¡Ese hombre allí! El que se sienta por encima de todos los demás. ¡El hombre llamado Schwab!",
  ui_story_5043_50431302_184_dialog_content = "Tú...",
  ui_story_5043_50431302_185_dialog_content = "¿Qué crimen cometió?",
  ui_story_5043_50431302_186_dialog_content = "¡E-Él fue quien rompió las estatuas!",
  ui_story_5043_50431302_187_dialog_content = "Tiene coartadas que prueban que nunca estuvo en la escena del crimen, entonces, ¿qué te hace estar tan seguro de que él fue el culpable?",
  ui_story_5043_50431302_188_dialog_content = "¡Él no necesitaba estar allí para destruirlos! Eso es porque él puede... él puede...",
  ui_story_5043_50431302_189_dialog_content = "El puede que?",
  ui_story_5043_50431302_190_dialog_content = "¡Él puede controlar los eclipses!",
  ui_story_5043_50431401_1_dialog_content = "¿Controlar eclipses?",
  ui_story_5043_50431401_2_dialog_content = "¡Mis cielos! ¿Sabes que tienes alguna idea de lo que estás insinuando?",
  ui_story_5043_50431401_3_dialog_content = "¡Asociarse con Eclipsites es un crimen muy grave aquí en Lumopolis!",
  ui_story_5043_50431401_4_dialog_content = "Tsk! ¡Qué ridículo testimonio!",
  ui_story_5043_50431401_5_dialog_content = "¿De verdad pensaste que podrías acusarme de conspirar con Eclipsites usando el testimonio de uno de su tipo?",
  ui_story_5043_50431401_6_dialog_content = "¡Qué burla a la justicia! ¡El testimonio de un borracho aguantaría más que el de un asqueroso Eclipsite!",
  ui_story_5043_50431401_7_dialog_content = "Cuando se trata de enmarcar a otros, tus habilidades aún son muy escasas, Leyn!",
  ui_story_5043_50431401_8_dialog_content = "¿Es eso así? Entonces, ¿quizás debería sacar una o dos páginas de su libro, juez Schwab?",
  ui_story_5043_50431401_9_dialog_content = "¡Tú!",
  ui_story_5043_50431401_10_dialog_content = "No necesito incriminarte para probar tu culpabilidad.",
  ui_story_5043_50431401_11_dialog_content = "Es como dices, el testimonio de un solo Eclipsite no es suficiente para implicarte en estos crímenes.",
  ui_story_5043_50431401_12_dialog_content = "Pero, ¿y si ese Eclipsite jugara un papel especial en el caso?",
  ui_story_5043_50431401_13_dialog_content = "¿Un papel especial...?",
  ui_story_5043_50431401_14_dialog_content = "Si fueras tan amable, Toto?",
  ui_story_5043_50431401_15_dialog_content = "Lo siento!!!",
  ui_story_5043_50431401_16_dialog_content = "Cometí un error... ¡¡¡Acepto mi castigo, aquí y ahora!!!",
  ui_story_5043_50431401_17_dialog_content = "¿Ah?",
  ui_story_5043_50431401_18_dialog_content = "¿Qué quieres decir, Totó? ¿De qué error estás hablando?",
  ui_story_5043_50431401_19_dialog_content = "Honestamente, en un momento está acusando al juez principal, y al siguiente, está admitiendo su propia culpa...",
  ui_story_5043_50431401_20_dialog_content = "¡Dejen de perder el tiempo y hablen claro, les digo!",
  ui_story_5043_50431401_21_dialog_content = "¡Lo siento! L-La verdad es...",
  ui_story_5043_50431401_22_dialog_content = "¡Fui yo quien destruyó las estatuas!",
  ui_story_5043_50431401_23_dialog_content = "¡¿Qué?!",
  ui_story_5043_50431401_24_dialog_content = "¿eh? ¡¿Así que fuiste tú?!",
  ui_story_5043_50431401_25_dialog_content = "¡¿Tú eres el que destruyó a mi esposa ya mi amante?!",
  ui_story_5043_50431401_26_dialog_content = "Sí, fui yo.",
  ui_story_5043_50431401_27_dialog_content = "¡Por qué, podrida, pequeña...!",
  ui_story_5043_50431401_28_dialog_content = "¡E-Espera! ¡No lo hice a propósito! ¡Me vi obligado!",
  ui_story_5043_50431401_29_dialog_content = "¡Schwab fue quien me obligó a hacerlo cada vez!",
  ui_story_5043_50431401_30_dialog_content = "Por favor todos. Ten piedad de mi-!",
  ui_story_5043_50431401_31_dialog_content = "<size=45>¿¡¿Qué?!?</size>",
  ui_story_5043_50431401_32_dialog_content = "...",
  ui_story_5043_50431401_33_dialog_content = "¿Es esto realmente lo que pasó...?",
  ui_story_5043_50431401_34_dialog_content = "E-Todo comenzó hace unas dos semanas...",
  ui_story_5043_50431401_35_dialog_content = "Acababa de llegar a Lumopolis y me estaba preparando para buscar trabajo.",
  ui_story_5043_50431401_36_dialog_content = "Pero Lumopolis es tan grande, y no conocía muy bien las carreteras... Antes de darme cuenta, ya era de noche.",
  ui_story_5043_50431401_37_dialog_content = "Después de eso, yo... me encontré con un grupo de Eclipsites en Lumopolis Courtyard.",
  ui_story_5043_50431401_38_dialog_content = "Bueno, ha habido múltiples avistamientos de actividad de Eclipsite en la ciudad últimamente.",
  ui_story_5043_50431401_39_dialog_content = "Esto es cierto, al menos.",
  ui_story_5043_50431401_40_dialog_content = "No esperaba encontrar más de mi tipo en la ciudad. Se sintió extraño.",
  ui_story_5043_50431401_41_dialog_content = "Mientras estaba allí tratando de entender las cosas, asumieron que solo era otro Eclipsite perdido.",
  ui_story_5043_50431401_42_dialog_content = "Insistieron mucho en que me uniera a sus filas.",
  ui_story_5043_50431401_43_dialog_content = "A pesar de mi confusión, los seguí hasta que finalmente...",
  ui_story_5043_50431401_44_dialog_content = "Llegamos al Salar Manor.",
  ui_story_5043_50431401_45_dialog_content = "¡Ey! ¡Esa es la casa de Schwab!",
  ui_story_5043_50431401_46_dialog_content = "Así es, y ahí fue donde lo vi por primera vez.",
  ui_story_5043_50431401_47_dialog_content = "Fue lo más impactante que jamás había visto...",
  ui_story_5043_50431401_48_dialog_content = "Estaba ordenando a los Eclipsites como si fueran esclavos.",
  ui_story_5043_50431401_49_dialog_content = "Y los Eclipsites... ¡Obedecieron todas sus órdenes!",
  ui_story_5043_50431401_50_dialog_content = "N-no tenía forma de escapar... Así que tuve que fingir ser uno de ellos.",
  ui_story_5043_50431401_51_dialog_content = "¡Fue entonces cuando nos encerró a todos en el sótano de Salar Manor!",
  ui_story_5043_50431401_52_dialog_content = "¡¿La bodega?!",
  ui_story_5043_50431401_53_dialog_content = "¡Así que mantuvo cautivos a esos Eclipsites allí todo el tiempo! No es de extrañar...",
  ui_story_5043_50431401_54_dialog_content = "¿Has estado allí antes?",
  ui_story_5043_50431401_55_dialog_content = "Er, no creo que este sea el momento o el lugar adecuado para decírtelo...",
  ui_story_5043_50431401_56_dialog_content = "¡Te hablaré de eso después del juicio!",
  ui_story_5043_50431401_57_dialog_content = "<size=45>¡Deja ya de tonterías!</size>",
  ui_story_5043_50431401_58_dialog_content = "¿Puedes creer el absoluto codswallop que se escupe de la boca de esta asquerosa criatura?",
  ui_story_5043_50431401_59_dialog_content = "¡¡¡No tengo motivos para soportar más esta ridícula calumnia!!!",
  ui_story_5043_50431401_60_dialog_content = "Veremos si es calumnia lo suficientemente pronto, juez Schwab.",
  ui_story_5043_50431401_61_dialog_content = "Cuéntanos qué pasó después, Toto.",
  ui_story_5043_50431401_62_dialog_content = "Si bien esta parte de su testimonio es impactante, de hecho, tiene poco que ver con las decapitaciones de estatuas en serie.",
  ui_story_5043_50431401_63_dialog_content = "¡Correcto! ¡Déjame relacionarlo con el caso!",
  ui_story_5043_50431401_64_dialog_content = "De vez en cuando, Schwab sacaba a algunos de nosotros del sótano para cumplir sus órdenes.",
  ui_story_5043_50431401_65_dialog_content = "Estaba desesperado por tener la oportunidad de escapar, así que actué aún más inquieto que mis hermanos.",
  ui_story_5043_50431401_66_dialog_content = "Y finalmente... Me eligió para una de sus tareas.",
  ui_story_5043_50431401_67_dialog_content = "Específicamente... ¡Me dijo que esperara hasta que el Globo Lunar se elevara hacia el cielo, y luego d-destruyera las estatuas debajo de él!",
  ui_story_5043_50431401_68_dialog_content = "¡Oh! ¡Eso coincide perfectamente con el conocimiento que tenemos sobre el caso!",
  ui_story_5043_50431401_69_dialog_content = "Las dos primeras veces fueron las estatuas frente al Salón de Justicia y Meadow Square.",
  ui_story_5043_50431401_70_dialog_content = "¡¿Frente al Salón de la Justicia?!",
  ui_story_5043_50431401_71_dialog_content = "Eso fue... ¡Mi amante!",
  ui_story_5043_50431401_72_dialog_content = "Lamento profundamente su pérdida, Sr. Byron.",
  ui_story_5043_50431401_73_dialog_content = "Quizás fue porque las dos primeras veces transcurrieron sin problemas... Pero Schwab me pidió más la tercera vez.",
  ui_story_5043_50431401_74_dialog_content = "M-Me dijo... Que me pusiera un guante extraño antes de romper la tercera estatua...",
  ui_story_5043_50431401_75_dialog_content = "Eso explica el guante!!!",
  ui_story_5043_50431401_76_dialog_content = "Y una vez que terminara, dejaría el guante en la escena del crimen.",
  ui_story_5043_50431401_77_dialog_content = "Fue entonces cuando fui a la Escalera a los Cielos con un grupo de Eclipsitas...",
  ui_story_5043_50431401_78_dialog_content = "Pero justo después de que rompí la cabeza de la estatua, el juez Leyn Logré agarrar mi mano derecha... Apenas evité la captura ese día.",
  ui_story_5043_50431401_79_dialog_content = "Afortunadamente, pude sacar mi mano del guante y salir corriendo... Con eso, mi \"tarea\" fue un éxito.",
  ui_story_5043_50431401_80_dialog_content = "¿Es este el guante que dejaste atrás?",
  ui_story_5043_50431401_81_dialog_content = "¡Sí! ¡Ese es!",
  ui_story_5043_50431401_82_dialog_content = "¡Se suma! ¡Todo suma ahora!",
  ui_story_5043_50431401_83_dialog_content = "Parece que el testimonio de Toto se alinea con la evidencia proporcionada en este juicio.",
  ui_story_5043_50431401_84_dialog_content = "A continuación, permítanos...",
  ui_story_5043_50431401_85_dialog_content = "¡Hmph! \"Líneas\", dices?",
  ui_story_5043_50431401_86_dialog_content = "¡Este \"testimonio\" de sus sonidos totalmente ensayado! ¡Una narrativa completamente falsificada!",
  ui_story_5043_50431401_87_dialog_content = "¿Hay alguna evidencia, alguna en absoluto, que demuestre que incluso una oración de lo que dijo es la verdad?",
  ui_story_5043_50431401_88_dialog_content = "Entonces, a pesar de su voluntad de declararse culpable, ¿todavía no encuentra su testimonio lo suficientemente confiable, juez Schwab?",
  ui_story_5043_50431401_89_dialog_content = "¡Por supuesto que no! ¡El hecho de que un testigo se declare culpable no significa que sea el culpable!",
  ui_story_5043_50431401_90_dialog_content = "Tengo razones más que suficientes para sospechar que alguien compró este Eclipsite para enmarcarme con él.",
  ui_story_5043_50431401_91_dialog_content = "Después de todo, usar una forma de vida inferior para incriminar a un juez de alto rango sería una ganga, ¿no le parece?",
  ui_story_5043_50431401_92_dialog_content = "¡¿Q-Qué se supone que significa eso?! ¡¡B-Además, t-tú eres el que me incrimina!!",
  ui_story_5043_50431401_93_dialog_content = "Solo vine a Lumopolis a buscar trabajo... ¡Nunca quise que me capturaran y me mandaran por tus intrigas!",
  ui_story_5043_50431401_94_dialog_content = "Si alguien no hubiera dejado la puerta del sótano abierta ayer, ¡nunca habría vuelto a encontrar mi libertad!",
  ui_story_5043_50431401_95_dialog_content = "Ya veo... Parece que esta bodega es bastante interesante.",
  ui_story_5043_50431401_96_dialog_content = "¡Disparates! ¡Está diciendo tonterías otra vez!",
  ui_story_5043_50431401_97_dialog_content = "¡Mi casa no tiene sótano de ningún tipo!",
  ui_story_5043_50431401_98_dialog_content = "¿Oh sí? ¡¿Por qué no enviamos a alguien a buscarlo y escuchar lo que tienen que decir?!",
  ui_story_5043_50431401_99_dialog_content = "¿Buscar mi casa? ¡Eso sería ilegal, monstruo tonto!",
  ui_story_5043_50431401_100_dialog_content = "¡La privacidad de la Familia Salar tiene derecho a la máxima protección de la ley!",
  ui_story_5043_50431401_101_dialog_content = "¿Pero cómo podría ser eso...?",
  ui_story_5043_50431401_102_dialog_content = "El juez Schwab tiene toda la razón. No tenemos derecho a iniciar una investigación sobre la residencia privada de la Familia Salar.",
  ui_story_5043_50431401_103_dialog_content = "...",
  ui_story_5043_50431401_104_dialog_content = "A menos, por supuesto, que haya demostrado su culpabilidad.",
  ui_story_5043_50431401_105_dialog_content = "¿¡¿Qué?!?",
  ui_story_5043_50431401_106_dialog_content = "Tch...",
  ui_story_5043_50431401_107_dialog_content = "Estoy seguro de que usted también se ha dado cuenta, juez Schwab. Después de todo, las palabras salieron de tu propia boca...",
  ui_story_5043_50431401_108_dialog_content = "\"El hecho de que un testigo se declare culpable no significa que sea el culpable\".",
  ui_story_5043_50431401_109_dialog_content = "...",
  ui_story_5043_50431401_110_dialog_content = "Dijiste esas palabras porque sabes que todo depende de ellas.",
  ui_story_5043_50431401_111_dialog_content = "En el momento en que el Salón de Justicia lo encuentre culpable, todo lo que dijo será sometido al más alto nivel de escrutinio.",
  ui_story_5043_50431401_112_dialog_content = "Eso es porque su testimonio también fue una admisión de culpabilidad.",
  ui_story_5043_50431401_113_dialog_content = "Y si el tribunal acepta el testimonio de Eclipsite, también acepta el hecho de que se rebeló contra alguien que movía los hilos detrás de escena.",
  ui_story_5043_50431401_114_dialog_content = "El Salón de Justicia tendría entonces todas las facultades para investigar los elementos del testimonio de Toto con todo el peso de la ley.",
  ui_story_5043_50431401_115_dialog_content = "Si eso sucediera, la pregunta de si el Salar Manor tiene o no una bodega sería respondida más temprano que tarde.",
  ui_story_5043_50431401_116_dialog_content = "Ahórrame tus artilugios, Leyn. Sé muy bien lo que estás planeando.",
  ui_story_5043_50431401_117_dialog_content = "Simplemente está utilizando un caso insignificante y un Eclipsite aún más insignificante para violar la privacidad de la Familia Salar.",
  ui_story_5043_50431401_118_dialog_content = "Recuerda lo que te digo, Leyn. ¡No lo lograrás!",
  ui_story_5043_50431401_119_dialog_content = "¡Ey! ¿De quién es el caso que llamas \"insignificante\"?",
  ui_story_5043_50431401_120_dialog_content = "¡Cállate la boca, desgraciado!",
  ui_story_5043_50431401_121_dialog_content = "¡¿Q-Qué fue eso...?!",
  ui_story_5043_50431401_122_dialog_content = "¡Ya he tenido bastante de esta farsa de juicio!",
  ui_story_5043_50431401_123_dialog_content = "Como juez principal, declaro que el testimonio de Eclipsite no tiene nada que ver con el caso.",
  ui_story_5043_50431401_124_dialog_content = "Como se indicó anteriormente, el juicio de este caso debe posponerse debido a la falta actual de pruebas convincentes.",
  ui_story_5043_50431401_125_dialog_content = "Se suspende la sesión del tribunal hasta el día en que se traigan a la luz pruebas concluyentes:",
  ui_story_5043_50431401_126_dialog_content = "¡E-Espera! ¡Tengo pruebas de mi culpabilidad!",
  ui_story_5043_50431401_127_dialog_content = "!",
  ui_story_5043_50431401_128_dialog_content = "¡Está justo aquí! ¡Justo en esta sala del tribunal!",
  ui_story_5043_50431401_129_dialog_content = "Déjame adivinar, ¿otra historia sin sentido destinada a implicarme?",
  ui_story_5043_50431401_130_dialog_content = "¡Tengo pruebas! ¡En realidad!",
  ui_story_5043_50431401_131_dialog_content = "¿Y qué es exactamente esta prueba, Toto?",
  ui_story_5043_50431401_132_dialog_content = "¡Es el guante que quedó en la escena del crimen!",
  ui_story_5043_50431401_133_dialog_content = "El guante...?",
  ui_story_5043_50431401_134_dialog_content = "Estoy seguro de que Schwab ya limpió el guante para eliminar cualquier rastro de eclipses...",
  ui_story_5043_50431401_135_dialog_content = "¡Pero antes de romper la estatua, usé mis uñas para hacer un agujero en el guante!",
  ui_story_5043_50431401_136_dialog_content = "¡E-Eso no es algo que pueda simplemente lavar!",
  ui_story_5043_50431401_137_dialog_content = "¿¡¿Qué?!?",
  ui_story_5043_50431401_138_dialog_content = "Veo. Así que si podemos encontrar ese agujero en el guante, prueba que eras tú quien lo llevaba puesto.",
  ui_story_5043_50431401_139_dialog_content = "Lo que, a su vez, probaría que usted es el culpable del crimen.",
  ui_story_5043_50431401_140_dialog_content = "¡Así es!",
  ui_story_5043_50431401_141_dialog_content = "Juez Schwab, ¿podríamos inspeccionar esa prueba una vez más?",
  ui_story_5043_50431401_142_dialog_content = "...",
  ui_story_5043_50431401_143_dialog_content = "Por favor entréguelo para que la corte lo vea.",
  ui_story_5043_50431401_144_dialog_content = "Si se va a levantar la sesión del tribunal en breve, prometo que no tardará mucho. Esta será nuestra última orden del día por hoy.",
  ui_story_5043_50431401_145_dialog_content = "...",
  ui_story_5043_50431401_146_dialog_content = "¿Juez Schwab?",
  ui_story_5043_50431401_147_dialog_content = "... Puaj.",
  ui_story_5043_50431401_148_dialog_content = "Precisamente por eso pienso <color=#FFB400>el amor es repugnante</color>.",
  ui_story_5043_50431401_149_dialog_content = "¡¿Qué?!",
  ui_story_5043_50431401_150_dialog_content = "Espera, ¿eso significa que él...?",
  ui_story_5043_50431401_151_dialog_content = "Me resulta repugnante estar rodeado de tantos plebeyos adoradores.",
  ui_story_5043_50431401_152_dialog_content = "Constantemente acercándose a mí, constantemente tratando de entrometerse en mi vida privada. ¡Imbéciles presuntuosos!",
  ui_story_5043_50431401_153_dialog_content = "Y sí, ustedes me recuerdan mucho a ellos.",
  ui_story_5043_50431401_154_dialog_content = "¿Dices que encuentras el amor \"repugnante\"?",
  ui_story_5043_50431401_155_dialog_content = "¡Por supuesto que sí! ¡Lo que vosotros llamáis amor no es más que una pesadilla ineludible!",
  ui_story_5043_50431401_156_dialog_content = "Estar rodeado de mis compañeros todos los días, tener que soportar sus halagos excesivos en todo momento.",
  ui_story_5043_50431401_157_dialog_content = "Cuando era estudiante, mi escritorio estaba lleno de cartas de amor y mi casa estaba llena de regalos durante las vacaciones solo para mí.",
  ui_story_5043_50431401_158_dialog_content = "¿¡¿Tienen idea de lo doloroso que es ser amado por todos?!?",
  ui_story_5043_50431401_159_dialog_content = "...",
  ui_story_5043_50431401_160_dialog_content = "... ¿De qué diablos está hablando?",
  ui_story_5043_50431401_161_dialog_content = "Tu predicción es como la mía.",
  ui_story_5043_50431401_162_dialog_content = "Al principio, pensé que las cosas mejorarían después de que empezara a trabajar.",
  ui_story_5043_50431401_163_dialog_content = "¡Nunca hubiera esperado que una ola de amor que induce al vómito se extendiera por toda la ciudad de esta manera!",
  ui_story_5043_50431401_164_dialog_content = "¡Y como para agravar mi sufrimiento, me hicieron el juez principal de esta humillante División de Romance dentro del Salón de Justicia!",
  ui_story_5043_50431401_165_dialog_content = "Así es. ¡¡¡No pude soportarlo más, así que planeé la destrucción de esas estatuas!!!",
  ui_story_5043_50431401_166_dialog_content = "¡Sabía que esos organizadores de eventos superficiales planeaban usarlos como piezas centrales de su vil celebración, y juré detenerlos a toda costa!",
  ui_story_5043_50431401_167_dialog_content = "Tú...",
  ui_story_5043_50431401_168_dialog_content = "¡Eres el superficial por usar la violencia para enviar tu mensaje de odio!",
  ui_story_5043_50431401_169_dialog_content = "¿Entonces por eso ordenó a los Eclipsites que destruyeran esas estatuas?",
  ui_story_5043_50431401_170_dialog_content = "Sí... Fui yo quien los envió. Sus naturalezas sucias son perfectas para profanar la llamada \"celebración del amor\".",
  ui_story_5043_50431401_171_dialog_content = "¿Significa esto que puedo tomar todo lo que acabas de decir como una admisión de culpabilidad?",
  ui_story_5043_50431401_172_dialog_content = "Ya puedes prescindir de las falsas formalidades, Leyn.",
  ui_story_5043_50431401_173_dialog_content = "Ya tienes todas las pruebas que necesitas. Ganaste.",
  ui_story_5043_50431401_174_dialog_content = "Mi único error fue que olvidé destruir la \"herramienta\" que usé para el crimen... Nunca pensé que volvería a testificar en mi contra de esta manera.",
  ui_story_5043_50431401_175_dialog_content = "...",
  ui_story_5043_50431401_176_dialog_content = "No, Schwab. La razón por la que perdiste no es tan complicada.",
  ui_story_5043_50431401_177_dialog_content = "La razón por la que perdiste es que no nos mostraste el guante.",
  ui_story_5043_50431401_178_dialog_content = "<size=45>¿¡¿Qué?!?</size>",
  ui_story_5043_50431401_179_dialog_content = "¡Espera un minuto! ¿No es el guante la prueba que necesitábamos para ganar?",
  ui_story_5043_50431401_180_dialog_content = "¿Será que... todo fue un farol?",
  ui_story_5043_50431401_181_dialog_content = "¡Uf, gracias a Dios que se acabó! Finalmente puedo respirar normalmente ahora.",
  ui_story_5043_50431401_182_dialog_content = "Debo decir, Leyn¡Realmente eres un maestro de la mala dirección!",
  ui_story_5043_50431401_183_dialog_content = "Ustedes... ¡¿Me engañaron?!",
  ui_story_5043_50431401_184_dialog_content = "¡¡¡E-Ese maldito Eclipsite nunca dejó ningún tipo de agujero en él!!!",
  ui_story_5043_50431401_185_dialog_content = "Jejeje... Pero espera, ¡hay más!",
  ui_story_5043_50431401_186_dialog_content = "¿No crees que lo encuentras un poco demasiado coincidente?",
  ui_story_5043_50431401_187_dialog_content = "¿Que el único Eclipsite que logró escapar de tu hogar, es el mismo al que le ordenaste destruir las estatuas?",
  ui_story_5043_50431401_188_dialog_content = "no me digas que tu...",
  ui_story_5043_50431401_189_dialog_content = "<color=#e8d9bb>Ayer...</color>",
  ui_story_5043_50431401_190_dialog_content = "¿Listo para un poco de tiempo extra, entonces?",
  ui_story_5043_50431401_191_dialog_content = "Por supuesto. Con el caso tan poco claro como siempre, es mi trabajo recopilar la mayor cantidad de información posible antes del juicio.",
  ui_story_5043_50431401_192_dialog_content = "Aun así, no esperaba que decidieras acompañarme.",
  ui_story_5043_50431401_193_dialog_content = "¡Tch! Dime, plebeyo, ¿fue eso un insulto a mi ética de trabajo o a mi amistad con Tina ¿En este momento?",
  ui_story_5043_50431401_194_dialog_content = "No importa, supongo. Dejemos de lado nuestras diferencias por ahora y concentrémonos en el caso...",
  ui_story_5043_50431401_195_dialog_content = "S-Perdón por molestar, pero ¿sigue abierto el Salón de la Justicia?",
  ui_story_5043_50431401_196_dialog_content = "¿Qué es esto? ¿Un eclipse?",
  ui_story_5043_50431401_197_dialog_content = "¡Y en la puerta del Palacio de Justicia, nada menos! ¡Prepárate para morir, demonio!",
  ui_story_5043_50431401_198_dialog_content = "¡E-Espera, no me hagas daño! ¡Estoy aquí para denunciar un crimen!",
  ui_story_5043_50431401_199_dialog_content = "¿Le ruego me disculpe? ¿Un Eclipsite reportando un crimen?",
  ui_story_5043_50431401_200_dialog_content = "Escuchemos lo que tiene que decir. Además, si causa algún problema, exterminarlo no será un problema.",
  ui_story_5043_50431401_201_dialog_content = "Bien. Háblanos de este crimen entonces. ¡Y hazlo rápido!",
  ui_story_5043_50431401_202_dialog_content = "¡E-está bien!",
  ui_story_5043_50431401_203_dialog_content = "A-Permítanme presentarme m-yo mismo...",
  ui_story_5043_50431401_204_dialog_content = "<color=#e8d9bb>Diez minutos tarde...</color>",
  ui_story_5043_50431401_205_dialog_content = "... ¡Y fue entonces cuando nos rodeó a todos y nos encerró en el sótano de Salar Manor!",
  ui_story_5043_50431401_206_dialog_content = "Pero, ¿cómo podría ser esto? Quiero decir, explica por qué nos encontramos con Eclipsites en el sótano...",
  ui_story_5043_50431401_207_dialog_content = "¡S-sí! ¡Fue entonces cuando escapé con el r-resto de ellos!",
  ui_story_5043_50431401_208_dialog_content = "¡¿Qué?!",
  ui_story_5043_50431401_209_dialog_content = "Entonces eso significa... ¡Nosotros somos los que te rescatamos!",
  ui_story_5043_50431401_210_dialog_content = "¡A-Y no podría estar más agradecida! ¡Ustedes son m-mis héroes!",
  ui_story_5043_50431401_211_dialog_content = "¿Así que quiere acusar a Schwab de albergar eclipses contra su voluntad?",
  ui_story_5043_50431401_212_dialog_content = "¡S-Sí! Sé que la ley L-Lumopolis nunca protegería a un E-Eclipsite, ¡pero sé que debe estar tramando algo aún peor!",
  ui_story_5043_50431401_213_dialog_content = "Una tarea bastante simple. Ven mañana al juzgado y cuéntales a todos lo que acabas de decirnos.",
  ui_story_5043_50431401_214_dialog_content = "¡Pronto, todos sabrán exactamente qué ha estado haciendo Schwab en las sombras!",
  ui_story_5043_50431401_215_dialog_content = "S-Claro! ¡Yo puedo hacer eso!",
  ui_story_5043_50431401_216_dialog_content = "... ¿Tienes alguna prueba?",
  ui_story_5043_50431401_217_dialog_content = "P-Prueba?",
  ui_story_5043_50431401_218_dialog_content = "Recuerda, eres un Eclipsite.",
  ui_story_5043_50431401_219_dialog_content = "Hemos estado en el sótano de la familia Salar, así que podemos confiar en tus palabras, pero ¿qué pasa con los demás?",
  ui_story_5043_50431401_220_dialog_content = "Sin ninguna evidencia, todo lo que Schwab tiene que hacer es negar su testimonio y será expulsado.",
  ui_story_5043_50431401_221_dialog_content = "No solo eso, incluso puede ir tras de ti una vez que termine el juicio.",
  ui_story_5043_50431401_222_dialog_content = "Seguir adelante con esto sería una decisión extremadamente peligrosa.",
  ui_story_5043_50431401_223_dialog_content = "Lo siento, pero no tengo pruebas...",
  ui_story_5043_50431401_224_dialog_content = "N-Me tomó todo lo que tenía para escapar de su sótano...",
  ui_story_5043_50431401_225_dialog_content = "¡Ey! ¡No podemos darnos el lujo de rendirnos simplemente porque no tenemos pruebas!",
  ui_story_5043_50431401_226_dialog_content = "¿Por qué no intentamos hacer otra visita a Salar Manor?",
  ui_story_5043_50431401_227_dialog_content = "Espera, no creo que tengamos que ir tan lejos. Tengo una idea...",
  ui_story_5043_50431401_228_dialog_content = "¿Seguir?",
  ui_story_5043_50431401_229_dialog_content = "¡Ya que no tenemos pruebas, todo lo que tenemos que hacer es lograr que admita los crímenes!",
  ui_story_5043_50431401_230_dialog_content = "... ¿Estás bromeando no?",
  ui_story_5043_50431401_231_dialog_content = "¡¿Cómo podríamos hacer que los admitiera sin ninguna prueba?!",
  ui_story_5043_50431401_232_dialog_content = "Dime, ¿por qué crees que estaba manteniendo cautivo a Eclipsites en primer lugar?",
  ui_story_5043_50431401_233_dialog_content = "Hmm... Bueno, para que él hiciera algo tan peligroso, tendría que ser por una razón muy importante.",
  ui_story_5043_50431401_234_dialog_content = "Creo que de alguna manera les ordenó destruir las estatuas.",
  ui_story_5043_50431401_235_dialog_content = "¿Oh? ¿Qué te hace decir eso?",
  ui_story_5043_50431401_236_dialog_content = "¿Recuerdas cuando agarré la mano del culpable en la Escalera a los Cielos?",
  ui_story_5043_50431401_237_dialog_content = "Después de que tú y los demás acabasteis con el resto de los Eclipsites, no había nadie más alrededor.",
  ui_story_5043_50431401_238_dialog_content = "La parte superior de la Escalera a los Cielos es un enorme espacio abierto. No hay forma de que alguien pueda desaparecer de nuestra vista tan rápido.",
  ui_story_5043_50431401_239_dialog_content = "A menos, por supuesto, que el culpable fuera un Eclipsite.",
  ui_story_5043_50431401_240_dialog_content = "¡Ah, ya veo! ¡Si el culpable fuera un Eclipsite, nos habríamos deshecho de él junto con los demás!",
  ui_story_5043_50431401_241_dialog_content = "¡Eso explicaría por qué nunca los encontramos!",
  ui_story_5043_50431401_242_dialog_content = "Esta es la razón más probable, sí.",
  ui_story_5043_50431401_243_dialog_content = "Entonces, ¿cómo piensa utilizar esta información?",
  ui_story_5043_50431401_244_dialog_content = "Primero, vamos a hacer que Toto sea el culpable.",
  ui_story_5043_50431401_245_dialog_content = "A continuación, le pediremos que dé nuestra versión de la verdad como su testimonio.",
  ui_story_5043_50431401_246_dialog_content = "Mientras nuestra corazonada se acerque lo suficiente a la verdad, Schwab creerá que Toto era el Eclipsite a quien ordenó destruir las estatuas.",
  ui_story_5043_50431401_247_dialog_content = "¡Es perfecto! Así que tu objetivo es hacerle creer que tenemos pruebas incriminatorias sobre él. Y luego, una vez que reconozca la derrota, ¡confesará sus crímenes por frustración!",
  ui_story_5043_50431401_248_dialog_content = "Así es. Tenemos que vencerlo en una batalla de ingenio.",
  ui_story_5043_50431401_249_dialog_content = "Entonces, ¿qué dices, Totó? ¿Estás dispuesto a mentir bajo juramento?",
  ui_story_5043_50431401_250_dialog_content = "¡A-Mientras exponga a Schwab, lo haré!",
  ui_story_5043_50431401_251_dialog_content = "Bien. Pasaremos el resto del día ensayando sus líneas, entonces.",
  ui_story_5043_50431401_252_dialog_content = "Si queremos maximizar nuestras posibilidades de éxito, debemos encontrar algo convincente.",
  ui_story_5043_50431401_253_dialog_content = "Algo que hará que Schwab dude de sí mismo lo suficiente como para creer que estamos diciendo la verdad.",
  ui_story_5043_50431401_254_dialog_content = "Vosotros... ¡Miserables charlatanes!",
  ui_story_5043_50431401_255_dialog_content = "Todo lo que hicimos fue apagar fuego con fuego, juez Schwab.",
  ui_story_5043_50431401_256_dialog_content = "Pensar que el culpable fue el juez principal todo el tiempo.",
  ui_story_5043_50431401_257_dialog_content = "Es increíble. ¿Cómo podría alguno de ustedes caer tan bajo? ¡¿Se llaman a sí mismos miembros del Salón de la Justicia?!",
  ui_story_5043_50431401_258_dialog_content = "Aun así, el tribunal finalmente pudo sacar a la luz la verdad, ¿no es así?",
  ui_story_5043_50431401_259_dialog_content = "¡A veces, la única forma de vencer a la oscuridad es con la oscuridad misma!",
  ui_story_5043_50431401_260_dialog_content = "Se acabó, juez Schwab. Vengan pacíficamente y asuma la responsabilidad de sus acciones.",
  ui_story_5043_50431401_261_dialog_content = "Hmph. ¿Se acabó, dices?",
  ui_story_5043_50431401_262_dialog_content = "Parece que tú también has cometido un único y crucial error, Leyn. ¿Quieres adivinar qué es?",
  ui_story_5043_50431401_263_dialog_content = "Qué quieres decir...?",
  ui_story_5043_50431401_264_dialog_content = "Tu error fue suponer que las cosas llegarían a su fin una vez que descubrieras la verdad.",
  ui_story_5043_50431401_265_dialog_content = "Como juez principal, por la presente declaro que el juez Leyn, Juez Tinay juez Matthieu ¡Todos son cómplices de los delitos presentados ante el tribunal!",
  ui_story_5043_50431401_266_dialog_content = "¡Los tres perpetradores serán arrestados inmediatamente después de la clausura de este juicio!",
  ui_story_5043_50431401_267_dialog_content = "¡¿Qué locura es esta, Schwab?!",
  ui_story_5043_50431401_268_dialog_content = "¡Todos aquí acaban de escucharte confesar! ¡Tú eres el verdadero culpable, no nosotros!",
  ui_story_5043_50431401_269_dialog_content = "Vaya, parece que todavía tenemos que llegar a un consenso sobre este caso.",
  ui_story_5043_50431401_270_dialog_content = "¡Muy bien entonces! ¡Haremos que el jurado lo vote en su lugar!",
  ui_story_5043_50431401_271_dialog_content = "¡¿El jurado?!",
  ui_story_5043_50431401_272_dialog_content = "Un momento, ¿esos son...?",
  ui_story_5043_50431401_273_dialog_content = "E-Eclipsitos?! ¡¿Pero cómo?!",
  ui_story_5043_50431401_274_dialog_content = "Por favor entregue su declaración final, juez Leyn.",
  ui_story_5043_50431401_275_dialog_content = "... A la luz de todo lo sucedido, concluyo que Schwab Salar es el verdadero culpable de este caso.",
  ui_story_5043_50431401_276_dialog_content = "Bien, bien... Los que estén de acuerdo con su acusación, que levanten la mano.",
  ui_story_5043_50431401_277_dialog_content = "Vamos a ver... Leyn, Matthieu, Tina, y Judge Jr.",
  ui_story_5043_50431401_278_dialog_content = "Cuatro votos en total. Parece que tus palabras han influido en un buen número de corazones, Leyn.",
  ui_story_5043_50431401_279_dialog_content = "¡Eso es porque digo la verdad!",
  ui_story_5043_50431401_280_dialog_content = "Por otro lado, concluyo que los jueces Leyn, Tina, y Matthieu son los verdaderos culpables del caso.",
  ui_story_5043_50431401_281_dialog_content = "Aquellos que estén de acuerdo con mi conclusión, por favor golpeen la mesa una vez.",
  ui_story_5043_50431401_282_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5043_50431401_283_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5043_50431401_284_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5043_50431401_285_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5043_50431401_286_dialog_content = "Pero son...",
  ui_story_5043_50431401_287_dialog_content = "Cuatro votos.",
  ui_story_5043_50431401_288_dialog_content = "Incluyendo mi propio voto, que hace cinco.",
  ui_story_5043_50431401_289_dialog_content = "Parece que mi conclusión fue un poco más convincente que la tuya.",
  ui_story_5043_50431401_290_dialog_content = "Tu... ¡¡Reemplazaste a todos en el jurado con tus propios secuaces!!",
  ui_story_5043_50431401_291_dialog_content = "¿Tus secuaces? ¡Todos deben ser eclipses debajo de esas máscaras!",
  ui_story_5043_50431401_292_dialog_content = "¡Se han emitido los votos y se ha tomado una decisión clara!",
  ui_story_5043_50431401_293_dialog_content = "el tribunal encuentra Leyn, Matthieu, y Tina—",
  ui_story_5043_50431401_294_dialog_content = "¡Culpable!",
  ui_story_5043_50431401_295_dialog_content = "<color=#e8d9bb>¡Bang—!</color>",
  ui_story_5043_50431401_296_dialog_content = "¡Hay algo mal con esos jurados!",
  ui_story_5043_50431401_X296_dialog_content = "¡Qué Darkflow tan intenso! ¡Realmente son eclipses!",
  ui_story_5043_50431401_X297_dialog_content = "¿¡Q-Qué dijiste!?",
  ui_story_5043_50431401_X298_dialog_content = "Tienes que estar bromeando, ¿todas estas personas sentadas aquí conmigo son Eclipsitas?",
  ui_story_5043_50431401_297_dialog_content = "Respetados miembros del jurado, les agradezco su ayuda.",
  ui_story_5043_50431401_298_dialog_content = "Ustedes sirvieron no solo como testigos hoy sino como mis caballeros en la ejecución de la justicia.",
  ui_story_5043_50431401_299_dialog_content = "Por el poder conferido al Salón de la Justicia—",
  ui_story_5043_50431401_300_dialog_content = "¡Arrestar a esos criminales!",
  ui_story_5043_50431401_301_dialog_content = "Graah...",
  ui_story_5043_50431401_302_dialog_content = "¡Diablos, creo que esos son Eclipsites escondidos debajo de esas máscaras!",
  ui_story_5043_50431401_303_dialog_content = "En efecto. Si esta es la carta de triunfo de Schwab, no será fácil lidiar con ellos.",
  ui_story_5043_50431401_304_dialog_content = "¿Recurriendo a la violencia, todo porque perdiste en la corte? ¡Qué mezquino!",
  ui_story_5043_50431401_305_dialog_content = "Esto no es bueno, el Salón de la Justicia se adapta mejor a su estilo de lucha. ¡Estaremos rodeados en poco tiempo!",
  ui_story_5043_50431401_306_dialog_content = "Teníamos razón... ¡Teníamos razón, Schwab! ¡¿Cómo pudiste dejar que el mal triunfara en la casa de la justicia?!",
  ui_story_5043_50431401_307_dialog_content = "Déjalo ir, Leyn! ¡La justicia siempre se pone del lado del ganador, y aquí estamos peleando una batalla cuesta arriba!",
  ui_story_5043_50431401_308_dialog_content = "¡Tenemos que escapar mientras podamos!",
  ui_story_5043_50431401_309_dialog_content = "Ella tiene razón, ¡ahora muévete!",
  ui_story_5043_50431401_310_dialog_content = "¡Por aquí, date prisa!",
  ui_story_5043_50431402_1_dialog_content = "Muy por encima de nuestras cabezas, ¡nuestro amor flota como una nube! ♪",
  ui_story_5043_50431402_2_dialog_content = "Oculto justo detrás de un velo, ¡nuestro amor es tan orgulloso! ♪",
  ui_story_5043_50431402_3_dialog_content = "Desde lejos, nos preguntamos qué belleza hay dentro ♪",
  ui_story_5043_50431402_4_dialog_content = "¡Ver florecer nuestro amor es un deseo que no podemos ocultar! ♪",
  ui_story_5043_50431402_5_dialog_content = "Escuché que van a reventar el globo lunar hoy. ¿Crees que es verdad?",
  ui_story_5043_50431402_6_dialog_content = "¡Por supuesto que lo son! ¡Esa es toda la razón por la que estamos reunidos aquí hoy!",
  ui_story_5043_50431402_7_dialog_content = "Dicen que el globo está lleno de todo tipo de cosas, como flores, artesanías de papel e incluso burbujas de diferentes colores.",
  ui_story_5043_50431402_8_dialog_content = "¡Eso suena incluso mejor que los fuegos artificiales! ¡Un tributo perfecto al poder del amor!",
  ui_story_5043_50431402_9_dialog_content = "¿Eh? Parece que una multitud de personas está saliendo corriendo del Salón de la Justicia.",
  ui_story_5043_50431402_10_dialog_content = "¿Me pregunto qué están haciendo?",
  ui_story_5043_50431402_11_dialog_content = "Uf, finalmente logramos escapar.",
  ui_story_5043_50431402_12_dialog_content = "¡Aún no podemos relajarnos! ¡Van a ponerse al día en cualquier momento!",
  ui_story_5043_50431402_13_dialog_content = "...",
  ui_story_5043_50431402_14_dialog_content = "Monstruos persistentes, ¿no?",
  ui_story_5043_50431402_15_dialog_content = "¡¿Pretenden perseguirnos hasta Umbraton?!",
  ui_story_5043_50431402_16_dialog_content = "¡Espera, parece que un desfile se dirige hacia aquí!",
  ui_story_5043_50431402_17_dialog_content = "Ahora, de todos los tiempos...",
  ui_story_5043_50431402_18_dialog_content = "¡No podemos huir ahora! ¡Los Eclipsites atacarán a esa gente si lo hacemos!",
  ui_story_5043_50431402_19_dialog_content = "Así es. Tendremos que derrotarlos, aquí y ahora.",
  ui_story_5043_50431402_20_dialog_content = "PlayerName, ¿puede advertir al desfile y hacer que evacuen el área?",
  ui_story_5043_50431402_21_dialog_content = "¡Claro, déjamelo a mí!",
  ui_story_5043_50431402_22_dialog_content = "Vinieron a ver un espectáculo como nunca antes habían presenciado.",
  ui_story_5043_50431402_23_dialog_content = "¿Realmente tienes el corazón para robarles una experiencia tan esperada?",
  ui_story_5043_50431402_24_dialog_content = "Tú... ¡Cómo te atreves a hacer bromas en un momento como este!",
  ui_story_5043_50431402_25_dialog_content = "Estaba hablando completamente en serio, Matthieu. Todo lo que quiero es darle a la gente el espectáculo que se mueren por ver.",
  ui_story_5043_50431402_26_dialog_content = "¡Un final grandioso para esta farsa de celebración!",
  ui_story_5043_50431402_27_dialog_content = "<size=45>¡Así, todos! ¡Rápido, ahora!</size>",
  ui_story_5043_50431402_28_dialog_content = "<size=45>¡El espectáculo está a punto de comenzar!</size>",
  ui_story_5043_50431402_29_dialog_content = "Schwab, ¿cuál es el significado de esto?",
  ui_story_5043_50431402_30_dialog_content = "¡Está tratando de arruinar la celebración! ¡Esa gente está en peligro!",
  ui_story_5043_50431402_31_dialog_content = "¡Están corriendo! ¡No dejes que se acerquen a los Eclipsites!",
  ui_story_5043_50431402_32_dialog_content = "¡No te preocupes, yo los protegeré!",
  ui_story_5043_50431402_33_dialog_content = "¿Por qué tan serio? Después de todo, no es más que un espectáculo.",
  ui_story_5043_50431402_34_dialog_content = "Ahora que recuerdo, ¿no se suponía que el globo lunar explotaría hoy?",
  ui_story_5043_50431402_35_dialog_content = "Me pregunto qué encontraremos escondidos dentro de ese ridículo monumento flotante al amor cuando lo haga.",
  ui_story_5043_50431402_36_dialog_content = "no me digas que tu...",
  ui_story_5043_50431402_37_dialog_content = "¡Contempla los frutos de tus ridículas creencias!",
  ui_story_5043_50431402_38_dialog_content = "<color=#e8d9bb>Estallido-!!!</color>",
  ui_story_5043_50431402_39_dialog_content = "Wooooooow!!!",
  ui_story_5043_50431402_40_dialog_content = "¡Cuidado, todos!",
  ui_story_5043_50431402_41_dialog_content = "Oye, ¿qué es esto que flota sobre nosotros...?",
  ui_story_5043_50431402_42_dialog_content = "Los regalos de festivales antiguos, mis ramos de tréboles, ¿qué son estos?",
  ui_story_5043_50431402_43_dialog_content = "¿Son estas flores muertas?",
  ui_story_5043_50431402_44_dialog_content = "Sí, rosas muertas, para ser exactos...",
  ui_story_5043_50431402_45_dialog_content = "El cielo está lleno de flores muertas...",
  ui_story_5043_50431402_46_dialog_content = "Que vista tan fea, me siento horrible solo de verlo.",
  ui_story_5043_50431402_47_dialog_content = "¿Es realmente así como se suponía que iba a ser el estallido del Globo Lunar?",
  ui_story_5043_50431402_48_dialog_content = "¡De hecho, es!",
  ui_story_5043_50431402_49_dialog_content = "¡Ni un paso más, Schwab!",
  ui_story_5043_50431402_50_dialog_content = "¿Qué pasa, juez? Tina? ¿No es esta la imagen misma del amor?",
  ui_story_5043_50431402_51_dialog_content = "Una belleza que solo podemos imaginar cuando apartamos la mirada de lo que hay dentro.",
  ui_story_5043_50431402_52_dialog_content = "Como la luna en el cielo nocturno, nos cautiva con su misteriosa y lejana belleza.",
  ui_story_5043_50431402_53_dialog_content = "Su encanto extrae fuerza de lo desconocido, de la ignorancia de la gente sobre su verdadera naturaleza.",
  ui_story_5043_50431402_54_dialog_content = "Y ahora, todos lo han presenciado por sí mismos.",
  ui_story_5043_50431402_55_dialog_content = "Este es el verdadero significado de su supuesto amor.",
  ui_story_5043_50431402_56_dialog_content = "Todo lo que queda después de que la emoción y el absurdo desaparecen es un mundo en ruinas.",
  ui_story_5043_50431402_57_dialog_content = "Y desde este día en adelante, nadie volverá a ver la luna por su belleza nunca más.",
  ui_story_5043_50431402_58_dialog_content = "Bueno, tiene razón en una cosa, no quiero volver a ver ese estúpido globo nunca más.",
  ui_story_5043_50431402_59_dialog_content = "No es broma, ¿de quién fue la idea de llenarlo de flores muertas? Básicamente era solo una bolsa flotante de basura...",
  ui_story_5043_50431402_60_dialog_content = "¡Basta ya de tu retórica falaz! Fuiste tú quien cambió el contenido del globo, ¿no?",
  ui_story_5043_50431402_61_dialog_content = "Nunca toqué el contenido del globo. Todo lo que hice fue quitar los Lumináticos que lo rodeaban.",
  ui_story_5043_50431402_62_dialog_content = "¡Tú!",
  ui_story_5043_50431402_63_dialog_content = "No me mires así. Fuiste tú quien quiso mentirle a las masas conservando esas flores con Lumina.",
  ui_story_5043_50431402_64_dialog_content = "Todo lo que hice fue descubrir la verdad.",
  ui_story_5043_50431402_65_dialog_content = "La belleza solo se aprecia cuando alguien tiene la responsabilidad de la fealdad.",
  ui_story_5043_50431402_66_dialog_content = "Al igual que esas doncellas de ojos estrellados que me persiguen con sus promesas de amor, no tienen idea de cuánto sufro debido a sus vuelos de fantasía.",
  ui_story_5043_50431402_67_dialog_content = "¿Es esto realmente lo que es el amor...?",
  ui_story_5043_50431402_68_dialog_content = "Algo tan abrumador que crea cargas para los demás...",
  ui_story_5043_50431402_69_dialog_content = "Parece que finalmente estás empezando a entender mi mensaje.",
  ui_story_5043_50431402_70_dialog_content = "...",
  ui_story_5043_50431402_71_dialog_content = "(¿Podría ser que... cometí el mismo tipo de error?)",
  ui_story_5043_50431402_72_dialog_content = "Eso no es todo, Tina! ¡No deje que los conceptos erróneos de Schwab lo engañen!",
  ui_story_5043_50431402_73_dialog_content = "¿Ah?",
  ui_story_5043_50431402_74_dialog_content = "¿Cómo es posible que su \"verdad\" tenga prioridad sobre las experiencias de otras personas?",
  ui_story_5043_50431402_75_dialog_content = "Al igual que cualquier otra emoción, todos sentimos amor a nuestra manera.",
  ui_story_5043_50431402_76_dialog_content = "Puede que no sepa la \"verdad\" detrás del concepto de amor... ¡Pero solo ver lo felices que están todos durante eventos como estos es suficiente para mí!",
  ui_story_5043_50431402_77_dialog_content = "Y además, ¡no creo que Schwab haya sentido jamás un verdadero amor por sí mismo!",
  ui_story_5043_50431402_78_dialog_content = "¡¿Qué derecho tiene él de decirles a los demás cómo se sienten al respecto?!",
  ui_story_5043_50431402_79_dialog_content = "Tú...",
  ui_story_5043_50431402_80_dialog_content = "¡Por supuesto que nunca antes había sentido amor! ¡¿Cómo podría permitirme sentir una emoción tan repugnante?!",
  ui_story_5043_50431402_81_dialog_content = "Si, tienes razón, PlayerName!",
  ui_story_5043_50431402_82_dialog_content = "No hay verdad en lo que está diciendo en absoluto. ¡Está obsesionado con el peor resultado posible!",
  ui_story_5043_50431402_83_dialog_content = "Además, ¡no hay nada de malo en imaginar la belleza del amor!",
  ui_story_5043_50431402_84_dialog_content = "El amor no es algo que se pueda decidir en los tribunales. Entonces, ¿quiénes somos nosotros para juzgarlo?",
  ui_story_5043_50431402_85_dialog_content = "Ya sea una confesión de amor o amar a alguien desde lejos, unirse o separarse, ¡todas estas experiencias son expresiones válidas de amor!",
  ui_story_5043_50431402_86_dialog_content = "Schwab, ¡no tienes idea de lo que realmente significa el amor!",
  ui_story_5043_50431402_87_dialog_content = "Hmph, puede que tengas razón al decir que no entiendo el significado del amor.",
  ui_story_5043_50431402_88_dialog_content = "Tampoco entiendo por qué ustedes harían todo lo posible por conseguirlo.",
  ui_story_5043_50431402_89_dialog_content = "Para mí, el amor no es más que un estorbo, una emoción parasitaria que rompe mi paz e invita a otros a entrometerse en mi vida.",
  ui_story_5043_50431402_90_dialog_content = "¡No, su malvada influencia se extiende mucho más allá de mi vida! ¡Amenaza mi carrera y mi capacidad para cumplir con mis deberes, amenaza el equilibrio mismo de todo Lumopolis!",
  ui_story_5043_50431402_91_dialog_content = "¿Qué te hace decir eso?",
  ui_story_5043_50431402_92_dialog_content = "Basta con mirar a las personas que nos rodean. Incluso el más mínimo atisbo de emoción puede hacerles abandonar toda razón.",
  ui_story_5043_50431402_93_dialog_content = "¡Esas mismas emociones conducen al establecimiento de esta burla conocida como la División Romance!",
  ui_story_5043_50431402_94_dialog_content = "¿Qué ha hecho realmente el amor por nosotros, hmm? Además de dar a los delincuentes la oportunidad de escapar del castigo, nos lleva a acusar a personas inocentes de delitos que nunca cometieron.",
  ui_story_5043_50431402_95_dialog_content = "¡Profana las leyes centenarias que han mantenido unida a Lumopolis a lo largo de su gloriosa historia!",
  ui_story_5043_50431402_96_dialog_content = "Por eso, elegí hacer uso de toda la fuerza de la ley contra esta maldita ola de \"amor\" que asola nuestra bella ciudad...",
  ui_story_5043_50431402_97_dialog_content = "¡Todo lo que he hecho, lo hice con el único propósito de eliminar el amor como factor en la ejecución de la justicia!",
  ui_story_5043_50431402_98_dialog_content = "Necesitaba jurados cuyas opiniones coincidieran con las mías, cuyo juicio no se viera envenenado por emociones innecesarias.",
  ui_story_5043_50431402_99_dialog_content = "Afortunadamente, estos horribles monstruos eran más que capaces de cumplir esos roles.",
  ui_story_5043_50431402_100_dialog_content = "...",
  ui_story_5043_50431402_101_dialog_content = "Así que eso es lo que estuvo pensando todo el tiempo...",
  ui_story_5043_50431402_102_dialog_content = "Justificar la propia paranoia de tal manera.",
  ui_story_5043_50431402_103_dialog_content = "Este tipo de persona es mucho más aterrador que cualquier criminal que busque la infamia.",
  ui_story_5043_50431402_104_dialog_content = "Pero pongamos fin a esta conversación sin sentido sobre el amor.",
  ui_story_5043_50431402_105_dialog_content = "En cambio, dirijamos nuestra atención al caso que nos ocupa.",
  ui_story_5043_50431402_106_dialog_content = "Después de todo, eres todo <color=#FFB400>culpable</color> a los ojos de la corte!",
  ui_story_5043_50431402_107_dialog_content = "¡Oye, mira hacia allá!",
  ui_story_5043_50431402_108_dialog_content = "¡Están saliendo eclipses desde el interior del Salón de la Justicia!",
  ui_story_5043_50431402_109_dialog_content = "¡Este día no puede ser más loco! ¡¡¡Huir!!!",
  ui_story_5043_50431402_110_dialog_content = "Parece que Schwab está tomando la ofensiva nuevamente.",
  ui_story_5043_50431402_111_dialog_content = "Está loco si cree que puede convocar a Eclipsites frente al público. Los guardias lo pondrán grilletes muy pronto.",
  ui_story_5043_50431402_112_dialog_content = "Por ahora, todavía tenemos que tomar el control de la situación y asegurarnos de que sus acciones no dañen a ningún civil.",
  ui_story_5043_50431402_113_dialog_content = "Tú dices eso, pero esos Eclipsites enmascarados no serán fáciles de tratar...",
  ui_story_5043_50431402_114_dialog_content = "Déjame manejarlos.",
  ui_story_5043_50431402_115_dialog_content = "Por mi honor, y el honor de la familia Campbell—",
  ui_story_5043_50431402_116_dialog_content = "¡He aquí el poder de la Mano Divina!",
  ui_story_5043_50431402_117_dialog_content = "¡Guau! ¡¿Qué pasa con esta Lumina?!",
  ui_story_5043_50431402_118_dialog_content = "Un ataque como este podría ser suficiente para—",
  ui_story_5043_50431402_119_dialog_content = "Yaaaawn—",
  ui_story_5043_50431402_120_dialog_content = "¿Eh? H-Oye! ¡¿Por qué estás bostezando en un momento como este?!",
  ui_story_5043_50431402_121_dialog_content = "Lo siento... pero ya he... pasado mi límite... por hoy...",
  ui_story_5043_50431402_122_dialog_content = "Hmph. Tómenlos, Cuatro Caballeros.",
  ui_story_5043_50431402_123_dialog_content = "¡E-Espera, tiempo fuera! ¡¡Esto no es justo!!",
  ui_story_5043_50431402_124_dialog_content = "Animarse, Tina! ¡Ey! ¡¡¡Ey!!!",
  ui_story_5043_50431402_125_dialog_content = "Nnng... he aquí el poder... de la Mano Divina...!",
  ui_story_5043_50431402_126_dialog_content = "<color=#e8d9bb>Depresión-</color>",
  ui_story_5043_50431402_127_dialog_content = "¡Ella se durmió antes de que comenzara la pelea!",
  ui_story_5043_50431402_128_dialog_content = "¡¿Qué debemos hacer?! ¡Este no es un lugar para tomar una siesta!",
  ui_story_5043_50431402_129_dialog_content = "Despertar, Tina! ¡El enemigo está a punto de atacar!",
  ui_story_5043_50431402_130_dialog_content = "Estrellas... Veo estrellas... en tu cabeza... Leyn...",
  ui_story_5043_50431402_131_dialog_content = "¡Este no es momento para mirar las estrellas! ¡Prepárate para la batalla!",
  ui_story_5043_50431402_132_dialog_content = "Lo siento... pero no puedo...",
  ui_story_5043_50431402_133_dialog_content = "Toma, solo come esto.",
  ui_story_5043_50431402_134_dialog_content = "¿Eso es chocolate? Este tampoco es el momento para los bocadillos, Leyn!!!",
  ui_story_5043_50431402_135_dialog_content = "yo soy... yo soy...",
  ui_story_5043_50431402_136_dialog_content = "qué hacemos? Están justo en frente de nosotros ahora...",
  ui_story_5043_50431402_137_dialog_content = "¡¡¡Estoy perfectamente despierto ahora!!!",
  ui_story_5043_50431402_138_dialog_content = "¡¿Eh?!",
  ui_story_5043_50431402_139_dialog_content = "¡Hablando de una siesta energética!",
  ui_story_5043_50431402_140_dialog_content = "¡je! Cuando se trata de ganar el corazón de alguien, ¡tienes que confiar en más de una estrategia!",
  ui_story_5043_50431402_141_dialog_content = "¡Déjame mostrarte cómo se hace!",
  ui_story_5043_50431402_142_dialog_content = "¿Eh? ¿Qué es eso?",
  ui_story_5043_50431402_143_dialog_content = "¿Ya lo olvidaste? ¡Tú y los demás son los que me mostraron en primer lugar!",
  ui_story_5043_50431402_144_dialog_content = "Hay muchas maneras de perseguir un interés romántico, incluyendo... <color=#FFB400>una confesión</color>!",
  ui_story_5043_50431402_145_dialog_content = "Tenías razón todo el tiempo, Leyn! Obtener toda la atención de la otra persona es el primer paso y uno de los más importantes.",
  ui_story_5043_50431402_X145_dialog_content = "¡Aleja a los monstruos de la multitud!",
  ui_story_5043_50431402_146_dialog_content = "Disculpa que...?",
  ui_story_5043_50431402_147_dialog_content = "¡Muy bien, monstruos enmascarados, tomad esto!",
  ui_story_5043_50431402_148_dialog_content = "Graah...",
  ui_story_5043_50431402_149_dialog_content = "Creo que la Mano Divina logró captar toda su atención, ¿sí?",
  ui_story_5043_50431402_X149_dialog_content = "¡Graagh!",
  ui_story_5043_50431402_X150_dialog_content = "¡Ni siquiera dejarás un rasguño en mis caballeros con este nivel de poder! ¡No dejes de atacar!",
  ui_story_5043_50431402_150_dialog_content = "Juez Matthieu fue quien me mostró qué hacer a continuación. Aún lo recuerdas, ¿verdad?",
  ui_story_5043_50431402_151_dialog_content = "La gente no puede confiar únicamente en tomar la iniciativa. Ellos también deben aprender... <color=#FFB400>el arte de ocultar</color>!",
  ui_story_5043_50431402_152_dialog_content = "¡Y con razón! te cubriré, Tina!",
  ui_story_5043_50431402_153_dialog_content = "¡Rápido, pongámonos a cubierto detrás de esa pared!",
  ui_story_5043_50431402_154_dialog_content = "Hmph. ¿Listo para rendirte después de un contratiempo tan pequeño? Tu amor es verdaderamente frágil.",
  ui_story_5043_50431402_155_dialog_content = "¿No estabas diciendo hace un momento que querías proteger a la gente?",
  ui_story_5043_50431402_156_dialog_content = "Graaaaah...",
  ui_story_5043_50431402_157_dialog_content = "¿Grah?",
  ui_story_5043_50431402_158_dialog_content = "¡Lo sabía! ¡No pueden encontrarnos!",
  ui_story_5043_50431402_159_dialog_content = "¡Creo que esas máscaras que llevan puestas pueden ser sus puntos débiles!",
  ui_story_5043_50431402_160_dialog_content = "Puede que tengas razón. ¡Echemos un vistazo a lo que hay debajo de sus disfraces!",
  ui_story_5043_50431402_161_dialog_content = "¡Aquí es donde entra en juego el tercer método!",
  ui_story_5043_50431402_162_dialog_content = "Para encontrar el equilibrio adecuado entre avanzar y retroceder... <color=#FFB400>reconocimiento</color>!",
  ui_story_5043_50431402_163_dialog_content = "Necesitamos entender a la otra persona tanto como sea posible antes de dar el paso final.",
  ui_story_5043_50431402_X163_dialog_content = "¡Solo tenemos que encontrar su debilidad y dar el golpe decisivo para acabar con todo esto!",
  ui_story_5043_50431402_164_dialog_content = "¡Así que empecemos atacando sus máscaras!",
  ui_story_5043_50431402_165_dialog_content = "¡Ahora es nuestra oportunidad! ¡Ataque!",
  ui_story_5043_50431402_166_dialog_content = "¡¡¡Graaaah!!!",
  ui_story_5043_50431402_167_dialog_content = "<color=#e8d9bb>Pam, pam, pam!!!</color>",
  ui_story_5043_50431402_168_dialog_content = "Argh, ¿de qué están hechas esas cosas?",
  ui_story_5043_50431402_169_dialog_content = "Parece que romper esas máscaras no será tan fácil como pensábamos.",
  ui_story_5043_50431402_170_dialog_content = "¡Jajaja! ¡Oh, si tan solo pudieran ver las estúpidas miradas en sus rostros!",
  ui_story_5043_50431402_171_dialog_content = "¿Honestamente creíste que podrías dañar a mis caballeros con un ataque tan patético?",
  ui_story_5043_50431402_172_dialog_content = "Hmph, incluso cuando todo parece inútil, ¡todavía hay una posibilidad de que prevalezca el amor!",
  ui_story_5043_50431402_173_dialog_content = "En este punto, los trucos y las estrategias están fuera de discusión. Todo lo que queda por hacer—",
  ui_story_5043_50431402_174_dialog_content = "¡Ahora, Tina!",
  ui_story_5043_50431402_175_dialog_content = "¡Muéstrale al mundo lo que hay en tu corazón!",
  ui_story_5043_50431402_176_dialog_content = "¡Así es! ¡Tomaré cada onza de mi sinceridad!",
  ui_story_5043_50431402_177_dialog_content = "¡Y úsalo para asestar el golpe final!",
  ui_story_5043_50431402_178_dialog_content = "<size=45><color=#FFB400>Esplendor Divino</color>!</size>",
  ui_story_5043_50431402_179_dialog_content = "Uf, ¿lo logró?",
  ui_story_5043_50431402_180_dialog_content = "¡Ella hizo! ¡Ella voló las máscaras de esos Eclipsites!",
  ui_story_5043_50431402_181_dialog_content = "¡¿C-Cómo podría ser esto?! mis caballeros...",
  ui_story_5043_50431402_182_dialog_content = "¡Adelante, mis caballeros!",
  ui_story_5043_50431402_183_dialog_content = "¡No puedes fallarme ahora! ¡No cuando aún no se ha hecho justicia!",
  ui_story_5043_50431402_184_dialog_content = "Se acabó, Schwab.",
  ui_story_5043_50431402_185_dialog_content = "Al igual que tú, no sienten cosas como amor o lealtad, todo lo que pueden hacer es seguir órdenes sin pensar.",
  ui_story_5043_50431402_186_dialog_content = "Tal como eres ahora, nunca podrías esperar superar el poder crudo de nuestras emociones.",
  ui_story_5043_50431402_187_dialog_content = "¡¿Incluso ahora, insistes en hablar sobre tus sentimientos?!",
  ui_story_5043_50431402_188_dialog_content = "Ella tiene razón, ¿sabes? En cuanto a que no se haga justicia... Ya no tienes que preocuparte por eso.",
  ui_story_5043_50431402_189_dialog_content = "Con el resultado de las cosas, el Salón de Justicia definitivamente tomará este caso mucho más en serio.",
  ui_story_5043_50431402_190_dialog_content = "De hecho, no me sorprendería que el juez presidente Irridon preside todo.",
  ui_story_5043_50431402_191_dialog_content = "Estoy seguro de que te brindará la justicia que tanto deseas, Schwab.",
  ui_story_5043_50431402_192_dialog_content = "¿Servirme? ¡No no! ¡Esto no puede ser!",
  ui_story_5043_50431402_193_dialog_content = "¡Soy inocente, te lo digo! Nadie puede juzgarme!!!",
  ui_story_5043_50431402_194_dialog_content = "Eso no es para que usted decida.",
  ui_story_5043_50431402_195_dialog_content = "¡Por supuesto que lo es, tonto! ¡¡¡Soy el juez principal!!!",
  ui_story_5043_50431402_196_dialog_content = "Ese estado tampoco es para que tú lo decidas.",
  ui_story_5043_50431402_197_dialog_content = "¡Podrido! ¡Esta ciudad y sus leyes están podridas hasta la médula ahora!",
  ui_story_5043_50431402_198_dialog_content = "¡Fuera de mi camino! ¡Mi padre se enterará de esto!",
  ui_story_5043_50431402_199_dialog_content = "¡Recordad mis palabras, la Familia Salar no descansará hasta que se imponga la verdadera justicia!",
  ui_story_5043_50431402_200_dialog_content = "Qué vergüenza de tu parte, Schwab. ¿Correr a casa con papá cuando las cosas no salen como quieres?",
  ui_story_5043_50431402_201_dialog_content = "Qué desgracia.",
  ui_story_5043_50431402_202_dialog_content = "¡Dije fuera de mi camino!",
  ui_story_5043_50431402_203_dialog_content = "<color=#e8d9bb>¡Golpe!</color>",
  ui_story_5043_50431402_204_dialog_content = "¡Urgh...!",
  ui_story_5043_50431402_205_dialog_content = "¿Quién era? ¡¿Quién me golpeó hace un momento?!",
  ui_story_5043_50431402_206_dialog_content = "Fui yo, ya menos que vengas con nosotros pacíficamente al Salón de la Justicia... Habrá más de donde vino eso.",
  ui_story_5043_50431402_207_dialog_content = "Leyn! ¡Tonto!",
  ui_story_5043_50431402_208_dialog_content = "¡¿Tienes alguna idea de lo que acabas de hacer, desgraciado plebeyo?!",
  ui_story_5043_50431402_209_dialog_content = "Fue por tu propio bien.",
  ui_story_5043_50431402_210_dialog_content = "Es posible que no haya llegado a su juicio si Tina te había golpeado a ti en su lugar.",
  ui_story_5043_50431402_211_dialog_content = "¡Es cierto!",
  ui_story_5043_50431402_212_dialog_content = "T-Todos ustedes...",
  ui_story_5043_50431402_213_dialog_content = "Eso servirá, todos. ¡Los empleados de la División de Romance todavía están trabajando!",
  ui_story_5043_50431402_214_dialog_content = "¡Venir venir! ¡Es hora de volver a nuestros deberes!",
  ui_story_5043_50431402_215_dialog_content = "Supongo que todavía tenemos mucho trabajo por hoy, ¿eh?",
  ui_story_5043_50431402_216_dialog_content = "Yaaaawn... Oh, gracias a Dios, un sofá...",
  ui_story_5043_50431402_217_dialog_content = "¡Ey! ¡Mantén tus sucias manos lejos de mí!",
  ui_story_5043_50431402_218_dialog_content = "¡No seré empujado como un criminal común!",
  ui_story_5043_50431402_219_dialog_content = "¡Guau! ¡Finalmente están deteniendo a Schwab!",
  ui_story_5043_50431402_220_dialog_content = "Parece que todo salió bien al final, ¿eh?",
  ui_story_5043_50431402_221_dialog_content = "En efecto. Schwab tiene mucho de lo que responder. Su castigo no será ligero.",
  ui_story_5043_50431402_222_dialog_content = "Si bien sus acciones no resultaron en ningún daño real, todavía estaban en violación directa de las leyes de Lumopolis.",
  ui_story_5043_50431402_223_dialog_content = "Si alguna vez elige manipular Eclipsites de esta manera otra vez... No me atrevo a imaginar las consecuencias.",
  ui_story_5043_50431402_224_dialog_content = "No creo que lo haga. ¡Después de todo, su verdadero enemigo fue el amor todo el tiempo! Jajajaja!",
  ui_story_5043_50431402_225_dialog_content = "Eso es cierto. Su odio por el concepto del amor lo llevó a tales extremos, no a nadie ni a nada en particular.",
  ui_story_5043_50431402_226_dialog_content = "Por lo menos, pudo entregar su mensaje equivocado, gracias a esa farsa de juicio y este truco con el Globo Lunar.",
  ui_story_5043_50431402_227_dialog_content = "¡Sí, diría que este caso está cerrado!",
  ui_story_5043_50431402_228_dialog_content = "Nunca hubiera imaginado que un incidente tan pequeño terminaría de una manera tan loca...",
  ui_story_5043_50431402_229_dialog_content = "Yo tampoco, pero finalmente se acabó.",
  ui_story_5043_50431402_230_dialog_content = "Todo lo que queda es escuchar un veredicto final.",
  ui_story_5043_50431402_231_dialog_content = "¡Sí! ¡Vamos a buscar buenos asientos!",
  ui_story_5043_50431402_232_dialog_content = "No puedo esperar a escuchar lo que el juez tiene que decir sobre esto.",
  ui_story_5043_50431402_233_dialog_content = "¿Eh? ¿Pasa algo, hermana?",
  ui_story_5043_50431402_234_dialog_content = "Se acabó...",
  ui_story_5043_50431402_235_dialog_content = "¿P-Por qué estás llorando?",
  ui_story_5043_50431402_236_dialog_content = "La gente se ha ido, y también el globo.",
  ui_story_5043_50431402_237_dialog_content = "Mis flores y tréboles, todo ha terminado...",
  ui_story_5043_50431402_238_dialog_content = "Lo siento, hermana... ¡Pero no fue culpa tuya, fue de Schwab!",
  ui_story_5043_50431402_239_dialog_content = "Aun así, todo ha terminado ahora.",
  ui_story_5043_50431402_240_dialog_content = "La ola de amor de Lumopolis finalmente ha retrocedido...",
  ui_story_5043_50431501_1_dialog_content = "Después de una investigación minuciosa, la verdad detrás de los crímenes fue exactamente la misma. Leyn había supuesto.",
  ui_story_5043_50431501_2_dialog_content = "Schwab fue declarado culpable de las decapitaciones de estatuas en serie y también fue declarado culpable de manipular Eclipsites para cumplir sus órdenes.",
  ui_story_5043_50431501_3_dialog_content = "Afortunadamente, ningún auroriano resultó herido debido a sus acciones retorcidas, y los únicos daños sufridos fueron en esas tres estatuas.",
  ui_story_5043_50431501_4_dialog_content = "Supongo que todavía tenía algo de sentido de la justicia en su corazón después de todo, jaja...",
  ui_story_5043_50431501_5_dialog_content = "Sin embargo, necesito dárselo a esos tres jueces. ¡Se las arreglaron para deducir la verdad detrás de los crímenes sin apenas evidencia que los ayudara!",
  ui_story_5043_50431501_6_dialog_content = "En efecto. Después de este caso, estoy seguro de que la Sala de Justicia observará sus talentos con mayor interés.",
  ui_story_5043_50431501_7_dialog_content = "Aunque todavía hay una cosa que no entiendo.",
  ui_story_5043_50431501_8_dialog_content = "Para empezar, ¿cómo logró exactamente Schwab controlar esos eclipses?",
  ui_story_5043_50431501_9_dialog_content = "No lo vi usar ningún tipo de equipo especial durante nuestra batalla...",
  ui_story_5043_50431501_10_dialog_content = "Oh, la investigación también tiene una teoría sobre eso.",
  ui_story_5043_50431501_11_dialog_content = "Después de adquirir las órdenes necesarias, el Salón de Justicia registró Salar Manor y encontró el sótano donde Schwab escondió sus Eclipsites.",
  ui_story_5043_50431501_12_dialog_content = "Sin embargo, fuera de su sótano, los investigadores no encontraron nada que pudiera haber sido utilizado para controlarlos.",
  ui_story_5043_50431501_13_dialog_content = "Después de un largo interrogatorio, así como de una búsqueda completa en el sótano, el Salón de Justicia llegó a una conclusión inesperada.",
  ui_story_5043_50431501_14_dialog_content = "Schwab logró domar a los Eclipsites con métodos diferentes a los que se usan para el entrenamiento de animales.",
  ui_story_5043_50431501_15_dialog_content = "Él los domesticó?!?",
  ui_story_5043_50431501_16_dialog_content = "¿Pueden los eclipses realmente ser entrenados así?",
  ui_story_5043_50431501_17_dialog_content = "Si lo piensas bien, la noción no está completamente fuera del ámbito de la posibilidad.",
  ui_story_5043_50431501_18_dialog_content = "Los Aurorianos hemos visto a los Eclipsites como nuestros enemigos mortales durante generaciones. Naturalmente, tenemos un intenso sesgo en contra de ellos.",
  ui_story_5043_50431501_19_dialog_content = "Pero una vez que dejas de lado la historia entre nuestras especies, puedes ver que los eclipses son solo criaturas de inteligencia inferior.",
  ui_story_5043_50431501_20_dialog_content = "Tienen sus propias necesidades y comportamientos y no son diferentes a cualquier otro animal.",
  ui_story_5043_50431501_21_dialog_content = "Al tener en cuenta los hábitos y las características de una criatura, se la puede entrenar para que comprenda que seguir órdenes conduce a resultados positivos. Esa es la lógica detrás de la domesticación de bestias, ¿no es así?",
  ui_story_5043_50431501_22_dialog_content = "Todo lo que hizo Schwab fue domesticarlos hasta cierto punto, al igual que nuestros antepasados hicieron con los lobos y otros animales.",
  ui_story_5043_50431501_23_dialog_content = "Entiendo...",
  ui_story_5043_50431501_24_dialog_content = "Tiene sentido, pero sigo pensando que es un poco increíble.",
  ui_story_5043_50431501_25_dialog_content = "Muchos de los detalles del caso dan credibilidad a la conclusión.",
  ui_story_5043_50431501_26_dialog_content = "Schwab siempre ha menospreciado a los de su propia especie, pero, curiosamente, muestra una gran afinidad por los animales pequeños.",
  ui_story_5043_50431501_27_dialog_content = "Para que él hiciera todo lo posible por sus esquemas, también habría requerido una cantidad igualmente increíble de paciencia.",
  ui_story_5043_50431501_28_dialog_content = "Cuando lo pones de esa manera, no suena tan mal, al menos no desde el punto de vista de un auroriano.",
  ui_story_5043_50431501_29_dialog_content = "Oh, espera un minuto, no soy un auroriano...",
  ui_story_5043_50431501_30_dialog_content = "Muy bien, creo que podemos guardar el resto de esta discusión para más adelante.",
  ui_story_5043_50431501_31_dialog_content = "El juicio de Schwab está a punto de comenzar.",
  ui_story_5043_50431501_32_dialog_content = "El acusado, Schwab Salar, está acusado de manipular Eclipsites para llevar a cabo la destrucción de tres estatuas.",
  ui_story_5043_50431501_33_dialog_content = "La Sala de Justicia ha investigado a fondo el asunto, y las pruebas obtenidas corroboran la acusación antes mencionada.",
  ui_story_5043_50431501_34_dialog_content = "¿Tiene algo que decir en su defensa, Schwab Salar?",
  ui_story_5043_50431501_35_dialog_content = "...",
  ui_story_5043_50431501_36_dialog_content = "(Él solía actuar tan alto y poderoso antes, pero ahora se ve completamente avergonzado de sí mismo).",
  ui_story_5043_50431501_37_dialog_content = "La investigación también ha concluido que, a pesar de la conducta ilícita del acusado, no se han causado daños graves a la ciudad de Lumopolis ni a su gente.",
  ui_story_5043_50431501_38_dialog_content = "Además, teniendo en cuenta la edad relativamente joven del acusado, el tribunal cree que aún puede corregir sus formas. Como tal, el tribunal no impondrá una pena de prisión al acusado.",
  ui_story_5043_50431501_39_dialog_content = "¿Oh? Así que no iré a prisión después de todo.",
  ui_story_5043_50431501_40_dialog_content = "Que tiene sentido. Por problemático que sea, las acciones de Schwab no fueron más que vandalismo equivocado.",
  ui_story_5043_50431501_41_dialog_content = "Dada la menor extensión de los daños, no hay razón para enviarlo a la cárcel por sus crímenes.",
  ui_story_5043_50431501_42_dialog_content = "Sin embargo, la exención de la pena de prisión no significa una exención total de todas las repercusiones legales.",
  ui_story_5043_50431501_43_dialog_content = "El demandado, así como la Familia Salar, deben asumir todas y cada una de las cargas financieras incurridas por este caso.",
  ui_story_5043_50431501_44_dialog_content = "Su salario como juez de la Sala de Justicia también se deducirá en su totalidad.",
  ui_story_5043_50431501_45_dialog_content = "Por supuesto. Acepto mis castigos sin dudarlo.",
  ui_story_5043_50431501_46_dialog_content = "¿Por qué se ve tan tranquilo en este momento?",
  ui_story_5043_50431501_47_dialog_content = "El dinero es lo menos importante del mundo para un hombre como él.",
  ui_story_5043_50431501_48_dialog_content = "Si ese es el caso, ¿no crees que su castigo es demasiado indulgente?",
  ui_story_5043_50431501_49_dialog_content = "Naturalmente, esto es sólo la mitad de su sentencia.",
  ui_story_5043_50431501_50_dialog_content = "Después de analizar los eventos que condujeron a este incidente, el Salón de Justicia concluyó que el comportamiento extremo de Schwab Salar fue el resultado de una falla dentro del sistema educativo de la aristocracia.",
  ui_story_5043_50431501_51_dialog_content = "Por lo tanto, para subsanar este incumplimiento, el tribunal condena a Schwab Salar a la reeducación en su anterior lugar de estudio.",
  ui_story_5043_50431501_52_dialog_content = "Qué...? Quieres decir que tengo que volver a la Dawn Academia y repetir mis clases?!",
  ui_story_5043_50431501_53_dialog_content = "Coludir con Eclipsites es un delito grave y debe tratarse con severidad.",
  ui_story_5043_50431501_X53_dialog_content = "El tribunal ha decidido que el delincuente, Schwab, necesita la guía renovada del Dios de la Luz.",
  ui_story_5043_50431501_54_dialog_content = "Para recibir esta orientación, ha sido asignado a la <color=#FFB400>templo en el que se entrenan las monjas</color>.",
  ui_story_5043_50431501_55_dialog_content = "N-Monjas?!?",
  ui_story_5043_50431501_56_dialog_content = "Esto... ¡¡¡Esto va demasiado lejos, Su Señoría!!!",
  ui_story_5043_50431501_57_dialog_content = "Permítame presentarle a su nuevo instructor. May tu reeducación procede sin problemas, Schwab Salar.",
  ui_story_5043_50431501_58_dialog_content = "Nos encontramos de nuevo, Sr. Schwab.",
  ui_story_5043_50431501_59_dialog_content = "¡Eres tu! Eso solo puede significar que esta fue tu idea, ¿no?",
  ui_story_5043_50431501_60_dialog_content = "Tenemos un currículo emocionante planeado solo para ti. Además de sus estudios teológicos diarios, habrá lecciones de costura, cocina y servicio a los menos afortunados...",
  ui_story_5043_50431501_61_dialog_content = "Me siento honrado de tener el privilegio de guiar sus estudios durante los próximos años.",
  ui_story_5043_50431501_62_dialog_content = "¡¡¡No, nooo!!! ¡¡¡Me niego a recibir educación en un lugar dirigido íntegramente por mujeres!!!",
  ui_story_5043_50431501_63_dialog_content = "Parece que tus valores sociales también necesitan reeducación.",
  ui_story_5043_50431501_64_dialog_content = "Llévenlo al convento y prepárenlo para su nueva vida de estudio y reflexión.",
  ui_story_5043_50431501_65_dialog_content = "Además de Schwab, hay otras partes en este caso que necesitan ser reprendidas.",
  ui_story_5043_50431501_66_dialog_content = "Juez Leyn.",
  ui_story_5043_50431501_67_dialog_content = "¡Sí, su señoría!",
  ui_story_5043_50431501_68_dialog_content = "Estás acusado de irrumpir en Salar Manor. ¿Admites este crimen?",
  ui_story_5043_50431501_69_dialog_content = "Sí.",
  ui_story_5043_50431501_70_dialog_content = "(Pensé que no le mentiría al juez principal...)",
  ui_story_5043_50431501_71_dialog_content = "Muy bien. Por autorización de la Sala de Justicia, y de conformidad con el artículo 127 del Código de Conducta de los Jueces...",
  ui_story_5043_50431501_72_dialog_content = "Su calificación de desempeño mensual se restablecerá a cero, y su salario de este mes se reducirá al grado de pago mínimo permitido como servidor público de Lumopolis.",
  ui_story_5043_50431501_73_dialog_content = "Yo entiendo...",
  ui_story_5043_50431501_74_dialog_content = "(¡Él dice eso, pero creo que ese fue el castigo más doloroso que le pudieron haber dado!)",
  ui_story_5043_50431501_75_dialog_content = "Bueno, ahora, de verdad... ¡Soy igual de culpable de este crimen, Su Señoría!",
  ui_story_5043_50431501_76_dialog_content = "Estaba con él en ese momento, así que creo que este castigo debe dividirse entre los dos.",
  ui_story_5043_50431501_77_dialog_content = "¿Es así, juez? Matthieu?",
  ui_story_5043_50431501_78_dialog_content = "¡Yo también estaba allí! ¡No te olvides de mí!",
  ui_story_5043_50431501_79_dialog_content = "Debo decir que su voluntad de reconocer sus errores es muy refrescante. ¡Muy bien entonces! Aparte de que el salario del juez Matthieu fue descontado por el mes...",
  ui_story_5043_50431501_80_dialog_content = "Los sentencio a los tres a barrer los terrenos fuera del Salón de Justicia más tarde.",
  ui_story_5043_50431501_81_dialog_content = "La vista de todas esas flores muertas es muy desagradable.",
  ui_story_5043_50431501_82_dialog_content = "¿Q-Qué tipo de castigo es este?",
  ui_story_5043_50431501_83_dialog_content = "¿Quieres que lo reconsidere?",
  ui_story_5043_50431501_84_dialog_content = "¡N-No, gracias, Su Señoría! ¡Estamos más que dispuestos a consentir!",
  ui_story_5043_50431501_85_dialog_content = "Bien. Eso solo deja un veredicto final para pasar.",
  ui_story_5043_50431501_86_dialog_content = "¿Puede el testigo, Toto, acercarse al estrado?",
  ui_story_5043_50431501_87_dialog_content = "¡Estoy aquí, Su Señoría!",
  ui_story_5043_50431501_88_dialog_content = "¡Ay, Totó!",
  ui_story_5043_50431501_89_dialog_content = "(¡Vaya! ¿Cuándo consiguió Toto ese atuendo?)",
  ui_story_5043_50431501_90_dialog_content = "(Se ve tan refinado. ¡Combina perfectamente con el resto de Lumopolis!)",
  ui_story_5043_50431501_91_dialog_content = "Sin embargo, como víctima en este caso, estabas dispuesto a ayudar a los aurorianos a buscar justicia. Por eso, debo felicitarte.",
  ui_story_5043_50431501_92_dialog_content = "Sin embargo, el delito de perjurio no se tolera a la ligera aquí en el Salón de Justicia.",
  ui_story_5043_50431501_93_dialog_content = "Como cómplice de la estrategia del juez Leyn, es igualmente culpable de este delito.",
  ui_story_5043_50431501_94_dialog_content = "Yo... entiendo...",
  ui_story_5043_50431501_95_dialog_content = "Como juez superior, su castigo será:",
  ui_story_5043_50431501_96_dialog_content = "... discúlpate con Schwab.",
  ui_story_5043_50431501_97_dialog_content = "¿Cómo?",
  ui_story_5043_50431501_98_dialog_content = "¿Quieres que nos disculpemos? ¿Eso es todo?",
  ui_story_5043_50431501_99_dialog_content = "Tu acto de perjurio también fue una afrenta a su honor como juez del Salón de Justicia, así que recuerda mostrar al menos un mínimo de sinceridad cuando te disculpes.",
  ui_story_5043_50431501_100_dialog_content = "Y con eso, todos los castigos relacionados con este caso han sido dispensados.",
  ui_story_5043_50431501_101_dialog_content = "¡El caso de las Decapitaciones de Estatuas en Serie ya está cerrado! ¡Se suspende la sesión!",
  ui_story_5043_50431501_102_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5043_50431501_103_dialog_content = "<color=#e8d9bb> Unos días después...</color>",
  ui_story_5043_50431501_104_dialog_content = "Ejem, aquí están los detalles de mis viajes en Longzhou de hace unos meses.",
  ui_story_5043_50431501_105_dialog_content = "Muy bien. Gracias, PlayerName.",
  ui_story_5043_50431501_106_dialog_content = "Mientras el equilibrio de poder cambia en el mundo que nos rodea, la postura de Lumopolis nunca cambiará.",
  ui_story_5043_50431501_107_dialog_content = "Rezo para que Eraveil continúe manteniendo relaciones amistosas con nuestra bella ciudad.",
  ui_story_5043_50431501_108_dialog_content = "Rezo para que tú también sientas lo mismo, mi joven amigo.",
  ui_story_5043_50431501_109_dialog_content = "O-Claro Señor Schwartz! ¡Siempre estoy feliz de ayudar cuando se trata de hacer las paces con los demás!",
  ui_story_5043_50431501_110_dialog_content = "Estoy encantado de escuchar eso.",
  ui_story_5043_50431501_111_dialog_content = "(Uf... ¡Me alegro de que finalmente haya terminado!)",
  ui_story_5043_50431501_112_dialog_content = "Sabes, puedes ser todo un diplomático cuando te lo propones, PlayerName.",
  ui_story_5043_50431501_113_dialog_content = "Jejejeje, ¿tú crees? Para ser honesto, todavía me siento un poco nervioso.",
  ui_story_5043_50431501_114_dialog_content = "Esto concluye nuestra reunión de hoy. ¿Hay más preguntas?",
  ui_story_5043_50431501_115_dialog_content = "El Salón de Justicia no tiene nada más que informar.",
  ui_story_5043_50431501_116_dialog_content = "Duque Otón?",
  ui_story_5043_50431501_117_dialog_content = "Hmph, mis piernas están empezando a cansarse de tanto estar sentada.",
  ui_story_5043_50431501_118_dialog_content = "Muy bien entonces. Gracias a todos de nuevo. Eres libre de irte ahora.",
  ui_story_5043_50431501_119_dialog_content = "(Todavía no, hay una última cosa que necesito mencionar mientras los representantes del Salón de Justicia y el Consejo de Ancianos todavía están aquí).",
  ui_story_5043_50431501_120_dialog_content = "(Aparte de los Eclipsites y las multitudes incontrolables de personas, otra fiesta en Lumopolis ha estado sembrando discordia recientemente).",
  ui_story_5043_50431501_121_dialog_content = "(¡Como Capitán de la Guardia de Lumopolis Gardens, tengo el deber de decírselo al Consejo de Ancianos!)",
  ui_story_5043_50431501_122_dialog_content = "Padre, Duque Otto... Un momento de su tiempo, por favor.",
  ui_story_5043_50431501_123_dialog_content = "Debo decir, Señor Schwartz, Lumopolis Gardens ha estado manejando todas las emergencias recientes con bastante eficacia.",
  ui_story_5043_50431501_124_dialog_content = "Me sorprendió bastante ver lo bien que trabajan con la gente de Lumopolis.",
  ui_story_5043_50431501_125_dialog_content = "Jaja, tus elogios son demasiado amables, duque Otto. Naturalmente, debemos gran parte de nuestro éxito al apoyo del Consejo de Ancianos.",
  ui_story_5043_50431501_126_dialog_content = "Sin su ayuda en la lucha contra los Eclipsites, los Guardias de Lumopolis Gardens no serían capaces de abordar las necesidades de nuestra ciudad.",
  ui_story_5043_50431501_127_dialog_content = "Qué es, Carleen?",
  ui_story_5043_50431501_128_dialog_content = "...",
  ui_story_5043_50431501_129_dialog_content = "Ah, no digas más, milady. No deseo entrometerme en una conversación entre padre e hija. Buen día.",
  ui_story_5043_50431501_130_dialog_content = "Mi señor, supongo que está al tanto de lo que hicieron los guardias del Consejo de Ancianos durante el Día de la Corona de Luna, ¿no?",
  ui_story_5043_50431501_131_dialog_content = "Mucho más consciente de lo que piensas, Carleen.",
  ui_story_5043_50431501_132_dialog_content = "En el último año, se ha mostrado más tranquilo y valiente que nunca.",
  ui_story_5043_50431501_133_dialog_content = "Sin embargo, abordar cuestiones políticas como estas requiere algo más que valentía.",
  ui_story_5043_50431501_134_dialog_content = "Cuando mi trabajo actual esté completo, haré arreglos para que todos en los Jardines de Lumopolis tengan tiempo de vacaciones.",
  ui_story_5043_50431501_135_dialog_content = "Eso no será necesario, pero gracias, Padre.",
  ui_story_5043_50431501_136_dialog_content = "Vamos, PlayerName.",
  ui_story_5043_50431501_137_dialog_content = "<color=#e8d9bb>¡Estallido! ¡Estallido! ¡Estallido!</color>",
  ui_story_5043_50431501_138_dialog_content = "Felicitaciones por un informe de trabajo exitoso, PlayerName!!!",
  ui_story_5043_50431501_139_dialog_content = "Lo supimos en el momento en que vimos al Juez Jefe Irridon ¡Sal de la sala de conferencias!",
  ui_story_5043_50431501_140_dialog_content = "Estos petardos sobraron de cuando se los dieron a Byron para sus estatuas.",
  ui_story_5043_50431501_141_dialog_content = "No puedo dejar que se desperdicien, ¿verdad?",
  ui_story_5043_50431501_142_dialog_content = "¿Qué pasa? ¿Demasiado sorprendido para hablar?",
  ui_story_5043_50431501_143_dialog_content = "Anímate, ¿no? Eso también va para ti, señora. Carleen!",
  ui_story_5043_50431501_144_dialog_content = "Felicitaciones por un trabajo bien hecho, PlayerName.",
  ui_story_5043_50431501_145_dialog_content = "Guau... ¡Gracias a todos!",
  ui_story_5043_50431501_146_dialog_content = "Eres todo tan...",
  ui_story_5043_50431501_147_dialog_content = "Suspiro, ¿qué se supone que debemos hacer contigo?",
  ui_story_5043_50431501_148_dialog_content = "Perdóname por estropear la diversión a todos. Pero el trabajo del Salón de Justicia aún no está terminado.",
  ui_story_5043_50431501_149_dialog_content = "Su ayuda también sería muy apreciada, señora. Carleen.",
  ui_story_5043_50431501_150_dialog_content = "Este asunto requiere la cooperación de alguien de Lumopolis Gardens.",
  ui_story_5043_50431501_151_dialog_content = "<color=#e8d9bb>El Salón de la Justicia, Jardines de Lumopolis</color>",
  ui_story_5043_50431501_152_dialog_content = "Comprendo.",
  ui_story_5043_50431501_153_dialog_content = "Entonces, a pesar de la disolución de la División de Romance, aún quedan numerosos casos por resolver.",
  ui_story_5043_50431501_154_dialog_content = "El Salón de Justicia sigue tan diligente como siempre, Juez Jefe.",
  ui_story_5043_50431501_155_dialog_content = "¡Guau, solo mira todos estos archivos! Estaremos aquí durante semanas tratando de leerlos todos...",
  ui_story_5043_50431501_156_dialog_content = "Bueno, entonces, estoy contando con—",
  ui_story_5043_50431501_157_dialog_content = "Sabemos...",
  ui_story_5043_50431501_158_dialog_content = "Una última cosa, señora Carleen. Si bien estos casos pueden parecer simples disputas entre amantes a primera vista...",
  ui_story_5043_50431501_159_dialog_content = "Una investigación más profunda de sus contenidos revela rápidamente una miríada de problemas que afectan a Lumopolis a un nivel fundamental y social.",
  ui_story_5043_50431501_160_dialog_content = "Al leerlos, obtuve una gran comprensión de los pensamientos y motivos de quienes viven en Lumopolis Courtyard y Lower Lumopolis. Fue una experiencia sin precedentes para mí.",
  ui_story_5043_50431501_161_dialog_content = "Sus diversas interpretaciones del amor y la fe... Me dieron mucho que pensar.",
  ui_story_5043_50431501_162_dialog_content = "Creo que comprender estos casos es clave para revisar nuestras leyes en beneficio de Lumopolis en su conjunto.",
  ui_story_5043_50431501_163_dialog_content = "Cuando llegue ese momento, rezo para que el Salón de Justicia tenga el apoyo del Señor de la Ciudad, así como el suyo propio.",
  ui_story_5043_50431501_164_dialog_content = "En resumen, creo que este trabajo es esencial para asegurar un futuro brillante y próspero para Lumopolis.",
  ui_story_5043_50431501_165_dialog_content = "Muy bien, estoy de acuerdo con tu petición.",
  ui_story_5043_50431501_166_dialog_content = "Después de todo, Irridon... No eres el único que se siente así.",
  ui_story_5043_50431501_167_dialog_content = "Debes sentirte mucho más feliz ahora, ¿verdad? Carleen?",
  ui_story_5043_50431501_168_dialog_content = "¿Oh? ¿Es tan obvio para ti?",
  ui_story_5043_50431501_169_dialog_content = "Honestamente, estoy un poco sorprendido de lo rápido que las calles han vuelto a la normalidad.",
  ui_story_5043_50431501_170_dialog_content = "Así como así, los puestos y los desfiles se han ido, y la luna ya no está flotando en lo alto.",
  ui_story_5043_50431501_171_dialog_content = "¿Es realmente tan sorprendente para ti, Leyn? Somos nobles, después de todo.",
  ui_story_5043_50431501_172_dialog_content = "Los tiempos y las tendencias siempre están cambiando en Lumopolis. ¿Cómo podríamos permitirnos atrasarnos en las cosas más recientes?",
  ui_story_5043_50431501_173_dialog_content = "¡Véanlo ustedes mismos!",
  ui_story_5043_50431501_174_dialog_content = "¿Eh? ¿No son esos guantes iguales a los míos?",
  ui_story_5043_50431501_175_dialog_content = "Sí, pero recientemente se han convertido en el artículo de moda más popular del mercado. Ya se ha visto a miembros de la nobleza usándolos en varias ocasiones sociales.",
  ui_story_5043_50431501_176_dialog_content = "Son un poco gruesos para mi gusto, ¡pero eso no me impidió comprar siete pares!",
  ui_story_5043_50431501_177_dialog_content = "Qué ridículamente frívolo.",
  ui_story_5043_50431501_178_dialog_content = "Exactamente lo que esperarías de un niño rico...",
  ui_story_5043_50431501_179_dialog_content = "¡Hmph! Ignoren a estos filisteos, Tina. Dime, ¿cómo se siente ser el creador de tendencias de la última moda de Lumopolis?",
  ui_story_5043_50431501_180_dialog_content = "Ah, ¿y cómo van las cosas con Toto? ¿Ya encontraste una manera de mantenerlo?",
  ui_story_5043_50431501_181_dialog_content = "Algo así sería tabú aquí en Lumopolis... Pero eso es lo que lo hace aún más emocionante, ¿no?",
  ui_story_5043_50431501_182_dialog_content = "A-En realidad, todos... Le pedí a Toto que se encontrara conmigo aquí hoy.",
  ui_story_5043_50431501_183_dialog_content = "De esa manera, podría decir <color=#FFB400>adiós</color> a él.",
  ui_story_5043_50431501_184_dialog_content = "¡¿Qué?!",
  ui_story_5043_50431501_185_dialog_content = "Pero ¿por qué tan pronto? ¡No tenía idea de que tu amabilidad hacia él pudiera ser tan efímera!",
  ui_story_5043_50431501_186_dialog_content = "¡E-Eso no es todo! ¡En todo caso, es precisamente porque me preocupo mucho por el dulce pequeño!",
  ui_story_5043_50431501_187_dialog_content = "Los eclipses han sido temidos y odiados desde que cualquiera puede recordar, ¡pero Toto no es como los demás!",
  ui_story_5043_50431501_188_dialog_content = "Aun así, no todo el mundo estaría dispuesto a ver las cosas así, y mucho menos a aceptarlas.",
  ui_story_5043_50431501_189_dialog_content = "Si insistía en quedarme aquí en Lumopolis con él, le haría la vida mucho más difícil.",
  ui_story_5043_50431501_190_dialog_content = "Estoy seguro de que ha estado más asustado que feliz en su último mes viviendo aquí.",
  ui_story_5043_50431501_191_dialog_content = "... ¿Mmm?",
  ui_story_5043_50431501_192_dialog_content = "Em...",
  ui_story_5043_50431501_193_dialog_content = "¿Por qué te escondes ahí, Toto? ¡Ven aquí!",
  ui_story_5043_50431501_194_dialog_content = "T-ustedes están todos aquí...",
  ui_story_5043_50431501_X194_dialog_content = "¿¡Te cambiaste de ropa!?",
  ui_story_5043_50431501_X195_dialog_content = "¡Te ves tan refinado que combinas a la perfección con el resto de Lumopolis!",
  ui_story_5043_50431501_X196_dialog_content = "Cierto... Hoy es un día importante, después de todo, así que quería vestirme para la ocasión.",
  ui_story_5043_50431501_195_dialog_content = "En realidad, vine a despedirme también.",
  ui_story_5043_50431501_196_dialog_content = "Así que planeas salir a la carretera de nuevo, ¿eh?",
  ui_story_5043_50431501_197_dialog_content = "E-Eso es correcto, pero no en la forma en que podrías estar pensando.",
  ui_story_5043_50431501_198_dialog_content = "Mis últimos días en Lumopolis han estado llenos de peligro y terror.",
  ui_story_5043_50431501_199_dialog_content = "Pero también han sido algunos de los días más felices de mi vida.",
  ui_story_5043_50431501_200_dialog_content = "Eso es porque los conocí a todos ustedes.",
  ui_story_5043_50431501_201_dialog_content = "E-Especialmente tú, Tina.",
  ui_story_5043_50431501_202_dialog_content = "Gracias, Toto.",
  ui_story_5043_50431501_203_dialog_content = "E-Fuiste el primer Auroriano en mostrarme bondad incondicional.",
  ui_story_5043_50431501_204_dialog_content = "Es algo que apreciaré por el resto de mi vida.",
  ui_story_5043_50431501_205_dialog_content = "(Amabilidad incondicional, eh...)",
  ui_story_5043_50431501_206_dialog_content = "(Sé cómo se siente. Realmente es algo precioso.)",
  ui_story_5043_50431501_207_dialog_content = "... La mejor de las suertes en tus viajes, Toto.",
  ui_story_5043_50431501_208_dialog_content = "Espero que tengamos la oportunidad de encontrarnos de nuevo algún día, mi amigo.",
  ui_story_5043_50431501_209_dialog_content = "¡Oh espera! Antes de que te vayas, tengo algo que siempre quise darte.",
  ui_story_5043_50431501_210_dialog_content = "Aquí, es un lote de galletas recién horneadas. Seguro que el camino que tienes por delante será largo. ¡Así que espero que esto haga que tu viaje sea un poco más fácil!",
  ui_story_5043_50431501_211_dialog_content = "Sniff... G-Gracias... Muchas gracias, Tina...",
  ui_story_5043_50431501_212_dialog_content = "¡Voy a atesorar cada uno de ellos!",
  ui_story_5043_50431501_213_dialog_content = "Jajajaja! Simplemente no los atesores demasiado, ¿de acuerdo? ¡Después de todo, están hechos para comer!",
  ui_story_5043_50431501_214_dialog_content = "Deberías irte ahora.",
  ui_story_5043_50431501_215_dialog_content = "Es posible que el sol nunca se ponga en Lumopolis, pero ese no es necesariamente el caso para el resto del mundo.",
  ui_story_5043_50431501_216_dialog_content = "R-Bien, entonces... ¡Me iré ahora!",
  ui_story_5043_50431501_217_dialog_content = "¡¡¡Adiós a todos!!!",
  ui_story_5043_50431501_218_dialog_content = "Adiós, Toto!!!",
  ui_story_5043_50431501_219_dialog_content = "¡Y así, nuestro pequeño héroe parte una vez más! ♪",
  ui_story_5043_50431501_220_dialog_content = "¡Pero esta vez, se va con un regalo de sus amigos! ♪",
  ui_story_5043_50431501_221_dialog_content = "El aroma de las golosinas horneadas flota detrás de él cuando se va ♪",
  ui_story_5043_50431501_222_dialog_content = "¡Y hacia los cielos de Lumopolis con la brisa de la mañana! ♪"
}
return config
